% ------------------------------------------------------------------------------
% This tool is a stand-alone version of the "nc_create_synthetic_profile" tool
% used at the Coriolis GDAC to generate mono-cycle synthetic profile (S-PROF)
% files (from C and B mono-cycle (C-PROF and B-PROF) files).
% See http://doi.org/10.13155/55637 for details.
%
% SYNTAX :
%  create_mono_cycle_synthetic_profile(varargin)
%
% INPUT PARAMETERS :
%   varargin :
%      - should be provided in pairs ('param_name','param_value')
%      - 'param_name' value is not case sensitive
%   'param_name' parameter values are (all mandatory)
%      - 'floatWmo'      : the WMO number of the float to process
%      - 'inputDirName'  : the top directory of input (C-PROF, B-PROF and META)
%                          NetCDF files
%      - 'outputDirName' : the top directory of output S-PROF generated files
%                          (should exist)
%
% OUTPUT PARAMETERS :
%
% EXAMPLE :
%    create_mono_cycle_synthetic_profile('floatWmo', '7902334', ...
%       'inputDirName', 'C:/Users/jprannou/DATA/DAC/Coriolis', ...
%       'outputDirName', 'C:/Users/jprannou/DATA/OUT')
%
% SEE ALSO :
% AUTHOR : Jean-Philippe Rannou (Capgemini) (jean.philippe.rannou@partenaire-exterieur.ifremer.fr)
% ------------------------------------------------------------------------------
% RELEASES :
%   02/09/2026 - RNU - V 1.20: creation (from the current version of the
%                              Coriolis tool).
% ------------------------------------------------------------------------------
function create_mono_cycle_synthetic_profile(varargin)

% input parameters
global g_cocs_mono_sa_floatNumStr;
global g_cocs_mono_sa_inputDirName;
global g_cocs_mono_sa_outputDirName;

% program version
global g_cocs_mono_sa_createMonoCycleSyntheticProfileVersion;
g_cocs_mono_sa_createMonoCycleSyntheticProfileVersion = '1.20 (version 12.05.2025 for ARGO_simplified_profile)';

% start date of the run
global g_cocs_mono_sa_currentDate;
g_cocs_mono_sa_currentDate = datestr(now_utc, 'yyyymmddHHMMSS');


% default values initialization
init_default_values;

% get input parameters
inputError = parse_input_param(varargin);

if (~inputError)

   floatInputDir = [g_cocs_mono_sa_inputDirName '/' g_cocs_mono_sa_floatNumStr];
   if ~(exist(floatInputDir, 'dir') == 7)
      fprintf('ERROR: Float input directory not found: %s\n', floatInputDir);
      return
   end

   process_one_float(floatInputDir, g_cocs_mono_sa_outputDirName);
end

return

% ------------------------------------------------------------------------------
% Parse input parameters.
%
% SYNTAX :
%  [o_inputError] = parse_input_param(a_varargin)
%
% INPUT PARAMETERS :
%   a_varargin : input parameters
%
% OUTPUT PARAMETERS :
%   o_inputError : input error flag
%
% EXAMPLES :
%
% SEE ALSO :
% AUTHOR : Jean-Philippe Rannou (Capgemini) (jean.philippe.rannou@partenaire-exterieur.ifremer.fr)
% ------------------------------------------------------------------------------
% RELEASES :
%   02/09/2026 - RNU - creation
% ------------------------------------------------------------------------------
function [o_inputError] = parse_input_param(a_varargin)

% output parameters initialization
o_inputError = 0;

% input parameters
global g_cocs_mono_sa_floatNum;
global g_cocs_mono_sa_floatNumStr;
global g_cocs_mono_sa_inputDirName;
global g_cocs_mono_sa_outputDirName;

g_cocs_mono_sa_floatNum = '';
g_cocs_mono_sa_floatNumStr = '';
g_cocs_mono_sa_inputDirName = '';
g_cocs_mono_sa_outputDirName = '';


% ignore empty input parameters
idDel = [];
for id = 1:length(a_varargin)
   if (isempty(a_varargin{id}))
      idDel = [idDel id];
   end
end
a_varargin(idDel) = [];

% check input parameters
if (~isempty(a_varargin))
   if (rem(length(a_varargin), 2) ~= 0)
      fprintf('ERROR: expecting an even number of input arguments (e.g. (''argument_name'', ''argument_value'') - exit\n');
      print_help;
      o_inputError = 1;
      return
   else
      for id = 1:2:length(a_varargin)
         if (strcmpi(a_varargin{id}, 'floatWmo'))
            g_cocs_mono_sa_floatNumStr = a_varargin{id+1};
         elseif (strcmpi(a_varargin{id}, 'inputDirName'))
            g_cocs_mono_sa_inputDirName = a_varargin{id+1};
         elseif (strcmpi(a_varargin{id}, 'outputDirName'))
            g_cocs_mono_sa_outputDirName = a_varargin{id+1};
         else
            fprintf('WARNING: unexpected input argument (''%s'') - ignored\n', a_varargin{id});
         end
      end
   end
end

% check that mandatory parameters are provided
if (isempty(g_cocs_mono_sa_floatNumStr))
   fprintf('ERROR: ''floatWmo'' input parameter is mandatory\n');
   o_inputError = 1;
end
if (isempty(g_cocs_mono_sa_inputDirName))
   fprintf('ERROR: ''inputDirName'' input parameter is mandatory\n');
   o_inputError = 1;
end
if (isempty(g_cocs_mono_sa_outputDirName))
   fprintf('ERROR: ''outputDirName'' input parameter is mandatory\n');
   o_inputError = 1;
end
if (o_inputError)
   print_help;
   return
end

g_cocs_mono_sa_floatNum = str2double(g_cocs_mono_sa_floatNumStr);
if (isnan(g_cocs_mono_sa_floatNum))
   fprintf('ERROR: ''floatWmo'' input parameter should be convertible into a number\n');
   o_inputError = 1;
end
if ~(exist(g_cocs_mono_sa_inputDirName, 'dir') == 7)
   fprintf('ERROR: Input directory not found: %s\n', g_cocs_mono_sa_inputDirName);
   o_inputError = 1;
end
if ~(exist(g_cocs_mono_sa_outputDirName, 'dir') == 7)
   fprintf('ERROR: Output directory not found: %s\n', g_cocs_mono_sa_outputDirName);
   o_inputError = 1;
end
if (o_inputError)
   return
end

fprintf('INPUT PARAMETERS\n');
fprintf('floatWmo      : ''%s''\n', g_cocs_mono_sa_floatNumStr);
fprintf('inputDirName  : ''%s''\n', g_cocs_mono_sa_inputDirName);
fprintf('outputDirName : ''%s''\n', g_cocs_mono_sa_outputDirName);
fprintf('\n');

return

% ------------------------------------------------------------------------------
% Display help on input parameters.
%
% SYNTAX :
%   print_help
%
% INPUT PARAMETERS :
%
% OUTPUT PARAMETERS :
%
% EXAMPLES :
%
% SEE ALSO :
% AUTHOR : Jean-Philippe Rannou (Capgemini) (jean.philippe.rannou@partenaire-exterieur.ifremer.fr)
% ------------------------------------------------------------------------------
% RELEASES :
%   02/09/2026 - RNU - creation
% ------------------------------------------------------------------------------
function print_help

fprintf('\nExpected syntax:\n');
fprintf('   create_mono_cycle_synthetic_profile(varargin)\n');
fprintf('INPUT PARAMETERS :\n');
fprintf('   varargin :\n');
fprintf('      - should be provided in pairs (''param_name'',''param_value'')\n');
fprintf('      - ''param_name'' value is not case sensitive\n');
fprintf('   ''param_name'' parameter values are (all mandatory)\n');
fprintf('      - ''floatWmo''      : the WMO number of the float to process\n');
fprintf('      - ''inputDirName''  : the top directory of input (C-PROF, B-PROF and META) NetCDF files\n');
fprintf('      - ''outputDirName'' : the top directory of output S-PROF generated files (should exist)\n');
fprintf('EXAMPLE :\n');
fprintf('   create_mono_cycle_synthetic_profile(''floatWmo'', ''7902334'', ''inputDirName'', ''C:/Users/jprannou/DATA/DAC/Coriolis'', ''outputDirName'', ''C:/Users/jprannou/DATA/OUT'')\n');

return

% ------------------------------------------------------------------------------
% Generate all synthetic profiles for a given float.
%
% SYNTAX :
%  process_one_float(a_floatInputDir, a_outputDir)
%
% INPUT PARAMETERS :
%   a_floatInputDir : float input data directory
%   a_outputDir     : output directory
%
% OUTPUT PARAMETERS :
%
% EXAMPLES :
%
% SEE ALSO :
% AUTHOR : Jean-Philippe Rannou (Capgemini) (jean.philippe.rannou@partenaire-exterieur.ifremer.fr)
% ------------------------------------------------------------------------------
% RELEASES :
%   06/08/2018 - RNU - creation
% ------------------------------------------------------------------------------
function process_one_float(a_floatInputDir, a_outputDir)

% current float and cycle identification
global g_cocs_mono_sa_floatNum;
global g_cocs_mono_sa_floatNumStr;
global g_cocs_mono_sa_cycleNum;
global g_cocs_mono_sa_cycleDir;


% META data file
metaFileName = [a_floatInputDir '/' g_cocs_mono_sa_floatNumStr '_meta.nc'];
if ~(exist(metaFileName, 'file') == 2)
   fprintf('ERROR: META file not found: %s\n', metaFileName);
   return
end

% create the list of available cycle numbers (from PROF files)
profileDir = [a_floatInputDir '/profiles'];
files = dir([profileDir '/' '*' g_cocs_mono_sa_floatNumStr '_' '*.nc']);
cyNumList = [];
bgcFloatFlag = 0;
for idFile = 1:length(files)
   fileName = files(idFile).name;
   if (fileName(1) == 'B')
      bgcFloatFlag = 1;
   end
   if (ismember(fileName(1), 'DRB'))
      idF = strfind(fileName, g_cocs_mono_sa_floatNumStr);
      cyNumStr = fileName(idF+length(g_cocs_mono_sa_floatNumStr)+1:end-3);
      if (cyNumStr(end) == 'D')
         cyNumStr(end) = [];
      end
      cyNumList = [cyNumList, str2num(cyNumStr)];
   end
end
cyNumList = unique(cyNumList);

% process PROF files
for idCy = 1:length(cyNumList)

   g_cocs_mono_sa_cycleNum = cyNumList(idCy);

   % process descending and ascending profiles
   for idDir = 1:2

      if (idDir == 1)
         g_cocs_mono_sa_cycleDir = 'D';
      else
         g_cocs_mono_sa_cycleDir = '';
      end

      cProfFileName = '';
      bProfFileName = '';
      if (exist([profileDir '/' sprintf('D%d_%03d%c.nc', g_cocs_mono_sa_floatNum, g_cocs_mono_sa_cycleNum, g_cocs_mono_sa_cycleDir)], 'file') == 2)
         cProfFileName = [profileDir '/' sprintf('D%d_%03d%c.nc', g_cocs_mono_sa_floatNum, g_cocs_mono_sa_cycleNum, g_cocs_mono_sa_cycleDir)];
      elseif (exist([profileDir '/' sprintf('R%d_%03d%c.nc', g_cocs_mono_sa_floatNum, g_cocs_mono_sa_cycleNum, g_cocs_mono_sa_cycleDir)], 'file') == 2)
         cProfFileName = [profileDir '/' sprintf('R%d_%03d%c.nc', g_cocs_mono_sa_floatNum, g_cocs_mono_sa_cycleNum, g_cocs_mono_sa_cycleDir)];
      end
      if (exist([profileDir '/' sprintf('BD%d_%03d%c.nc', g_cocs_mono_sa_floatNum, g_cocs_mono_sa_cycleNum, g_cocs_mono_sa_cycleDir)], 'file') == 2)
         bProfFileName = [profileDir '/' sprintf('BD%d_%03d%c.nc', g_cocs_mono_sa_floatNum, g_cocs_mono_sa_cycleNum, g_cocs_mono_sa_cycleDir)];
      elseif (exist([profileDir '/' sprintf('BR%d_%03d%c.nc', g_cocs_mono_sa_floatNum, g_cocs_mono_sa_cycleNum, g_cocs_mono_sa_cycleDir)], 'file') == 2)
         bProfFileName = [profileDir '/' sprintf('BR%d_%03d%c.nc', g_cocs_mono_sa_floatNum, g_cocs_mono_sa_cycleNum, g_cocs_mono_sa_cycleDir)];
      end

      if (~isempty(cProfFileName) || ~isempty(bProfFileName))

         fprintf('   %02d/%02d: Float #%d Cycle #%d%c - generating mono_cycle S-PROF file\n', ...
            idCy, length(cyNumList), g_cocs_mono_sa_floatNum, g_cocs_mono_sa_cycleNum, g_cocs_mono_sa_cycleDir);

         % generate S-PROF file
         nc_create_synthetic_profile_( ...
            cProfFileName, bProfFileName, metaFileName, ...
            a_outputDir, bgcFloatFlag);
      end
   end
end

fprintf('done\n');

return

% ------------------------------------------------------------------------------
% Generate one synthetic profile from one C and one B mono-cycle files.
%
% SYNTAX :
%  nc_create_synthetic_profile_( ...
%    a_cProfFileName, a_bProfFileName, a_metaFileName, ...
%    a_outputDir, a_bgcFloatFlag)
%
% INPUT PARAMETERS :
%   a_cProfFileName : input C prof file path name
%   a_bProfFileName : input B prof file path name
%   a_metaFileName  : input meta file path name
%   a_outputDir     : output S prof file directory
%   a_bgcFloatFlag  : 1 if it is a BGC float, 0 otherwise
%
% OUTPUT PARAMETERS :
%
% EXAMPLES :
%
% SEE ALSO :
% AUTHOR : Jean-Philippe Rannou (Capgemini) (jean.philippe.rannou@partenaire-exterieur.ifremer.fr)
% ------------------------------------------------------------------------------
% RELEASES :
%   06/15/2018 - RNU - creation
% ------------------------------------------------------------------------------
function nc_create_synthetic_profile_( ...
   a_cProfFileName, a_bProfFileName, a_metaFileName, ...
   a_outputDir, a_bgcFloatFlag)

% input parameters
global g_cocs_mono_sa_floatNum;
global g_cocs_mono_sa_floatNumStr;


% retrieve PROF data
profDataStruct = get_prof_data(a_cProfFileName, a_bProfFileName);

% process PROF data
syntProfDataStruct = [];
if (~isempty(profDataStruct))
   syntProfDataStruct = process_prof_data(profDataStruct, ...
      a_cProfFileName, a_bProfFileName, a_metaFileName, a_bgcFloatFlag);
end

% create S-PROF file
if (~isempty(syntProfDataStruct))

   % create output file directory
   outputFloatDirName = [a_outputDir '/' g_cocs_mono_sa_floatNumStr '/profiles/'];
   if ~(exist(outputFloatDirName, 'dir') == 7)
      mkdir(outputFloatDirName);
   end

   create_synthetic_mono_cycle_file(g_cocs_mono_sa_floatNum, syntProfDataStruct, outputFloatDirName);
end

return

% ------------------------------------------------------------------------------
% Retrieve data from PROF file.
%
% SYNTAX :
%  [o_profData] = get_prof_data(a_cProfFileName, a_bProfFileName)
%
% INPUT PARAMETERS :
%   a_cProfFileName : C PROF file path name
%   a_bProfFileName : B PROF file path name
%
% OUTPUT PARAMETERS :
%   o_profData : retrieved data
%
% EXAMPLES :
%
% SEE ALSO :
% AUTHOR : Jean-Philippe Rannou (Capgemini) (jean.philippe.rannou@partenaire-exterieur.ifremer.fr)
% ------------------------------------------------------------------------------
% RELEASES :
%   06/15/2018 - RNU - creation
% ------------------------------------------------------------------------------
function [o_profData] = get_prof_data(a_cProfFileName, a_bProfFileName)

% output parameter initialization
o_profData = [];

% current float and cycle identification
global g_cocs_mono_sa_floatNum;
global g_cocs_mono_sa_cycleNum;
global g_cocs_mono_sa_cycleDir;


onlyCFileFlag = 0;
onlyBFileFlag = 0;
if (isempty(a_cProfFileName))
   onlyBFileFlag = 1;
end
if (isempty(a_bProfFileName))
   onlyCFileFlag = 1;
end

% retrieve PROF data from C and B files
profDataTabC = [];
profDataTabB = [];
for idType= 1:2
   if (idType == 1)
      profFilePathName = a_cProfFileName;
   else
      profFilePathName = a_bProfFileName;
   end

   if (isempty(profFilePathName))
      continue
   end

   % retrieve information from PROF file
   wantedVars = [ ...
      {'FORMAT_VERSION'} ...
      {'STATION_PARAMETERS'} ...
      ];
   [profData1] = get_data_from_nc_file(profFilePathName, wantedVars);

   formatVersion = deblank(get_data_from_name('FORMAT_VERSION', profData1)');

   % check the PROF file format version
   if (~strcmp(formatVersion, '3.1'))
      fprintf('ERROR: Float #%d Cycle #%d%c: Input PROF file (%s) format version is %s - not used\n', ...
         g_cocs_mono_sa_floatNum, g_cocs_mono_sa_cycleNum, g_cocs_mono_sa_cycleDir, profFilePathName, formatVersion);
      return
   end

   % create the list of parameters to be retrieved from PROF file
   wantedVars = [ ...
      {'HANDBOOK_VERSION'} ...
      {'REFERENCE_DATE_TIME'} ...
      ...
      {'PLATFORM_NUMBER'} ...
      {'PROJECT_NAME'} ...
      {'PI_NAME'} ...
      {'CYCLE_NUMBER'} ...
      {'DIRECTION'} ...
      {'DATA_CENTRE'} ...
      {'DATA_MODE'} ...
      {'PARAMETER_DATA_MODE'} ...
      {'PLATFORM_TYPE'} ...
      {'FLOAT_SERIAL_NO'} ...
      {'FIRMWARE_VERSION'} ...
      {'WMO_INST_TYPE'} ...
      {'JULD'} ...
      {'JULD_QC'} ...
      {'JULD_LOCATION'} ...
      {'LATITUDE'} ...
      {'LONGITUDE'} ...
      {'POSITION_QC'} ...
      {'POSITIONING_SYSTEM'} ...
      {'VERTICAL_SAMPLING_SCHEME'} ...
      {'CONFIG_MISSION_NUMBER'} ...
      {'PARAMETER'} ...
      {'SCIENTIFIC_CALIB_EQUATION'} ...
      {'SCIENTIFIC_CALIB_COEFFICIENT'} ...
      {'SCIENTIFIC_CALIB_COMMENT'} ...
      {'SCIENTIFIC_CALIB_DATE'} ...
      ];

   % add parameter measurements
   stationParameters = get_data_from_name('STATION_PARAMETERS', profData1);
   parameterList = [];
   [~, nParam, nProf] = size(stationParameters);
   for idProf = 1:nProf
      profParamList = [];
      for idParam = 1:nParam
         paramName = deblank(stationParameters(:, idParam, idProf)');
         if (~isempty(paramName))
            paramInfo = get_netcdf_param_attributes_extended(paramName, g_cocs_mono_sa_floatNum);
            if ((paramInfo.paramType == 'c') || (paramInfo.paramType == 'b'))
               profParamList{end+1} = paramName;
               wantedVars = [wantedVars ...
                  {paramName} ...
                  {[paramName '_QC']} ...
                  {[paramName '_ADJUSTED']} ...
                  {[paramName '_ADJUSTED_QC']} ...
                  {[paramName '_ADJUSTED_ERROR']} ...
                  ];
            end
         end
      end
      parameterList = [parameterList; {profParamList}];
   end

   % retrieve information from PROF file
   [profData2] = get_data_from_nc_file(profFilePathName, wantedVars);

   handbookVersion = get_data_from_name('HANDBOOK_VERSION', profData2)';
   referenceDateTime = get_data_from_name('REFERENCE_DATE_TIME', profData2)';
   platformNumber = get_data_from_name('PLATFORM_NUMBER', profData2)';
   projectName = get_data_from_name('PROJECT_NAME', profData2)';
   piName = get_data_from_name('PI_NAME', profData2)';
   cycleNumber = get_data_from_name('CYCLE_NUMBER', profData2)';
   direction = get_data_from_name('DIRECTION', profData2)';
   dataCentre = get_data_from_name('DATA_CENTRE', profData2)';
   dataMode = get_data_from_name('DATA_MODE', profData2)';
   parameterDataMode = get_data_from_name('PARAMETER_DATA_MODE', profData2)';
   platformType = get_data_from_name('PLATFORM_TYPE', profData2)';
   floatSerialNo = get_data_from_name('FLOAT_SERIAL_NO', profData2)';
   firmwareVersion = get_data_from_name('FIRMWARE_VERSION', profData2)';
   wmoInstType = get_data_from_name('WMO_INST_TYPE', profData2)';
   juld = get_data_from_name('JULD', profData2)';
   juldQc = get_data_from_name('JULD_QC', profData2)';
   juldLocation = get_data_from_name('JULD_LOCATION', profData2)';
   latitude = get_data_from_name('LATITUDE', profData2)';
   longitude = get_data_from_name('LONGITUDE', profData2)';
   positionQc = get_data_from_name('POSITION_QC', profData2)';
   positioningSystem = get_data_from_name('POSITIONING_SYSTEM', profData2)';
   verticalSamplingScheme = get_data_from_name('VERTICAL_SAMPLING_SCHEME', profData2)';
   configMissionNumber = get_data_from_name('CONFIG_MISSION_NUMBER', profData2)';
   parameter = get_data_from_name('PARAMETER', profData2);
   scientificCalibEquation = get_data_from_name('SCIENTIFIC_CALIB_EQUATION', profData2);
   scientificCalibCoefficient = get_data_from_name('SCIENTIFIC_CALIB_COEFFICIENT', profData2);
   scientificCalibComment = get_data_from_name('SCIENTIFIC_CALIB_COMMENT', profData2);
   scientificCalibDate = get_data_from_name('SCIENTIFIC_CALIB_DATE', profData2);

   % retrieve information from PROF file
   wantedVarAtts = [ ...
      {'JULD'} {'resolution'} ...
      {'JULD_LOCATION'} {'resolution'} ...
      ];

   [profDataAtt] = get_att_from_nc_file(profFilePathName, wantedVarAtts);

   juldResolution = get_att_from_name('JULD', 'resolution', profDataAtt);
   juldLocationResolution = get_att_from_name('JULD_LOCATION', 'resolution', profDataAtt);

   % store PROF data in dedicated structures
   for idProf = 1:nProf

      % do not consider Bounce cycles (from Ice cycles of APEX APF1 floats)
      vss = strtrim(verticalSamplingScheme(idProf, :));
      if (strncmp(vss, 'Bounce sampling:', length('Bounce sampling:')))
         continue
      end

      profData = get_prof_data_init_struct;

      profData.nProfId = idProf;
      profData.handbookVersion = strtrim(handbookVersion);
      profData.referenceDateTime = strtrim(referenceDateTime);
      profData.platformNumber = strtrim(platformNumber(idProf, :));
      profData.projectName = strtrim(projectName(idProf, :));
      profData.piName = strtrim(piName(idProf, :));
      profData.cycleNumber = cycleNumber(idProf);
      profData.direction = direction(idProf);
      profData.dataCentre = strtrim(dataCentre(idProf, :));
      profData.platformType = strtrim(platformType(idProf, :));
      profData.floatSerialNo = strtrim(floatSerialNo(idProf, :));
      profData.firmwareVersion = strtrim(firmwareVersion(idProf, :));
      profData.wmoInstType = strtrim(wmoInstType(idProf, :));
      profData.juld = juld(idProf);
      profData.juldResolution = juldResolution;
      profData.juldQc = juldQc(idProf);
      profData.juldLocation = juldLocation(idProf);
      profData.juldLocationResolution = juldLocationResolution;
      profData.latitude = latitude(idProf);
      profData.longitude = longitude(idProf);
      profData.positionQc = positionQc(idProf);
      profData.positioningSystem = positioningSystem(idProf, :);
      profData.verticalSamplingScheme = strtrim(verticalSamplingScheme(idProf, :));
      profData.configMissionNumber = configMissionNumber(idProf);

      profParameterList = parameterList{idProf};
      profData.paramList = profParameterList;
      if ((idType == 2) && (onlyBFileFlag == 0))
         idPres = find(strcmp('PRES', profData.paramList) == 1, 1);
         profData.paramList(idPres) = [];
      end

      % array to store SCIENTIFIC_CALIB_* information
      [~, ~, nCalib, ~] = size(parameter);
      sciCalibEquation = cell(1, length(profData.paramList));
      sciCalibCoefficient = cell(1, length(profData.paramList));
      sciCalibComment = cell(1, length(profData.paramList));
      sciCalibDate = cell(1, length(profData.paramList));

      for idParam = 1:length(profParameterList)
         paramName = profParameterList{idParam};
         paramData = get_data_from_name(paramName, profData2)';
         if (strcmp(paramName, 'PRES'))
            profData.presData = paramData(idProf, :)';
         end
         if ((idType == 2) && strcmp(paramName, 'PRES') && (onlyBFileFlag == 0))
            continue
         end
         if (onlyBFileFlag == 0)
            if (idType == 1)
               profData.paramDataMode = [profData.paramDataMode dataMode(idProf)];
            else
               % find N_PARAM index of the current parameter
               nParamId = [];
               for idParamNc = 1:nParam
                  stationParametersParamName = deblank(stationParameters(:, idParamNc, idProf)');
                  if (strcmp(paramName, stationParametersParamName))
                     nParamId = idParamNc;
                     break
                  end
               end
               if (~isempty(deblank(parameterDataMode)))
                  profData.paramDataMode = [profData.paramDataMode parameterDataMode(idProf, nParamId)];
               elseif (dataMode(idProf) == 'R')
                  %                fprintf('WARNING: Float #%d Cycle #%d%c: PARAMETER_DATA_MODE information is missing in input PROF file (%s) - set to ''R'' (as DATA_MODE = ''R'')\n', ...
                  %                   g_cocs_mono_sa_floatNum, g_cocs_mono_sa_cycleNum, g_cocs_mono_sa_cycleDir, profFilePathName);
                  profData.paramDataMode = [profData.paramDataMode 'R'];
               else
                  fprintf('ERROR: Float #%d Cycle #%d%c: PARAMETER_DATA_MODE information is missing in input PROF file (%s) - exit (as DATA_MODE = ''%c'')\n', ...
                     g_cocs_mono_sa_floatNum, g_cocs_mono_sa_cycleNum, g_cocs_mono_sa_cycleDir, profFilePathName, dataMode(idProf));
                  return
               end
            end
         else
            profData.paramDataMode = [profData.paramDataMode dataMode(idProf)];
         end

         % manage SCIENTIFIC_CALIB_* information
         sciCalEquation = cell(1, nCalib);
         sciCalCoefficient = cell(1, nCalib);
         sciCalComment = cell(1, nCalib);
         sciCalDate = cell(1, nCalib);

         % find N_PARAM index of the current parameter
         nParamId = [];
         for idCalib = 1:nCalib
            for idParamNc = 1:nParam
               calibParamName = deblank(parameter(:, idParamNc, idCalib, idProf)');
               if (~isempty(calibParamName))
                  if (strcmp(paramName, calibParamName))
                     nParamId = idParamNc;
                     break
                  end
               end
            end
            if (~isempty(nParamId))
               break
            end
         end
         if (~isempty(nParamId))
            for idCalib2 = 1:nCalib
               sciCalEquation{idCalib2} = deblank(scientificCalibEquation(:, nParamId, idCalib2, idProf)');
               sciCalCoefficient{idCalib2} = deblank(scientificCalibCoefficient(:, nParamId, idCalib2, idProf)');
               sciCalComment{idCalib2} = deblank(scientificCalibComment(:, nParamId, idCalib2, idProf)');
               sciCalDate{idCalib2} = deblank(scientificCalibDate(:, nParamId, idCalib2, idProf)');
            end
         end
         idParam2 = find(strcmp(paramName, profData.paramList) == 1, 1);
         sciCalibEquation{idParam2} = sciCalEquation;
         sciCalibCoefficient{idParam2} = sciCalCoefficient;
         sciCalibComment{idParam2} = sciCalComment;
         sciCalibDate{idParam2} = sciCalDate;
      end
      profData.scientificCalibEquation = sciCalibEquation;
      profData.scientificCalibCoefficient = sciCalibCoefficient;
      profData.scientificCalibComment = sciCalibComment;
      profData.scientificCalibDate = sciCalibDate;

      if (idType == 1)
         profDataTabC = [profDataTabC profData];
      else
         profDataTabB = [profDataTabB profData];
      end
   end
end

% concatenate C and B data
profDataTab = [];
if (~isempty(profDataTabC) && ~isempty(profDataTabB))
   for idProfC = 1:length(profDataTabC)
      profData = profDataTabC(idProfC);
      idProfB = find([profDataTabB.nProfId] == profData.nProfId);
      if (~isempty(idProfB))
         if (length(profData.presData) ~= length(profDataTabB(idProfB).presData))
            fprintf('ERROR: Float #%d Cycle #%d%c: C and B files don''t have the same number of levels (%d vs %d) - files ignored\n', ...
               g_cocs_mono_sa_floatNum, g_cocs_mono_sa_cycleNum, g_cocs_mono_sa_cycleDir, ...
               length(profData.presData), ...
               length(profDataTabB(idProfB).presData));
            return
         end

         if (~any((profData.presData - profDataTabB(idProfB).presData) ~= 0))
            profDataB = profDataTabB(idProfB);
            profData.paramList = [profData.paramList profDataB.paramList];
            profData.paramSensorList = [profData.paramSensorList profDataB.paramSensorList];
            profData.paramDataMode = [profData.paramDataMode profDataB.paramDataMode];
            % N_CALIB of C and B files are not necessarily the same
            nCalibC = 0;
            if (~isempty(profData.scientificCalibEquation))
               nCalibC = length(profData.scientificCalibEquation{1});
            end
            nCalibB = 0;
            if (~isempty(profDataB.scientificCalibEquation))
               nCalibB = length(profDataB.scientificCalibEquation{1});
            end
            if (nCalibC > nCalibB)
               for idParam = 1:length(profDataB.scientificCalibEquation)
                  profDataB.scientificCalibEquation{idParam} = ...
                     cat(2, profDataB.scientificCalibEquation{idParam}, cell(1, nCalibC-nCalibB));
                  profDataB.scientificCalibCoefficient{idParam} = ...
                     cat(2, profDataB.scientificCalibCoefficient{idParam}, cell(1, nCalibC-nCalibB));
                  profDataB.scientificCalibComment{idParam} = ...
                     cat(2, profDataB.scientificCalibComment{idParam}, cell(1, nCalibC-nCalibB));
                  profDataB.scientificCalibDate{idParam} = ...
                     cat(2, profDataB.scientificCalibDate{idParam}, cell(1, nCalibC-nCalibB));
               end
            else
               for idParam = 1:length(profData.scientificCalibEquation)
                  profData.scientificCalibEquation{idParam} = ...
                     cat(2, profData.scientificCalibEquation{idParam}, cell(1, nCalibB-nCalibC));
                  profData.scientificCalibCoefficient{idParam} = ...
                     cat(2, profData.scientificCalibCoefficient{idParam}, cell(1, nCalibB-nCalibC));
                  profData.scientificCalibComment{idParam} = ...
                     cat(2, profData.scientificCalibComment{idParam}, cell(1, nCalibB-nCalibC));
                  profData.scientificCalibDate{idParam} = ...
                     cat(2, profData.scientificCalibDate{idParam}, cell(1, nCalibB-nCalibC));
               end
            end
            profData.scientificCalibEquation = [profData.scientificCalibEquation profDataB.scientificCalibEquation];
            profData.scientificCalibCoefficient = [profData.scientificCalibCoefficient profDataB.scientificCalibCoefficient];
            profData.scientificCalibComment = [profData.scientificCalibComment profDataB.scientificCalibComment];
            profData.scientificCalibDate = [profData.scientificCalibDate profDataB.scientificCalibDate];
            profDataTabB(idProfB) = [];
         else
            fprintf('ERROR: Float #%d Cycle #%d%c: C and B files don''t have the same PRES profile for N_PROF = %d - files ignored\n', ...
               g_cocs_mono_sa_floatNum, g_cocs_mono_sa_cycleNum, g_cocs_mono_sa_cycleDir, profData.nProfId);
            return
         end
      else
         fprintf('ERROR: Float #%d Cycle #%d%c: unable to find N_PROF = %d profile in B file - files ignored\n', ...
            g_cocs_mono_sa_floatNum, g_cocs_mono_sa_cycleNum, g_cocs_mono_sa_cycleDir, profData.nProfId);
         return
      end
      profDataTab = [profDataTab profData];
   end

   if (~isempty(profDataTabB))
      fprintf('ERROR: Float #%d Cycle #%d%c: %d B profiles are not used\n', ...
         g_cocs_mono_sa_floatNum, g_cocs_mono_sa_cycleNum, g_cocs_mono_sa_cycleDir, length(profDataTabB));
   end

elseif (~isempty(profDataTabC))
   profDataTab = profDataTabC;
elseif (~isempty(profDataTabB))
   profDataTab = profDataTabB;
end

% output parameter
o_profData = profDataTab;

return

% ------------------------------------------------------------------------------
% Get the dedicated structure to store PROF information.
%
% SYNTAX :
%  [o_profDataStruct] = get_prof_data_init_struct
%
% INPUT PARAMETERS :
%
% OUTPUT PARAMETERS :
%   o_profDataStruct : PROF data initialized structure
%
% EXAMPLES :
%
% SEE ALSO :
% AUTHOR : Jean-Philippe Rannou (Capgemini) (jean.philippe.rannou@partenaire-exterieur.ifremer.fr)
% ------------------------------------------------------------------------------
% RELEASES :
%   06/15/2018 - RNU - creation
% ------------------------------------------------------------------------------
function [o_profDataStruct] = get_prof_data_init_struct

% output parameters initialization
o_profDataStruct = struct( ...
   'nProfId', [], ...
   'handbookVersion', '', ...
   'referenceDateTime', '', ...
   'platformNumber', '', ...
   'projectName', '', ...
   'piName', '', ...
   'cycleNumber', [], ...
   'direction', '', ...
   'dataCentre', '', ...
   'platformType', '', ...
   'floatSerialNo', '', ...
   'firmwareVersion', '', ...
   'wmoInstType', '', ...
   'juld', [], ...
   'juldResolution', [], ...
   'juldQc', '', ...
   'juldLocation', [], ...
   'juldLocationResolution', [], ...
   'latitude', [], ...
   'longitude', [], ...
   'positionQc', '', ...
   'positioningSystem', '', ...
   'verticalSamplingScheme', '', ...
   'configMissionNumber', [], ...
   ...
   'paramList', [], ...
   'paramSensorList', [], ...
   'paramDataMode', '', ...
   ...
   'presData', [], ...
   'paramData', [], ...
   'paramDataQc', '', ...
   'paramDataAdjusted', [], ...
   'paramDataAdjustedQc', '', ...
   'paramDataAdjustedError', [], ...
   ...
   'scientificCalibEquation', [], ...
   'scientificCalibCoefficient', [], ...
   'scientificCalibComment', [], ...
   'scientificCalibDate', [] ...
   );

return

% ------------------------------------------------------------------------------
% Process PROF data to generate synthetic profile data.
%
% SYNTAX :
%  [o_syntProfData] = process_prof_data(a_profData, ...
%    a_cProfFileName, a_bProfFileName, a_metaFileName, a_bgcFloatFlag)
%
% INPUT PARAMETERS :
%   a_profData      : data retrieved from PROF file(s)
%   a_cProfFileName : input C prof file path name
%   a_bProfFileName : input B prof file path name
%   a_metaFileName  : input meta file path name
%   a_bgcFloatFlag  : 1 if it is a BGC float, 0 otherwise
%
% OUTPUT PARAMETERS :
%   o_syntProfData : synthetic profile data
%
% EXAMPLES :
%
% SEE ALSO :
% AUTHOR : Jean-Philippe Rannou (Capgemini) (jean.philippe.rannou@partenaire-exterieur.ifremer.fr)
% ------------------------------------------------------------------------------
% RELEASES :
%   06/15/2018 - RNU - creation
% ------------------------------------------------------------------------------
function [o_syntProfData] = process_prof_data(a_profData, ...
   a_cProfFileName, a_bProfFileName, a_metaFileName, a_bgcFloatFlag)

% output parameters initialization
o_syntProfData = [];

% QC flag values (char)
global g_decArgo_qcStrDef;

% current float and cycle identification
global g_cocs_mono_sa_floatNum;
global g_cocs_mono_sa_cycleNum;
global g_cocs_mono_sa_cycleDir;


% check input profile consistency
errorFlag = 0;
if (length(unique({a_profData.handbookVersion})) > 1)
   fprintf('ERROR: Float #%d Cycle #%d%c: multiple HANDBOOK_VERSION - file ignored\n', ...
      g_cocs_mono_sa_floatNum, g_cocs_mono_sa_cycleNum, g_cocs_mono_sa_cycleDir);
   errorFlag = 1;
end
if (length(unique({a_profData.referenceDateTime})) > 1)
   fprintf('ERROR: Float #%d Cycle #%d%c: multiple REFERENCE_DATE_TIME - file ignored\n', ...
      g_cocs_mono_sa_floatNum, g_cocs_mono_sa_cycleNum, g_cocs_mono_sa_cycleDir);
   errorFlag = 1;
end
if (length(unique({a_profData.platformNumber})) > 1)
   fprintf('ERROR: Float #%d Cycle #%d%c: multiple PLATFORM_NUMBER - file ignored\n', ...
      g_cocs_mono_sa_floatNum, g_cocs_mono_sa_cycleNum, g_cocs_mono_sa_cycleDir);
   errorFlag = 1;
end
if (length(unique({a_profData.projectName})) > 1)
   fprintf('ERROR: Float #%d Cycle #%d%c: multiple PROJECT_NAME - file ignored\n', ...
      g_cocs_mono_sa_floatNum, g_cocs_mono_sa_cycleNum, g_cocs_mono_sa_cycleDir);
   errorFlag = 1;
end
if (length(unique({a_profData.piName})) > 1)
   fprintf('ERROR: Float #%d Cycle #%d%c: multiple PI_NAME - file ignored\n', ...
      g_cocs_mono_sa_floatNum, g_cocs_mono_sa_cycleNum, g_cocs_mono_sa_cycleDir);
   errorFlag = 1;
end
if (length(unique([a_profData.cycleNumber])) > 1)
   fprintf('ERROR: Float #%d Cycle #%d%c: multiple CYCLE_NUMBER - file ignored\n', ...
      g_cocs_mono_sa_floatNum, g_cocs_mono_sa_cycleNum, g_cocs_mono_sa_cycleDir);
   errorFlag = 1;
end
if (length(unique({a_profData.direction})) > 1)
   fprintf('ERROR: Float #%d Cycle #%d%c: multiple DIRECTION - file ignored\n', ...
      g_cocs_mono_sa_floatNum, g_cocs_mono_sa_cycleNum, g_cocs_mono_sa_cycleDir);
   errorFlag = 1;
end
if (length(unique({a_profData.dataCentre})) > 1)
   fprintf('ERROR: Float #%d Cycle #%d%c: multiple DATA_CENTRE - file ignored\n', ...
      g_cocs_mono_sa_floatNum, g_cocs_mono_sa_cycleNum, g_cocs_mono_sa_cycleDir);
   errorFlag = 1;
end
if (length(unique({a_profData.platformType})) > 1)
   fprintf('ERROR: Float #%d Cycle #%d%c: multiple PLATFORM_TYPE - file ignored\n', ...
      g_cocs_mono_sa_floatNum, g_cocs_mono_sa_cycleNum, g_cocs_mono_sa_cycleDir);
   errorFlag = 1;
end
if (length(unique({a_profData.floatSerialNo})) > 1)
   fprintf('ERROR: Float #%d Cycle #%d%c: multiple FLOAT_SERIAL_NO - file ignored\n', ...
      g_cocs_mono_sa_floatNum, g_cocs_mono_sa_cycleNum, g_cocs_mono_sa_cycleDir);
   errorFlag = 1;
end
if (length(unique({a_profData.firmwareVersion})) > 1)
   fprintf('ERROR: Float #%d Cycle #%d%c: multiple FIRMWARE_VERSION - file ignored\n', ...
      g_cocs_mono_sa_floatNum, g_cocs_mono_sa_cycleNum, g_cocs_mono_sa_cycleDir);
   errorFlag = 1;
end
if (length(unique({a_profData.wmoInstType})) > 1)
   fprintf('ERROR: Float #%d Cycle #%d%c: multiple WMO_INST_TYPE - file ignored\n', ...
      g_cocs_mono_sa_floatNum, g_cocs_mono_sa_cycleNum, g_cocs_mono_sa_cycleDir);
   errorFlag = 1;
end
if (length(unique([a_profData.juld])) > 1)
   fprintf('ERROR: Float #%d Cycle #%d%c: multiple JULD - file ignored\n', ...
      g_cocs_mono_sa_floatNum, g_cocs_mono_sa_cycleNum, g_cocs_mono_sa_cycleDir);
   errorFlag = 1;
end
if (length(unique([a_profData.juldResolution])) > 1)
   fprintf('ERROR: Float #%d Cycle #%d%c: multiple JULD:resolution - file ignored\n', ...
      g_cocs_mono_sa_floatNum, g_cocs_mono_sa_cycleNum, g_cocs_mono_sa_cycleDir);
   errorFlag = 1;
end
if (length(unique({a_profData.juldQc})) > 1)
   fprintf('ERROR: Float #%d Cycle #%d%c: multiple JULD_QC - file ignored\n', ...
      g_cocs_mono_sa_floatNum, g_cocs_mono_sa_cycleNum, g_cocs_mono_sa_cycleDir);
   errorFlag = 1;
end
if (length(unique([a_profData.juldLocation])) > 1)
   fprintf('ERROR: Float #%d Cycle #%d%c: multiple JULD_LOCATION - file ignored\n', ...
      g_cocs_mono_sa_floatNum, g_cocs_mono_sa_cycleNum, g_cocs_mono_sa_cycleDir);
   errorFlag = 1;
end
if (length(unique([a_profData.juldLocationResolution])) > 1)
   fprintf('ERROR: Float #%d Cycle #%d%c: multiple JULD_LOCATION:resolution - file ignored\n', ...
      g_cocs_mono_sa_floatNum, g_cocs_mono_sa_cycleNum, g_cocs_mono_sa_cycleDir);
   errorFlag = 1;
end
if (length(unique([a_profData.latitude])) > 1)
   fprintf('ERROR: Float #%d Cycle #%d%c: multiple LATITUDE - file ignored\n', ...
      g_cocs_mono_sa_floatNum, g_cocs_mono_sa_cycleNum, g_cocs_mono_sa_cycleDir);
   errorFlag = 1;
end
if (length(unique([a_profData.longitude])) > 1)
   fprintf('ERROR: Float #%d Cycle #%d%c: multiple LONGITUDE - file ignored\n', ...
      g_cocs_mono_sa_floatNum, g_cocs_mono_sa_cycleNum, g_cocs_mono_sa_cycleDir);
   errorFlag = 1;
end
if (length(unique({a_profData.positionQc})) > 1)
   fprintf('ERROR: Float #%d Cycle #%d%c: multiple POSITION_QC - file ignored\n', ...
      g_cocs_mono_sa_floatNum, g_cocs_mono_sa_cycleNum, g_cocs_mono_sa_cycleDir);
   errorFlag = 1;
end
if (length(unique({a_profData.positioningSystem})) > 1)
   fprintf('ERROR: Float #%d Cycle #%d%c: multiple POSITIONING_SYSTEM - file ignored\n', ...
      g_cocs_mono_sa_floatNum, g_cocs_mono_sa_cycleNum, g_cocs_mono_sa_cycleDir);
   errorFlag = 1;
end
if (length(unique([a_profData.configMissionNumber])) > 1)
   fprintf('ERROR: Float #%d Cycle #%d%c: multiple CONFIG_MISSION_NUMBER - file ignored\n', ...
      g_cocs_mono_sa_floatNum, g_cocs_mono_sa_cycleNum, g_cocs_mono_sa_cycleDir);
   errorFlag = 1;
end
if (errorFlag == 1)
   return
end

% create synthetic profile
o_syntProfData = get_synthetic_prof_data_init_struct;

% fill synthetic profile
o_syntProfData.handbookVersion = a_profData(1).handbookVersion;
o_syntProfData.referenceDateTime = a_profData(1).referenceDateTime;
o_syntProfData.platformNumber = a_profData(1).platformNumber;
o_syntProfData.projectName = a_profData(1).projectName;
o_syntProfData.piName = a_profData(1).piName;
o_syntProfData.cycleNumber = a_profData(1).cycleNumber;
o_syntProfData.direction = a_profData(1).direction;
o_syntProfData.dataCentre = a_profData(1).dataCentre;
o_syntProfData.platformType = a_profData(1).platformType;
o_syntProfData.floatSerialNo = a_profData(1).floatSerialNo;
o_syntProfData.firmwareVersion = a_profData(1).firmwareVersion;
o_syntProfData.wmoInstType = a_profData(1).wmoInstType;
o_syntProfData.juld = a_profData(1).juld;
o_syntProfData.juldResolution = a_profData(1).juldResolution;
o_syntProfData.juldQc = a_profData(1).juldQc;
o_syntProfData.juldLocation = a_profData(1).juldLocation;
o_syntProfData.juldLocationResolution = a_profData(1).juldLocationResolution;
o_syntProfData.latitude = a_profData(1).latitude;
o_syntProfData.longitude = a_profData(1).longitude;
o_syntProfData.positionQc = a_profData(1).positionQc;
o_syntProfData.positioningSystem = a_profData(1).positioningSystem;
o_syntProfData.configMissionNumber = a_profData(1).configMissionNumber;

% gather information on final parameter list
paramList = [];
paramFillValue = [];
paramDataMode = [];
for idProf = 1:length(a_profData)
   profParamList = a_profData(idProf).paramList;
   for idParam = 1:length(profParamList)
      if (~ismember(profParamList{idParam}, paramList))
         paramList = [paramList profParamList(idParam)];
         paramInfo = get_netcdf_param_attributes_extended(profParamList{idParam}, g_cocs_mono_sa_floatNum);
         paramFillValue = [paramFillValue double(paramInfo.fillValue)];
         paramDataMode = [paramDataMode a_profData(idProf).paramDataMode(idParam)];
      end
   end
end

% compute synthetic profile data
try
   syntProfData = ARGO_simplified_profile( ...
      'cfilepath', a_cProfFileName, ...
      'bfilepath', a_bProfFileName, ...
      'metafilepath', a_metaFileName, ...
      'bgcFloatFlag', a_bgcFloatFlag);
catch error
   [~, bProfFileName, bProfFileExt] = fileparts(a_bProfFileName);
   fprintf('ERROR: Float #%d Cycle #%d%c: the synthetic profile data processing failed (ARGO_simplified_profile fonction on file %s)\n', ...
      g_cocs_mono_sa_floatNum, g_cocs_mono_sa_cycleNum, g_cocs_mono_sa_cycleDir, [bProfFileName bProfFileExt]);
   o_syntProfData = [];

   % write error information in log file
   fprintf('%s\n', error.message);
   for idS = 1:size(error.stack, 1)
      fprintf('   Line: %3d File: %s (func: %s)\n', ...
         error.stack(idS). line, ...
         error.stack(idS). file, ...
         error.stack(idS). name);
   end
   return
end

if (isempty(syntProfData))
   fprintf('ERROR: Float #%d Cycle #%d%c: no synthetic profile data reported by ARGO_simplified_profile fonction\n', ...
      g_cocs_mono_sa_floatNum, g_cocs_mono_sa_cycleNum, g_cocs_mono_sa_cycleDir);
   o_syntProfData = [];
   return
end

% store synthetic profile data in the output structure

% initialize data arrays
nbLev = length(syntProfData.PRES.value);
paramData = repmat(paramFillValue, nbLev, 1);
paramDataQc = repmat(g_decArgo_qcStrDef, size(paramData));
paramDataDPres = repmat(repmat(paramFillValue(1), 1, size(paramData, 2)), nbLev, 1);
paramDataAdjusted = repmat(paramFillValue, nbLev, 1);
paramDataAdjustedQc = repmat(g_decArgo_qcStrDef, size(paramData));
paramDataAdjustedError = repmat(paramFillValue, nbLev, 1);

for idParam = 1:length(paramList)

   paramName = paramList{idParam};
   if (~isfield(syntProfData, paramName))
      fprintf('ERROR: Float #%d Cycle #%d%c: ''%s'' parameter is not present in the output file\n', ...
         g_cocs_mono_sa_floatNum, g_cocs_mono_sa_cycleNum, g_cocs_mono_sa_cycleDir, ...
         paramName);
      continue
   end
   data = syntProfData.(paramName).value;
   idOk = find(~isnan(data));
   paramData(idOk, idParam) = data(idOk);

   paramNameQc = [paramName '_QC'];
   dataQc = syntProfData.(paramNameQc).value;
   idOk = find(~isnan(dataQc));
   paramDataQc(idOk, idParam) = num2str(dataQc(idOk));

   paramNameDPres = [paramName '_dPRES'];
   data = syntProfData.(paramNameDPres).value;
   idOk = find(~isnan(data));
   paramDataDPres(idOk, idParam) = data(idOk);

   paramNameAdj = [paramName '_ADJUSTED'];
   data = syntProfData.(paramNameAdj).value;
   idOk = find(~isnan(data));
   paramDataAdjusted(idOk, idParam) = data(idOk);

   paramNameAdjQc = [paramName '_ADJUSTED_QC'];
   dataQc = syntProfData.(paramNameAdjQc).value;
   idOk = find(~isnan(dataQc));
   paramDataAdjustedQc(idOk, idParam) = num2str(dataQc(idOk));

   paramNameAdjErr = [paramName '_ADJUSTED_ERROR'];
   data = syntProfData.(paramNameAdjErr).value;
   idOk = find(~isnan(data));
   paramDataAdjustedError(idOk, idParam) = data(idOk);
end

o_syntProfData.paramList = paramList;
o_syntProfData.paramDataMode = paramDataMode;

o_syntProfData.paramData = paramData;
o_syntProfData.paramDataQc = paramDataQc;
o_syntProfData.paramDataDPres = paramDataDPres;
o_syntProfData.paramDataAdjusted = paramDataAdjusted;
o_syntProfData.paramDataAdjustedQc = paramDataAdjustedQc;
o_syntProfData.paramDataAdjustedError = paramDataAdjustedError;

% retrieve SCIENTIFIC_CALIB_* information
scientificCalibEquation = cell(1, length(paramList));
scientificCalibCoefficient = cell(1, length(paramList));
scientificCalibComment = cell(1, length(paramList));
scientificCalibDate = cell(1, length(paramList));

% collect data
for idProf = 1:length(a_profData)
   profData = a_profData(idProf);
   profParamList = profData.paramList;

   % we don't known how to manage different information from different inital
   % profiles for a same parameter => we keep only the information from the
   % first N_PROF intial profile
   sciCalibEquation = profData.scientificCalibEquation;
   sciCalibCoefficient = profData.scientificCalibCoefficient;
   sciCalibComment = profData.scientificCalibComment;
   sciCalibDate = profData.scientificCalibDate;
   for idP = 1:length(sciCalibEquation)

      idParam = find(strcmp(paramList, profParamList{idP}), 1);

      scientificCalibEquationParam = scientificCalibEquation{idParam};
      scientificCalibCoefficientParam = scientificCalibCoefficient{idParam};
      scientificCalibCommentParam = scientificCalibComment{idParam};
      scientificCalibDateParam = scientificCalibDate{idParam};

      sciCalibEquationParam = sciCalibEquation{idP};
      sciCalibCoefficientParam = sciCalibCoefficient{idP};
      sciCalibCommentParam = sciCalibComment{idP};
      sciCalibDateParam = sciCalibDate{idP};

      updatedFlag = 0;
      for idC = 1:length(sciCalibEquationParam)

         % if N_CALIB > 1 update the size of the cell arrays
         if (length(scientificCalibEquationParam) < idC)
            tmpEquationParam = scientificCalibEquationParam;
            tmpCoefficientParam = scientificCalibCoefficientParam;
            tmpCommentParam = scientificCalibCommentParam;
            tmpDateParam = scientificCalibDateParam;

            scientificCalibEquationParam = cell(1, length(sciCalibEquationParam));
            scientificCalibCoefficientParam = cell(1, length(sciCalibEquationParam));
            scientificCalibCommentParam = cell(1, length(sciCalibEquationParam));
            scientificCalibDateParam = cell(1, length(sciCalibEquationParam));

            scientificCalibEquationParam(1:length(tmpEquationParam)) = tmpEquationParam;
            scientificCalibCoefficientParam(1:length(tmpEquationParam)) = tmpCoefficientParam;
            scientificCalibCommentParam(1:length(tmpEquationParam)) = tmpCommentParam;
            scientificCalibDateParam(1:length(tmpEquationParam)) = tmpDateParam;

            scientificCalibEquation{idParam} = scientificCalibEquationParam;
            scientificCalibCoefficient{idParam} = scientificCalibEquationParam;
            scientificCalibComment{idParam} = scientificCalibEquationParam;
            scientificCalibDate{idParam} = scientificCalibEquationParam;
         end

         % checke if the array need to be updated
         if (isempty(scientificCalibEquationParam{idC}) && ...
               isempty(scientificCalibCoefficientParam{idC}) && ...
               isempty(scientificCalibCommentParam{idC}) && ...
               isempty(scientificCalibDateParam{idC}))
            if (~isempty(sciCalibEquationParam{idC}) || ...
                  ~isempty(sciCalibCoefficientParam{idC}) || ...
                  ~isempty(sciCalibCommentParam{idC}) || ...
                  ~isempty(sciCalibDateParam{idC}))
               scientificCalibEquationParam{idC} = sciCalibEquationParam{idC};
               scientificCalibCoefficientParam{idC} = sciCalibCoefficientParam{idC};
               scientificCalibCommentParam{idC} = sciCalibCommentParam{idC};
               scientificCalibDateParam{idC} = sciCalibDateParam{idC};
               updatedFlag = 1;
            end
         end
      end

      if (updatedFlag)
         scientificCalibEquation{idParam} = scientificCalibEquationParam;
         scientificCalibCoefficient{idParam} = scientificCalibCoefficientParam;
         scientificCalibComment{idParam} = scientificCalibCommentParam;
         scientificCalibDate{idParam} = scientificCalibDateParam;
      end
   end
end

o_syntProfData.scientificCalibEquation = scientificCalibEquation;
o_syntProfData.scientificCalibCoefficient = scientificCalibCoefficient;
o_syntProfData.scientificCalibComment = scientificCalibComment;
o_syntProfData.scientificCalibDate = scientificCalibDate;

if (isempty(o_syntProfData.paramData))
   fprintf('ERROR: Float #%d Cycle #%d%c: no data remain after processing - no synthetic profile\n', ...
      g_cocs_mono_sa_floatNum, g_cocs_mono_sa_cycleNum, g_cocs_mono_sa_cycleDir);
   o_syntProfData = [];
end

return

% ------------------------------------------------------------------------------
% Get the dedicated structure to store synthetic profile information.
%
% SYNTAX :
%  [o_profDataStruct] = get_synthetic_prof_data_init_struct
%
% INPUT PARAMETERS :
%
% OUTPUT PARAMETERS :
%   o_profDataStruct : synthetic profile data initialized structure
%
% EXAMPLES :
%
% SEE ALSO :
% AUTHOR : Jean-Philippe Rannou (Capgemini) (jean.philippe.rannou@partenaire-exterieur.ifremer.fr)
% ------------------------------------------------------------------------------
% RELEASES :
%   06/15/2018 - RNU - creation
% ------------------------------------------------------------------------------
function [o_profDataStruct] = get_synthetic_prof_data_init_struct

% output parameters initialization
o_profDataStruct = struct( ...
   'handbookVersion', '', ...
   'referenceDateTime', '', ...
   'platformNumber', '', ...
   'projectName', '', ...
   'piName', '', ...
   'cycleNumber', [], ...
   'direction', '', ...
   'dataCentre', '', ...
   'platformType', '', ...
   'floatSerialNo', '', ...
   'firmwareVersion', '', ...
   'wmoInstType', '', ...
   'juld', [], ...
   'juldResolution', [], ...
   'juldQc', '', ...
   'juldLocation', [], ...
   'juldLocationResolution', [], ...
   'latitude', [], ...
   'longitude', [], ...
   'positionQc', '', ...
   'positioningSystem', '', ...
   'configMissionNumber', [], ...
   ...
   'paramList', [], ...
   'paramDataMode', '', ...
   ...
   'paramData', [], ...
   'paramDataQc', '', ...
   'paramDataDPres', [], ...
   'paramDataAdjusted', [], ...
   'paramDataAdjustedQc', '', ...
   'paramDataAdjustedError', [], ...
   ...
   'scientificCalibEquation', [], ...
   'scientificCalibCoefficient', [], ...
   'scientificCalibComment', [], ...
   'scientificCalibDate', [] ...
   );

return

% ------------------------------------------------------------------------------
% Create synthetic mono-cycle NetCDF file.
%
% SYNTAX :
%  create_synthetic_mono_cycle_file(a_floatWmo, a_profData, a_outputDir)
%
% INPUT PARAMETERS :
%   a_floatWmo  : float WMO number
%   a_profData  : synthetic profile data
%   a_outputDir : output directory
%
% OUTPUT PARAMETERS :
%
% EXAMPLES :
%
% SEE ALSO :
% AUTHOR : Jean-Philippe Rannou (Capgemini) (jean.philippe.rannou@partenaire-exterieur.ifremer.fr)
% ------------------------------------------------------------------------------
% RELEASES :
%   02/09/2026 - RNU - creation
% ------------------------------------------------------------------------------
function create_synthetic_mono_cycle_file(a_floatWmo, a_profData, a_outputDir)

% program version
global g_cocs_mono_sa_createMonoCycleSyntheticProfileVersion;

% start date of the run
global g_cocs_mono_sa_currentDate;

% current float and cycle identification
global g_cocs_mono_sa_floatNum;
global g_cocs_mono_sa_cycleNum;
global g_cocs_mono_sa_cycleDir;

% common long_name for nc files
global g_decArgo_longNameOfParamAdjErr;

% deflate levels
DEFLATE_LEVEL = 1;

% shuffle flag
SHUFFLE_FLAG = true;


% compute file dimensions
nProfDim = 1;
nParamDim = size(a_profData.paramData, 2);
nLevelsDim = size(a_profData.paramData, 1);
nCalibDim = 1;
for idParam = 1:length(a_profData.scientificCalibEquation)
   scientificCalibEquation = a_profData.scientificCalibEquation{idParam};
   nCalibDim = max(nCalibDim, length(scientificCalibEquation));
end

% create the output file name
if (any(a_profData.paramDataMode == 'D'))
   modeCode = 'D';
else
   modeCode = 'R';
end
outputFileName = ['S' modeCode num2str(a_floatWmo) '_' sprintf('%03d%c', g_cocs_mono_sa_cycleNum, g_cocs_mono_sa_cycleDir) '.nc'];
outputFilePathName = [a_outputDir '/' outputFileName];

% create and open NetCDF file
mode = netcdf.getConstant('NC_CLOBBER');
mode = bitor(mode, netcdf.getConstant('NETCDF4'));
mode = bitor(mode, netcdf.getConstant('CLASSIC_MODEL'));
fCdf = netcdf.create(outputFilePathName, mode);
if (isempty(fCdf))
   fprintf('ERROR: Unable to create NetCDF output file: %s\n', outputFilePathName);
   return
end

try

   %%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
   % DEFINE MODE BEGIN

   % create dimensions
   dateTimeDimId = netcdf.defDim(fCdf, 'DATE_TIME', 14);
   string256DimId = netcdf.defDim(fCdf, 'STRING256', 256);
   string64DimId = netcdf.defDim(fCdf, 'STRING64', 64);
   string32DimId = netcdf.defDim(fCdf, 'STRING32', 32);
   string8DimId = netcdf.defDim(fCdf, 'STRING8', 8);
   string4DimId = netcdf.defDim(fCdf, 'STRING4', 4);
   string2DimId = netcdf.defDim(fCdf, 'STRING2', 2);
   nProfDimId = netcdf.defDim(fCdf, 'N_PROF', nProfDim);
   nParamDimId = netcdf.defDim(fCdf, 'N_PARAM', nParamDim);
   nLevelsDimId = netcdf.defDim(fCdf, 'N_LEVELS', nLevelsDim);
   nCalibDimId = netcdf.defDim(fCdf, 'N_CALIB', nCalibDim);

   % create global attributes
   globalVarId = netcdf.getConstant('NC_GLOBAL');
   netcdf.putAtt(fCdf, globalVarId, 'title', 'Argo float vertical profile');
   institution = get_institution_from_data_centre(a_profData.dataCentre, 0);
   if (isempty(deblank(institution)))
      fprintf('WARNING: Float #%d Cycle #%d%c: No institution assigned to data centre %s\n', ...
         g_cocs_mono_sa_floatNum, g_cocs_mono_sa_cycleNum, g_cocs_mono_sa_cycleDir, a_profData.dataCentre);
   end
   netcdf.putAtt(fCdf, globalVarId, 'institution', institution);
   netcdf.putAtt(fCdf, globalVarId, 'source', 'Argo float');
   netcdf.putAtt(fCdf, globalVarId, 'history', ...
      [datestr(datenum(g_cocs_mono_sa_currentDate, 'yyyymmddHHMMSS'), 'yyyy-mm-ddTHH:MM:SSZ') ...
      ' creation (software version ' g_cocs_mono_sa_createMonoCycleSyntheticProfileVersion ')']);
   netcdf.putAtt(fCdf, globalVarId, 'software_version', g_cocs_mono_sa_createMonoCycleSyntheticProfileVersion);
   netcdf.putAtt(fCdf, globalVarId, 'references', 'http://www.argodatamgt.org/Documentation');
   netcdf.putAtt(fCdf, globalVarId, 'user_manual_version', '1.0');
   netcdf.putAtt(fCdf, globalVarId, 'Conventions', 'Argo-3.1 CF-1.6');
   netcdf.putAtt(fCdf, globalVarId, 'featureType', 'trajectoryProfile');
   netcdf.putAtt(fCdf, globalVarId, 'id', 'https://doi.org/10.17882/42182');

   % create misc variables
   dataTypeVarId = netcdf.defVar(fCdf, 'DATA_TYPE', 'NC_CHAR', string32DimId);
   netcdf.defVarDeflate(fCdf, dataTypeVarId, SHUFFLE_FLAG, true, DEFLATE_LEVEL);
   netcdf.putAtt(fCdf, dataTypeVarId, 'long_name', 'Data type');
   netcdf.putAtt(fCdf, dataTypeVarId, 'conventions', 'Argo reference table 1');
   netcdf.defVarFill(fCdf, dataTypeVarId, false, ' ');

   formatVersionVarId = netcdf.defVar(fCdf, 'FORMAT_VERSION', 'NC_CHAR', string4DimId);
   netcdf.defVarDeflate(fCdf, formatVersionVarId, SHUFFLE_FLAG, true, DEFLATE_LEVEL);
   netcdf.putAtt(fCdf, formatVersionVarId, 'long_name', 'File format version');
   netcdf.defVarFill(fCdf, formatVersionVarId, false, ' ');

   handbookVersionVarId = netcdf.defVar(fCdf, 'HANDBOOK_VERSION', 'NC_CHAR', string4DimId);
   netcdf.defVarDeflate(fCdf, handbookVersionVarId, SHUFFLE_FLAG, true, DEFLATE_LEVEL);
   netcdf.putAtt(fCdf, handbookVersionVarId, 'long_name', 'Data handbook version');
   netcdf.defVarFill(fCdf, handbookVersionVarId, false, ' ');

   referenceDateTimeVarId = netcdf.defVar(fCdf, 'REFERENCE_DATE_TIME', 'NC_CHAR', dateTimeDimId);
   netcdf.defVarDeflate(fCdf, referenceDateTimeVarId, SHUFFLE_FLAG, true, DEFLATE_LEVEL);
   netcdf.putAtt(fCdf, referenceDateTimeVarId, 'long_name', 'Date of reference for Julian days');
   netcdf.putAtt(fCdf, referenceDateTimeVarId, 'conventions', 'YYYYMMDDHHMISS');
   netcdf.defVarFill(fCdf, referenceDateTimeVarId, false, ' ');

   dateCreationVarId = netcdf.defVar(fCdf, 'DATE_CREATION', 'NC_CHAR', dateTimeDimId);
   netcdf.defVarDeflate(fCdf, dateCreationVarId, SHUFFLE_FLAG, true, DEFLATE_LEVEL);
   netcdf.putAtt(fCdf, dateCreationVarId, 'long_name', 'Date of file creation');
   netcdf.putAtt(fCdf, dateCreationVarId, 'conventions', 'YYYYMMDDHHMISS');
   netcdf.defVarFill(fCdf, dateCreationVarId, false, ' ');

   dateUpdateVarId = netcdf.defVar(fCdf, 'DATE_UPDATE', 'NC_CHAR', dateTimeDimId);
   netcdf.defVarDeflate(fCdf, dateUpdateVarId, SHUFFLE_FLAG, true, DEFLATE_LEVEL);
   netcdf.putAtt(fCdf, dateUpdateVarId, 'long_name', 'Date of update of this file');
   netcdf.putAtt(fCdf, dateUpdateVarId, 'conventions', 'YYYYMMDDHHMISS');
   netcdf.defVarFill(fCdf, dateUpdateVarId, false, ' ');

   % create profile variables
   platformNumberVarId = netcdf.defVar(fCdf, 'PLATFORM_NUMBER', 'NC_CHAR', fliplr([nProfDimId string8DimId]));
   netcdf.defVarDeflate(fCdf, platformNumberVarId, SHUFFLE_FLAG, true, DEFLATE_LEVEL);
   netcdf.putAtt(fCdf, platformNumberVarId, 'long_name', 'Float unique identifier');
   netcdf.putAtt(fCdf, platformNumberVarId, 'conventions', 'WMO float identifier : A9IIIII');
   netcdf.defVarFill(fCdf, platformNumberVarId, false, ' ');

   projectNameVarId = netcdf.defVar(fCdf, 'PROJECT_NAME', 'NC_CHAR', fliplr([nProfDimId string64DimId]));
   netcdf.defVarDeflate(fCdf, projectNameVarId, SHUFFLE_FLAG, true, DEFLATE_LEVEL);
   netcdf.putAtt(fCdf, projectNameVarId, 'long_name', 'Name of the project');
   netcdf.defVarFill(fCdf, projectNameVarId, false, ' ');

   piNameVarId = netcdf.defVar(fCdf, 'PI_NAME', 'NC_CHAR', fliplr([nProfDimId string64DimId]));
   netcdf.defVarDeflate(fCdf, piNameVarId, SHUFFLE_FLAG, true, DEFLATE_LEVEL);
   netcdf.putAtt(fCdf, piNameVarId, 'long_name', 'Name of the principal investigator');
   netcdf.defVarFill(fCdf, piNameVarId, false, ' ');

   stationParametersVarId = netcdf.defVar(fCdf, 'STATION_PARAMETERS', 'NC_CHAR', fliplr([nProfDimId nParamDimId string64DimId]));
   netcdf.defVarDeflate(fCdf, stationParametersVarId, SHUFFLE_FLAG, true, DEFLATE_LEVEL);
   netcdf.putAtt(fCdf, stationParametersVarId, 'long_name', 'List of available parameters for the station');
   netcdf.putAtt(fCdf, stationParametersVarId, 'conventions', 'Argo reference table 3');
   netcdf.defVarFill(fCdf, stationParametersVarId, false, ' ');

   cycleNumberVarId = netcdf.defVar(fCdf, 'CYCLE_NUMBER', 'NC_INT', nProfDimId);
   netcdf.defVarDeflate(fCdf, cycleNumberVarId, SHUFFLE_FLAG, true, DEFLATE_LEVEL);
   netcdf.putAtt(fCdf, cycleNumberVarId, 'long_name', 'Float cycle number');
   netcdf.putAtt(fCdf, cycleNumberVarId, 'conventions', '0...N, 0 : launch cycle (if exists), 1 : first complete cycle');
   netcdf.defVarFill(fCdf, cycleNumberVarId, false, int32(99999));

   directionVarId = netcdf.defVar(fCdf, 'DIRECTION', 'NC_CHAR', nProfDimId);
   netcdf.defVarDeflate(fCdf, directionVarId, SHUFFLE_FLAG, true, DEFLATE_LEVEL);
   netcdf.putAtt(fCdf, directionVarId, 'long_name', 'Direction of the station profiles');
   netcdf.putAtt(fCdf, directionVarId, 'conventions', 'A: ascending profiles, D: descending profiles');
   netcdf.defVarFill(fCdf, directionVarId, false, ' ');

   dataCenterVarId = netcdf.defVar(fCdf, 'DATA_CENTRE', 'NC_CHAR', fliplr([nProfDimId string2DimId]));
   netcdf.defVarDeflate(fCdf, dataCenterVarId, SHUFFLE_FLAG, true, DEFLATE_LEVEL);
   netcdf.putAtt(fCdf, dataCenterVarId, 'long_name', 'Data centre in charge of float data processing');
   netcdf.putAtt(fCdf, dataCenterVarId, 'conventions', 'Argo reference table 4');
   netcdf.defVarFill(fCdf, dataCenterVarId, false, ' ');

   parameterDataModeVarId = netcdf.defVar(fCdf, 'PARAMETER_DATA_MODE', 'NC_CHAR', fliplr([nProfDimId nParamDimId]));
   netcdf.defVarDeflate(fCdf, parameterDataModeVarId, SHUFFLE_FLAG, true, DEFLATE_LEVEL);
   netcdf.putAtt(fCdf, parameterDataModeVarId, 'long_name', 'Delayed mode or real time data');
   netcdf.putAtt(fCdf, parameterDataModeVarId, 'conventions', 'R : real time; D : delayed mode; A : real time with adjustment');
   netcdf.defVarFill(fCdf, parameterDataModeVarId, false, ' ');

   platformTypeVarId = netcdf.defVar(fCdf, 'PLATFORM_TYPE', 'NC_CHAR', fliplr([nProfDimId string32DimId]));
   netcdf.putAtt(fCdf, platformTypeVarId, 'long_name', 'Type of float');
   netcdf.putAtt(fCdf, platformTypeVarId, 'conventions', 'Argo reference table 23');
   netcdf.defVarFill(fCdf, platformTypeVarId, false, ' ');

   floatSerialNoVarId = netcdf.defVar(fCdf, 'FLOAT_SERIAL_NO', 'NC_CHAR', fliplr([nProfDimId string32DimId]));
   netcdf.defVarDeflate(fCdf, floatSerialNoVarId, SHUFFLE_FLAG, true, DEFLATE_LEVEL);
   netcdf.putAtt(fCdf, floatSerialNoVarId, 'long_name', 'Serial number of the float');
   netcdf.defVarFill(fCdf, floatSerialNoVarId, false, ' ');

   firmwareVersionVarId = netcdf.defVar(fCdf, 'FIRMWARE_VERSION', 'NC_CHAR', fliplr([nProfDimId string32DimId]));
   netcdf.defVarDeflate(fCdf, firmwareVersionVarId, SHUFFLE_FLAG, true, DEFLATE_LEVEL);
   netcdf.putAtt(fCdf, firmwareVersionVarId, 'long_name', 'Instrument firmware version');
   netcdf.defVarFill(fCdf, firmwareVersionVarId, false, ' ');

   wmoInstTypeVarId = netcdf.defVar(fCdf, 'WMO_INST_TYPE', 'NC_CHAR', fliplr([nProfDimId string4DimId]));
   netcdf.defVarDeflate(fCdf, wmoInstTypeVarId, SHUFFLE_FLAG, true, DEFLATE_LEVEL);
   netcdf.putAtt(fCdf, wmoInstTypeVarId, 'long_name', 'Coded instrument type');
   netcdf.putAtt(fCdf, wmoInstTypeVarId, 'conventions', 'Argo reference table 8');
   netcdf.defVarFill(fCdf, wmoInstTypeVarId, false, ' ');

   juldVarId = netcdf.defVar(fCdf, 'JULD', 'NC_DOUBLE', nProfDimId);
   netcdf.defVarDeflate(fCdf, juldVarId, SHUFFLE_FLAG, true, DEFLATE_LEVEL);
   netcdf.putAtt(fCdf, juldVarId, 'long_name', 'Julian day (UTC) of the station relative to REFERENCE_DATE_TIME');
   netcdf.putAtt(fCdf, juldVarId, 'standard_name', 'time');
   netcdf.putAtt(fCdf, juldVarId, 'units', 'days since 1950-01-01 00:00:00 UTC');
   netcdf.putAtt(fCdf, juldVarId, 'conventions', 'Relative julian days with decimal part (as parts of day)');
   netcdf.putAtt(fCdf, juldVarId, 'resolution', a_profData.juldResolution);
   netcdf.defVarFill(fCdf, juldVarId, false, double(999999));
   netcdf.putAtt(fCdf, juldVarId, 'axis', 'T');

   juldQcVarId = netcdf.defVar(fCdf, 'JULD_QC', 'NC_CHAR', nProfDimId);
   netcdf.defVarDeflate(fCdf, juldQcVarId, SHUFFLE_FLAG, true, DEFLATE_LEVEL);
   netcdf.putAtt(fCdf, juldQcVarId, 'long_name', 'Quality on date and time');
   netcdf.putAtt(fCdf, juldQcVarId, 'conventions', 'Argo reference table 2');
   netcdf.defVarFill(fCdf, juldQcVarId, false, ' ');

   juldLocationVarId = netcdf.defVar(fCdf, 'JULD_LOCATION', 'NC_DOUBLE', nProfDimId);
   netcdf.defVarDeflate(fCdf, juldLocationVarId, SHUFFLE_FLAG, true, DEFLATE_LEVEL);
   netcdf.putAtt(fCdf, juldLocationVarId, 'long_name', 'Julian day (UTC) of the location relative to REFERENCE_DATE_TIME');
   netcdf.putAtt(fCdf, juldLocationVarId, 'units', 'days since 1950-01-01 00:00:00 UTC');
   netcdf.putAtt(fCdf, juldLocationVarId, 'conventions', 'Relative julian days with decimal part (as parts of day)');
   netcdf.putAtt(fCdf, juldLocationVarId, 'resolution', a_profData.juldLocationResolution);
   netcdf.putAtt(fCdf, juldLocationVarId, '_FillValue', double(999999));
   netcdf.defVarFill(fCdf, juldLocationVarId, false, double(999999));

   latitudeVarId = netcdf.defVar(fCdf, 'LATITUDE', 'NC_DOUBLE', nProfDimId);
   netcdf.defVarDeflate(fCdf, latitudeVarId, SHUFFLE_FLAG, true, DEFLATE_LEVEL);
   netcdf.putAtt(fCdf, latitudeVarId, 'long_name', 'Latitude of the station, best estimate');
   netcdf.putAtt(fCdf, latitudeVarId, 'standard_name', 'latitude');
   netcdf.putAtt(fCdf, latitudeVarId, 'units', 'degree_north');
   netcdf.defVarFill(fCdf, latitudeVarId, false, double(99999));
   netcdf.putAtt(fCdf, latitudeVarId, 'valid_min', double(-90));
   netcdf.putAtt(fCdf, latitudeVarId, 'valid_max', double(90));
   netcdf.putAtt(fCdf, latitudeVarId, 'axis', 'Y');

   longitudeVarId = netcdf.defVar(fCdf, 'LONGITUDE', 'NC_DOUBLE', nProfDimId);
   netcdf.defVarDeflate(fCdf, longitudeVarId, SHUFFLE_FLAG, true, DEFLATE_LEVEL);
   netcdf.putAtt(fCdf, longitudeVarId, 'long_name', 'Longitude of the station, best estimate');
   netcdf.putAtt(fCdf, longitudeVarId, 'standard_name', 'longitude');
   netcdf.putAtt(fCdf, longitudeVarId, 'units', 'degree_east');
   netcdf.defVarFill(fCdf, longitudeVarId, false, double(99999));
   netcdf.putAtt(fCdf, longitudeVarId, 'valid_min', double(-180));
   netcdf.putAtt(fCdf, longitudeVarId, 'valid_max', double(180));
   netcdf.putAtt(fCdf, longitudeVarId, 'axis', 'X');

   positionQcVarId = netcdf.defVar(fCdf, 'POSITION_QC', 'NC_CHAR', nProfDimId);
   netcdf.defVarDeflate(fCdf, positionQcVarId, SHUFFLE_FLAG, true, DEFLATE_LEVEL);
   netcdf.putAtt(fCdf, positionQcVarId, 'long_name', 'Quality on position (latitude and longitude)');
   netcdf.putAtt(fCdf, positionQcVarId, 'conventions', 'Argo reference table 2');
   netcdf.defVarFill(fCdf, positionQcVarId, false, ' ');

   positioningSystemVarId = netcdf.defVar(fCdf, 'POSITIONING_SYSTEM', 'NC_CHAR', fliplr([nProfDimId string8DimId]));
   netcdf.defVarDeflate(fCdf, positioningSystemVarId, SHUFFLE_FLAG, true, DEFLATE_LEVEL);
   netcdf.putAtt(fCdf, positioningSystemVarId, 'long_name', 'Positioning system');
   netcdf.defVarFill(fCdf, positioningSystemVarId, false, ' ');

   configMissionNumberVarId = netcdf.defVar(fCdf, 'CONFIG_MISSION_NUMBER', 'NC_INT', nProfDimId);
   netcdf.defVarDeflate(fCdf, configMissionNumberVarId, SHUFFLE_FLAG, true, DEFLATE_LEVEL);
   netcdf.putAtt(fCdf, configMissionNumberVarId, 'long_name', 'Unique number denoting the missions performed by the float');
   netcdf.putAtt(fCdf, configMissionNumberVarId, 'conventions', '1...N, 1 : first complete mission');
   netcdf.defVarFill(fCdf, configMissionNumberVarId, false, int32(99999));

   % calibration information
   parameterVarId = netcdf.defVar(fCdf, 'PARAMETER', 'NC_CHAR', fliplr([nProfDimId nCalibDimId nParamDimId string64DimId]));
   netcdf.defVarDeflate(fCdf, parameterVarId, SHUFFLE_FLAG, true, DEFLATE_LEVEL);
   netcdf.putAtt(fCdf, parameterVarId, 'long_name', 'List of parameters with calibration information');
   netcdf.putAtt(fCdf, parameterVarId, 'conventions', 'Argo reference table 3');
   netcdf.defVarFill(fCdf, parameterVarId, false, ' ');

   scientificCalibEquationVarId = netcdf.defVar(fCdf, 'SCIENTIFIC_CALIB_EQUATION', 'NC_CHAR', fliplr([nProfDimId nCalibDimId nParamDimId string256DimId]));
   netcdf.defVarDeflate(fCdf, scientificCalibEquationVarId, SHUFFLE_FLAG, true, DEFLATE_LEVEL);
   netcdf.putAtt(fCdf, scientificCalibEquationVarId, 'long_name', 'Calibration equation for this parameter');
   netcdf.defVarFill(fCdf, scientificCalibEquationVarId, false, ' ');

   scientificCalibCoefficientVarId = netcdf.defVar(fCdf, 'SCIENTIFIC_CALIB_COEFFICIENT', 'NC_CHAR', fliplr([nProfDimId nCalibDimId nParamDimId string256DimId]));
   netcdf.defVarDeflate(fCdf, scientificCalibCoefficientVarId, SHUFFLE_FLAG, true, DEFLATE_LEVEL);
   netcdf.putAtt(fCdf, scientificCalibCoefficientVarId, 'long_name', 'Calibration coefficients for this equation');
   netcdf.defVarFill(fCdf, scientificCalibCoefficientVarId, false, ' ');

   scientificCalibCommentVarId = netcdf.defVar(fCdf, 'SCIENTIFIC_CALIB_COMMENT', 'NC_CHAR', fliplr([nProfDimId nCalibDimId nParamDimId string256DimId]));
   netcdf.defVarDeflate(fCdf, scientificCalibCommentVarId, SHUFFLE_FLAG, true, DEFLATE_LEVEL);
   netcdf.putAtt(fCdf, scientificCalibCommentVarId, 'long_name', 'Comment applying to this parameter calibration');
   netcdf.defVarFill(fCdf, scientificCalibCommentVarId, false, ' ');

   scientificCalibDateVarId = netcdf.defVar(fCdf, 'SCIENTIFIC_CALIB_DATE', 'NC_CHAR', fliplr([nProfDimId nCalibDimId nParamDimId dateTimeDimId]));
   netcdf.defVarDeflate(fCdf, scientificCalibDateVarId, SHUFFLE_FLAG, true, DEFLATE_LEVEL);
   netcdf.putAtt(fCdf, scientificCalibDateVarId, 'long_name', 'Date of calibration');
   netcdf.putAtt(fCdf, scientificCalibDateVarId, 'conventions', 'YYYYMMDDHHMISS');
   netcdf.defVarFill(fCdf, scientificCalibDateVarId, false, ' ');

   % create parameter variables
   paramList = a_profData.paramList;

   % global quality of PARAM profile
   for idParam = 1:length(paramList)
      paramName = paramList{idParam};
      profParamQcName = ['PROFILE_' paramName '_QC'];

      profileParamQcVarId = netcdf.defVar(fCdf, profParamQcName, 'NC_CHAR', nProfDimId);
      netcdf.defVarDeflate(fCdf, profileParamQcVarId, SHUFFLE_FLAG, true, DEFLATE_LEVEL);

      netcdf.putAtt(fCdf, profileParamQcVarId, 'long_name', sprintf('Global quality flag of %s profile', paramName));
      netcdf.putAtt(fCdf, profileParamQcVarId, 'conventions', 'Argo reference table 2a');
      netcdf.defVarFill(fCdf, profileParamQcVarId, false, ' ');
   end

   % PARAM profile
   paramPresInfo = get_netcdf_param_attributes_extended('PRES', g_cocs_mono_sa_floatNum);
   for idParam = 1:length(paramList)

      paramName = paramList{idParam};
      paramInfo = get_netcdf_param_attributes_extended(paramName, g_cocs_mono_sa_floatNum);

      % parameter variable and attributes
      if (~var_is_present_dec_argo(fCdf, paramName))

         paramVarId = netcdf.defVar(fCdf, paramName, paramInfo.paramNcType, fliplr([nProfDimId nLevelsDimId]));
         netcdf.defVarDeflate(fCdf, paramVarId, SHUFFLE_FLAG, true, DEFLATE_LEVEL);

         if (~isempty(paramInfo.longName))
            netcdf.putAtt(fCdf, paramVarId, 'long_name', paramInfo.longName);
         end
         if (~isempty(paramInfo.standardName))
            netcdf.putAtt(fCdf, paramVarId, 'standard_name', paramInfo.standardName);
         end
         if (~isempty(paramInfo.fillValue))
            netcdf.defVarFill(fCdf, paramVarId, false, paramInfo.fillValue)
         end
         if (~isempty(paramInfo.units))
            netcdf.putAtt(fCdf, paramVarId, 'units', paramInfo.units);
         end
         if (~isempty(paramInfo.validMin))
            netcdf.putAtt(fCdf, paramVarId, 'valid_min', paramInfo.validMin);
         end
         if (~isempty(paramInfo.validMax))
            netcdf.putAtt(fCdf, paramVarId, 'valid_max', paramInfo.validMax);
         end
         if (~isempty(paramInfo.cFormat))
            netcdf.putAtt(fCdf, paramVarId, 'C_format', paramInfo.cFormat);
         end
         if (~isempty(paramInfo.fortranFormat))
            netcdf.putAtt(fCdf, paramVarId, 'FORTRAN_format', paramInfo.fortranFormat);
         end
         if (~isempty(paramInfo.resolution))
            netcdf.putAtt(fCdf, paramVarId, 'resolution', paramInfo.resolution);
         end
         if (~isempty(paramInfo.axis))
            netcdf.putAtt(fCdf, paramVarId, 'axis', paramInfo.axis);
         end
      else
         fprintf('WARNING: Float #%d Cycle #%d%c: Parameter ''%s'' already exists in the nc file\n', ...
            g_cocs_mono_sa_floatNum, g_cocs_mono_sa_cycleNum, g_cocs_mono_sa_cycleDir, paramName);
      end

      % parameter QC variable and attributes
      paramQcName = [paramName '_QC'];
      if (~var_is_present_dec_argo(fCdf, paramQcName))

         paramQcVarId = netcdf.defVar(fCdf, paramQcName, 'NC_CHAR', fliplr([nProfDimId nLevelsDimId]));
         netcdf.defVarDeflate(fCdf, paramQcVarId, SHUFFLE_FLAG, true, DEFLATE_LEVEL);

         netcdf.putAtt(fCdf, paramQcVarId, 'long_name', 'quality flag');
         netcdf.putAtt(fCdf, paramQcVarId, 'conventions', 'Argo reference table 2');
         netcdf.defVarFill(fCdf, paramQcVarId, false, ' ')
      else
         fprintf('WARNING: Float #%d Cycle #%d%c: Parameter ''%s'' already exists in the nc file\n', ...
            g_cocs_mono_sa_floatNum, g_cocs_mono_sa_cycleNum, g_cocs_mono_sa_cycleDir, paramQcName);
      end

      % parameter displacement variable and attributes
      if (~strcmp(paramName, 'PRES'))
         paramDPresName = [paramName '_dPRES'];
         if (~var_is_present_dec_argo(fCdf, paramDPresName))

            paramDPresVarId = netcdf.defVar(fCdf, paramDPresName, paramPresInfo.paramNcType, fliplr([nProfDimId nLevelsDimId]));

            netcdf.putAtt(fCdf, paramDPresVarId, 'long_name', [paramName ' pressure displacement from original sampled value']);

            if (~isempty(paramInfo.fillValue))
               netcdf.defVarFill(fCdf, paramDPresVarId, false, paramPresInfo.fillValue)
            end
            if (~isempty(paramInfo.units))
               netcdf.putAtt(fCdf, paramDPresVarId, 'units', paramPresInfo.units);
            end
         else
            fprintf('WARNING: Float #%d Cycle #%d%c: Parameter ''%s'' already exists in the nc file\n', ...
               g_cocs_mono_sa_floatNum, g_cocs_mono_sa_cycleNum, g_cocs_mono_sa_cycleDir, paramDPresName);
         end
      end

      % parameter adjusted variable and attributes
      paramAdjName = [paramName '_ADJUSTED'];
      if (~var_is_present_dec_argo(fCdf, paramAdjName))

         paramAdjVarId = netcdf.defVar(fCdf, paramAdjName, paramInfo.paramNcType, fliplr([nProfDimId nLevelsDimId]));
         netcdf.defVarDeflate(fCdf, paramAdjVarId, SHUFFLE_FLAG, true, DEFLATE_LEVEL);

         if (~isempty(paramInfo.longName))
            netcdf.putAtt(fCdf, paramAdjVarId, 'long_name', paramInfo.longName);
         end
         if (~isempty(paramInfo.standardName))
            netcdf.putAtt(fCdf, paramAdjVarId, 'standard_name', paramInfo.standardName);
         end
         if (~isempty(paramInfo.fillValue))
            netcdf.defVarFill(fCdf, paramAdjVarId, false, paramInfo.fillValue)
         end
         if (~isempty(paramInfo.units))
            netcdf.putAtt(fCdf, paramAdjVarId, 'units', paramInfo.units);
         end
         if (~isempty(paramInfo.validMin))
            netcdf.putAtt(fCdf, paramAdjVarId, 'valid_min', paramInfo.validMin);
         end
         if (~isempty(paramInfo.validMax))
            netcdf.putAtt(fCdf, paramAdjVarId, 'valid_max', paramInfo.validMax);
         end
         if (~isempty(paramInfo.cFormat))
            netcdf.putAtt(fCdf, paramAdjVarId, 'C_format', paramInfo.cFormat);
         end
         if (~isempty(paramInfo.fortranFormat))
            netcdf.putAtt(fCdf, paramAdjVarId, 'FORTRAN_format', paramInfo.fortranFormat);
         end
         if (~isempty(paramInfo.resolution))
            netcdf.putAtt(fCdf, paramAdjVarId, 'resolution', paramInfo.resolution);
         end
         if (~isempty(paramInfo.axis))
            netcdf.putAtt(fCdf, paramAdjVarId, 'axis', paramInfo.axis);
         end
      else
         fprintf('WARNING: Float #%d Cycle #%d%c: Parameter ''%s'' already exists in the nc file\n', ...
            g_cocs_mono_sa_floatNum, g_cocs_mono_sa_cycleNum, g_cocs_mono_sa_cycleDir, paramAdjName);
      end

      % parameter adjusted QC variable and attributes
      paramAdjQcName = [paramName '_ADJUSTED_QC'];
      if (~var_is_present_dec_argo(fCdf, paramAdjQcName))

         paramAdjQcVarId = netcdf.defVar(fCdf, paramAdjQcName, 'NC_CHAR', fliplr([nProfDimId nLevelsDimId]));
         netcdf.defVarDeflate(fCdf, paramAdjQcVarId, SHUFFLE_FLAG, true, DEFLATE_LEVEL);

         netcdf.putAtt(fCdf, paramAdjQcVarId, 'long_name', 'quality flag');
         netcdf.putAtt(fCdf, paramAdjQcVarId, 'conventions', 'Argo reference table 2');
         netcdf.defVarFill(fCdf, paramAdjQcVarId, false, ' ')
      else
         fprintf('WARNING: Float #%d Cycle #%d%c: Parameter ''%s'' already exists in the nc file\n', ...
            g_cocs_mono_sa_floatNum, g_cocs_mono_sa_cycleNum, g_cocs_mono_sa_cycleDir, paramAdjQcName);
      end

      % parameter adjusted error variable and attributes
      paramAdjErrName = [paramName '_ADJUSTED_ERROR'];
      if (~var_is_present_dec_argo(fCdf, paramAdjErrName))

         paramAdjErrVarId = netcdf.defVar(fCdf, paramAdjErrName, paramInfo.paramNcType, fliplr([nProfDimId nLevelsDimId]));
         netcdf.defVarDeflate(fCdf, paramAdjErrVarId, SHUFFLE_FLAG, true, DEFLATE_LEVEL);

         netcdf.putAtt(fCdf, paramAdjErrVarId, 'long_name', g_decArgo_longNameOfParamAdjErr);
         if (~isempty(paramInfo.fillValue))
            netcdf.defVarFill(fCdf, paramAdjErrVarId, false, paramInfo.fillValue)
         end
         if (~isempty(paramInfo.units))
            netcdf.putAtt(fCdf, paramAdjErrVarId, 'units', paramInfo.units);
         end
         if (~isempty(paramInfo.cFormat))
            netcdf.putAtt(fCdf, paramAdjErrVarId, 'C_format', paramInfo.cFormat);
         end
         if (~isempty(paramInfo.fortranFormat))
            netcdf.putAtt(fCdf, paramAdjErrVarId, 'FORTRAN_format', paramInfo.fortranFormat);
         end
         if (~isempty(paramInfo.resolution))
            netcdf.putAtt(fCdf, paramAdjErrVarId, 'resolution', paramInfo.resolution);
         end
      else
         fprintf('WARNING: Float #%d Cycle #%d%c: Parameter ''%s'' already exists in the nc file\n', ...
            g_cocs_mono_sa_floatNum, g_cocs_mono_sa_cycleNum, g_cocs_mono_sa_cycleDir, paramAdjErrName);
      end
   end

   %%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
   % DEFINE MODE END

   netcdf.endDef(fCdf);

   % fill misc variable data
   valueStr = 'Argo synthetic profile';
   netcdf.putVar(fCdf, netcdf.inqVarID(fCdf, 'DATA_TYPE'), 0, length(valueStr), valueStr);
   valueStr = '1.0';
   netcdf.putVar(fCdf, netcdf.inqVarID(fCdf, 'FORMAT_VERSION'), 0, length(valueStr), valueStr);
   valueStr = a_profData.handbookVersion;
   if (~isempty(valueStr))
      netcdf.putVar(fCdf, netcdf.inqVarID(fCdf, 'HANDBOOK_VERSION'), 0, length(valueStr), valueStr);
   end
   valueStr = a_profData.referenceDateTime;
   if (~isempty(valueStr))
      netcdf.putVar(fCdf, netcdf.inqVarID(fCdf, 'REFERENCE_DATE_TIME'), 0, length(valueStr), valueStr);
   end
   valueStr = g_cocs_mono_sa_currentDate;
   if (~isempty(valueStr))
      netcdf.putVar(fCdf, netcdf.inqVarID(fCdf, 'DATE_CREATION'), 0, length(valueStr), valueStr);
   end
   valueStr = g_cocs_mono_sa_currentDate;
   if (~isempty(valueStr))
      netcdf.putVar(fCdf, netcdf.inqVarID(fCdf, 'DATE_UPDATE'), 0, length(valueStr), valueStr);
   end
   valueStr = a_profData.platformNumber;
   if (~isempty(valueStr))
      netcdf.putVar(fCdf, netcdf.inqVarID(fCdf, 'PLATFORM_NUMBER'), [0 0], fliplr([1 length(valueStr)]), valueStr');
   end
   valueStr = a_profData.projectName;
   if (~isempty(valueStr))
      netcdf.putVar(fCdf, netcdf.inqVarID(fCdf, 'PROJECT_NAME'), [0 0], fliplr([1 length(valueStr)]), valueStr');
   end
   valueStr = a_profData.piName;
   if (~isempty(valueStr))
      netcdf.putVar(fCdf, netcdf.inqVarID(fCdf, 'PI_NAME'), [0 0], fliplr([1 length(valueStr)]), valueStr');
   end
   stationParametersVarId = netcdf.inqVarID(fCdf, 'STATION_PARAMETERS');
   for idParam = 1:length(paramList)
      valueStr = paramList{idParam};
      netcdf.putVar(fCdf, stationParametersVarId, ...
         fliplr([0 idParam-1 0]), fliplr([1 1 length(valueStr)]), valueStr');
   end
   value = a_profData.cycleNumber;
   if (~isempty(valueStr))
      netcdf.putVar(fCdf, netcdf.inqVarID(fCdf, 'CYCLE_NUMBER'), 0, length(value), value);
   end
   valueStr = a_profData.direction;
   if (~isempty(valueStr))
      netcdf.putVar(fCdf, netcdf.inqVarID(fCdf, 'DIRECTION'), 0, length(valueStr), valueStr);
   end
   valueStr = a_profData.dataCentre;
   if (~isempty(valueStr))
      netcdf.putVar(fCdf, netcdf.inqVarID(fCdf, 'DATA_CENTRE'), [0 0], fliplr([1 length(valueStr)]), valueStr');
   end
   valueStr = a_profData.paramDataMode;
   if (~isempty(valueStr))
      netcdf.putVar(fCdf, netcdf.inqVarID(fCdf, 'PARAMETER_DATA_MODE'), [0 0], fliplr([1 length(valueStr)]), valueStr');
   end
   valueStr = a_profData.platformType;
   if (~isempty(valueStr))
      netcdf.putVar(fCdf, netcdf.inqVarID(fCdf, 'PLATFORM_TYPE'), [0 0], fliplr([1 length(valueStr)]), valueStr');
   end
   valueStr = a_profData.floatSerialNo;
   if (~isempty(valueStr))
      netcdf.putVar(fCdf, netcdf.inqVarID(fCdf, 'FLOAT_SERIAL_NO'), [0 0], fliplr([1 length(valueStr)]), valueStr');
   end
   valueStr = a_profData.firmwareVersion;
   if (~isempty(valueStr))
      netcdf.putVar(fCdf, netcdf.inqVarID(fCdf, 'FIRMWARE_VERSION'), [0 0], fliplr([1 length(valueStr)]), valueStr');
   end
   valueStr = a_profData.wmoInstType;
   if (~isempty(valueStr))
      netcdf.putVar(fCdf, netcdf.inqVarID(fCdf, 'WMO_INST_TYPE'), [0 0], fliplr([1 length(valueStr)]), valueStr');
   end
   value = a_profData.juld;
   if (~isempty(valueStr))
      netcdf.putVar(fCdf, netcdf.inqVarID(fCdf, 'JULD'), 0, length(value), value);
   end
   valueStr = a_profData.juldQc;
   if (~isempty(valueStr))
      netcdf.putVar(fCdf, netcdf.inqVarID(fCdf, 'JULD_QC'), 0, length(valueStr), valueStr);
   end
   value = a_profData.juldLocation;
   if (~isempty(valueStr))
      netcdf.putVar(fCdf, netcdf.inqVarID(fCdf, 'JULD_LOCATION'), 0, length(value), value);
   end
   value = a_profData.latitude;
   if (~isempty(valueStr))
      netcdf.putVar(fCdf, netcdf.inqVarID(fCdf, 'LATITUDE'), 0, length(value), value);
   end
   value = a_profData.longitude;
   if (~isempty(valueStr))
      netcdf.putVar(fCdf, netcdf.inqVarID(fCdf, 'LONGITUDE'), 0, length(value), value);
   end
   valueStr = a_profData.positionQc;
   if (~isempty(valueStr))
      netcdf.putVar(fCdf, netcdf.inqVarID(fCdf, 'POSITION_QC'), 0, length(valueStr), valueStr);
   end
   valueStr = a_profData.positioningSystem;
   if (~isempty(valueStr))
      netcdf.putVar(fCdf, netcdf.inqVarID(fCdf, 'POSITIONING_SYSTEM'), [0 0], fliplr([1 length(valueStr)]), valueStr');
   end
   value = a_profData.configMissionNumber;
   if (~isempty(valueStr))
      netcdf.putVar(fCdf, netcdf.inqVarID(fCdf, 'CONFIG_MISSION_NUMBER'), 0, length(value), value);
   end

   % fill PARAM variable data
   for idParam = 1:length(paramList)

      paramDataMode = a_profData.paramDataMode(idParam);
      paramData = a_profData.paramData(:, idParam);
      paramDataQc = a_profData.paramDataQc(:, idParam);
      paramDataDPres = a_profData.paramDataDPres(:, idParam);
      paramDataAdj = a_profData.paramDataAdjusted(:, idParam);
      paramDataAdjQc = a_profData.paramDataAdjustedQc(:, idParam);
      paramDataAdjErr = a_profData.paramDataAdjustedError(:, idParam);

      paramName = paramList{idParam};
      paramQcName = [paramName '_QC'];
      if (~strcmp(paramName, 'PRES'))
         paramDPresName = [paramName '_dPRES'];
      end
      paramAdjName = [paramName '_ADJUSTED'];
      paramAdjQcName = [paramName '_ADJUSTED_QC'];
      paramAdjErrName = [paramName '_ADJUSTED_ERROR'];

      % global quality of PARAM profile
      if (paramDataMode == 'R')
         profParamQcData = compute_profile_quality_flag(paramDataQc);
      else
         profParamQcData = compute_profile_quality_flag(paramDataAdjQc);
      end
      profParamQcName = ['PROFILE_' paramName '_QC'];
      netcdf.putVar(fCdf, netcdf.inqVarID(fCdf, profParamQcName), 0, 1, profParamQcData);

      % PARAM profile
      netcdf.putVar(fCdf, netcdf.inqVarID(fCdf, paramName), fliplr([0 0]), fliplr([1 length(paramData)]), paramData);
      netcdf.putVar(fCdf, netcdf.inqVarID(fCdf, paramQcName), fliplr([0 0]), fliplr([1 length(paramData)]), paramDataQc);
      if (~strcmp(paramName, 'PRES'))
         netcdf.putVar(fCdf, netcdf.inqVarID(fCdf, paramDPresName), fliplr([0 0]), fliplr([1 length(paramDataDPres)]), paramDataDPres);
      end

      netcdf.putVar(fCdf, netcdf.inqVarID(fCdf, paramAdjName), fliplr([0 0]), fliplr([1 length(paramDataAdj)]), paramDataAdj);
      netcdf.putVar(fCdf, netcdf.inqVarID(fCdf, paramAdjQcName), fliplr([0 0]), fliplr([1 length(paramDataAdj)]), paramDataAdjQc);
      netcdf.putVar(fCdf, netcdf.inqVarID(fCdf, paramAdjErrName), fliplr([0 0]), fliplr([1 length(paramDataAdjErr)]), paramDataAdjErr);
   end

   % fill SCIENTIFIC_CALIB_* variable data
   [~, nCalibDim] = netcdf.inqDim(fCdf, netcdf.inqDimID(fCdf, 'N_CALIB'));
   parameterVarId = netcdf.inqVarID(fCdf, 'PARAMETER');
   scientificCalibEquationVarId = netcdf.inqVarID(fCdf, 'SCIENTIFIC_CALIB_EQUATION');
   scientificCalibCoefficientVarId = netcdf.inqVarID(fCdf, 'SCIENTIFIC_CALIB_COEFFICIENT');
   scientificCalibCommentVarId = netcdf.inqVarID(fCdf, 'SCIENTIFIC_CALIB_COMMENT');
   scientificCalibDateVarId = netcdf.inqVarID(fCdf, 'SCIENTIFIC_CALIB_DATE');
   for idParam = 1:length(paramList)

      paramName = paramList{idParam};
      scientificCalibEquation = a_profData.scientificCalibEquation{idParam};
      scientificCalibCoefficient = a_profData.scientificCalibCoefficient{idParam};
      scientificCalibComment = a_profData.scientificCalibComment{idParam};
      scientificCalibDate = a_profData.scientificCalibDate{idParam};

      for idCalib = 1:nCalibDim
         netcdf.putVar(fCdf, parameterVarId, ...
            fliplr([0 idCalib-1 idParam-1 0]), fliplr([1 1 1 length(paramName)]), paramName');
      end
      for idCalib = 1:length(scientificCalibEquation)
         valueStr = scientificCalibEquation{idCalib};
         if (~isempty(valueStr))
            netcdf.putVar(fCdf, scientificCalibEquationVarId, ...
               fliplr([0 idCalib-1 idParam-1 0]), fliplr([1 1 1 length(valueStr)]), valueStr');
         end
         valueStr = scientificCalibCoefficient{idCalib};
         if (~isempty(valueStr))
            netcdf.putVar(fCdf, scientificCalibCoefficientVarId, ...
               fliplr([0 idCalib-1 idParam-1 0]), fliplr([1 1 1 length(valueStr)]), valueStr');
         end
         valueStr = scientificCalibComment{idCalib};
         if (~isempty(valueStr))
            netcdf.putVar(fCdf, scientificCalibCommentVarId, ...
               fliplr([0 idCalib-1 idParam-1 0]), fliplr([1 1 1 length(valueStr)]), valueStr');
         end
         valueStr = scientificCalibDate{idCalib};
         if (~isempty(valueStr))
            netcdf.putVar(fCdf, scientificCalibDateVarId, ...
               fliplr([0 idCalib-1 idParam-1 0]), fliplr([1 1 1 length(valueStr)]), valueStr');
         end
      end
   end

   % close NetCDF file
   netcdf.close(fCdf);

catch MException
   netcdf.close(fCdf);
   rethrow(MException)
end

return

%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
% The following functions are duplicated from Coriolis Argo decoder distribution
% to generate a stand-alone version of the current tool.
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%

%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
% The following code is under the responsibility of Henry Bittig
% <henry.bittig@io-warnemuende.de>
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%

function synthfull=ARGO_simplified_profile(varargin)
%
%
% create simplified Biogeochemical-Argo single cycle file from DAC c- and
% b- files with synthetic pressure axis
%
% - synthetic axis constructed from data
% - include CONFIG_<short_sensor_name>VerticalPressureOffset_dbar from
% WMO_meta.nc if present in meta file
% - obey n_prof priorities (needs WMO_meta.nc)
% - single gaps in series of 5 filled with interpolated data
% - interleave non-BGC level T/S profile for full T/S resolution
%
% inputs: - 'bfilepath', 'cfilepath' (one of them is mandatory)
%         - 'metafilepath' (optional)
%         - 'bgcFloatFlag' (optional; default true): by setting to zero,
%            all parts on synthetic axis construction can be skipped in
%            case the float is core-only and N_PROFs of core data should be
%            combined anyway
% 
% usage: 
% out=ARGO_simplified_profile('bfilepath','BR6901485_050.nc');
% out=ARGO_simplified_profile('bfilepath','6901485/profiles/BR6901485_050.nc');
% out=ARGO_simplified_profile('bfilepath','argo/coriolis/6901485/profiles/BR6901485_050.nc','cfilepath','argo/coriolis/6901485/profiles/R6901485_050.nc','metafilepath','argo/coriolis/6901485/6901485_meta.nc');
%
%
% Henry Bittig, LOV/IOW
% 18.01.2018
% 05.03.2018, updated
% 19.04.2018, use b- and c- files instead of m-files
% 15.06.2018, modify input to name/value pairs
% 27.06.2018, make approach more robust: Union of PARAMETER and STATION_PARAMETERS, 
%             only apply vertical offsets for sensors with data, be tolerant towards 
%             older, pre-v3.1 meta files
% 29.06.2018, separate PARAM and PARAM_ADJUSTED overlap determination, using no bad PRES_QC
% 11.02.2019, following ADMT in San Diego: include HR T/S profile at end;
%             rework code for R2018b; recognize netcdf dim order
% 18.02.2019, streamlining of code
% 30.06.2020, create s-profile also in absence of BGC-levels or in the
%             absence of either core- or b-profile, gap data do not get a
%             QC of '8' if either bounding point has QC '3' or '4', PRES/
%             PRES_ADJUSTED do not get a QC of '8' either, add file name to
%             all info messages, correct treatment of levels with QC '4' in
%             adjusted fields, add bgcFloatFlag as optional input
% 01.04.2022, gap data do not get a QC of '8' if either bounding point has
%             QC '0', PRES/PRES_ADJUSTED do not get a QC of '8' either
% 09.06.2022, add Coriolis csv export accessories to git-controlled local version
% 09.06.2022, remove ic parameters TEMP_CNDC, MTIME, NB_sample_... and
%             statistical parameters ..._MED, ..._STD from parameter selection
% 01.12.2023, fix to keep vertical pressure offset on PRES for profiles
%             with only one synthetic pressure level
% 11.01.2024, PRES may be non-monotonic with revised pressure increasing
%             test 08 - remove internal pressure inversion test and prepare
%             code for repeated pressures: aggregate with nanmean
% 12.05.2025, allow multiple occurences of the same sensor type in the
%             launch configuration's list of VerticalPressureOffset_dbar in
%             the meta file, e.g., DOXY as well as DOXY2 or DOXY_2

% output CSV file information
global g_cocs_mono_sa_fidCsvFile;
global g_cocs_mono_sa_dacName;
global g_cocs_mono_sa_floatWmoStr;
global g_cocs_mono_sa_cycleNumStr;
global g_cocs_mono_sa_cycleDir;
global g_cocs_mono_sa_inputFile;

if nargin<1 || isempty(varargin)
    varargin{1}='bfilepath';varargin{2}='\argo\dac\coriolis\6901485\profiles\BR6901485_049.nc';
end

includeTSflag=0;
addTSeverywhere=1;
verbose=1;
addoffsetflag=1;  % add pressure sensor vertical pressure offset to PRES

fieldsuffixvarname={'PRES';'BBP[0-9]+';'BISULFIDE';'CDOM';'CHLA';'CP[0-9]+';'DOWN_IRRADIANCE[0-9]+';'DOWNWELLING_PAR';'DOXY';'NITRATE';'PH_IN_SITU_TOTAL';'TURBIDITY';'UP_RADIANCE[0-9]+';};
%% get file names
bfilepath='';cfilepath='';metafilepath='';
bgcfloatflag=true(1);
for i=1:floor(length(varargin)/2)
    switch varargin{2*i-1}
        case 'bfilepath'
            bfilepath=varargin{2*i};
        case 'cfilepath'
            cfilepath=varargin{2*i};
        case 'metafilepath'
            metafilepath=varargin{2*i};
        case 'bgcFloatFlag'
            bgcfloatflag=varargin{2*i};
    end
end
if isempty(cfilepath) && isempty(bfilepath) % either profile file must be present
    if verbose>-2, disp(['S-PROF_ERROR: Either core-profile or b-profile path must be specified. Abort..']), end
    synthfull=[];
    return
end
if isempty(cfilepath)
% figure out name of the corresponding core file
[basepath,fname]=fileparts(bfilepath);
fnamec=dir([basepath filesep 'R' fname(3:end) '.nc']);
if isempty(fnamec), fnamec=dir([basepath filesep 'D' fname(3:end) '.nc']); end
if ~isempty(fnamec), cfilepath=[basepath filesep fnamec.name]; end
clear fnamec fname basepath
end
if isempty(bfilepath) && bgcfloatflag
% figure out name of the corresponding bgc file
[basepath,fname]=fileparts(cfilepath);
fnameb=dir([basepath filesep 'BR' fname(2:end) '.nc']);
if isempty(fnameb), fnameb=dir([basepath filesep 'BD' fname(2:end) '.nc']); end
if ~isempty(fnameb), bfilepath=[basepath filesep fnameb.name]; end
clear fnameb fname basepath
end
% keep b- and core-file names for error/warning/info reporting
[~,bfilestr]=fileparts(bfilepath);
[~,cfilestr]=fileparts(cfilepath);

%% load b-file netcdf into convenient structure
if ~isempty(bfilepath) % b-file exists
    S=lov_netcdf_pickprod(bfilepath);
    % remove everything but PRES and b-parameters
    fnames=fieldnames(S);
    fnamesind=true(size(fnames));
    for k=1:length(fieldsuffixvarname)
        fnamesind(~cellfun(@isempty,regexp(fnames,['^' fieldsuffixvarname{k} '$*'])))=0; % normal variable
        fnamesind(~cellfun(@isempty,regexp(fnames,['^' fieldsuffixvarname{k} '[0-9]+$*'])))=0; % multiple variable
        fnamesind(~cellfun(@isempty,regexp(fnames,['^' fieldsuffixvarname{k} '_[0-9]+$*'])))=0; % multiple variable with underscore
    end
    fnamesind(ismember(fnames,'PARAMETER'))=0; % keep PARAMETER field, too: Used for N_PROF identification
    fnamesind(ismember(fnames,'STATION_PARAMETERS'))=0; % keep STATION_PARAMETERS field, too: Used for backup N_PROF identification
    if isempty(cfilepath) % c-file does not exists
        %fnamesind(:)=0; % keep all other meta fields, too; Can't be copied from core file...
        fnamesind(ismember(fnames,'PLATFORM_NUMBER'))=0; % keep WMO
    end
    S=rmfield(S,fnames(fnamesind));
else % b-file does not exist
    S.empty=[];
end
%% load c-file netcdf and add core data into convenient structure
if ~isempty(cfilepath) % c-file exists
    C=lov_netcdf_pickprod(cfilepath); % load core file
    fnamec=setdiff(fieldnames(C),fieldnames(S)); % find core parameter names
    for i=1:length(fnamec), S.(fnamec{i})=C.(fnamec{i}); end % copy core data to bio data
else
    if (verbose>-2)
       disp(['S-PROF_WARNING: File ' bfilestr '.nc: No corresponding core file found. Create empty s-profile.'])
       
       % CSV output
       msgType = 'warning_s-prof';
       message = 'No corresponding core file found. Create empty s-profile.';
       [~, fileName, fileExt] = fileparts(bfilepath);
       g_cocs_mono_sa_inputFile  = [fileName fileExt];
       if ~isempty(g_cocs_mono_sa_fidCsvFile) && g_cocs_mono_sa_fidCsvFile>0 % g_cocs_mono_sa_fidCsvFile points to a valid file identifier
          fprintf(g_cocs_mono_sa_fidCsvFile, '%s,%s,%s,%s%s,%s,%s\n', ...
             g_cocs_mono_sa_dacName, msgType, g_cocs_mono_sa_floatWmoStr, g_cocs_mono_sa_cycleNumStr, g_cocs_mono_sa_cycleDir, message, g_cocs_mono_sa_inputFile);
       end
    end
    S.PRES_QC.value=ones(size(S.PRES.value))*4; % mimic core PRES_QC: all bad, because no info
end
if isfield(S,'empty') && bgcfloatflag
    if (verbose>-2)
       disp(['S-PROF_WARNING: File ' cfilestr '.nc: No corresponding bio file found. Use only the core file.'])
       
       % CSV output
       msgType = 'warning_s-prof';
       message = 'No corresponding bio file found. Use only the core file.';
       [~, fileName, fileExt] = fileparts(cfilepath);
       g_cocs_mono_sa_inputFile  = [fileName fileExt];
       if ~isempty(g_cocs_mono_sa_fidCsvFile) && g_cocs_mono_sa_fidCsvFile>0 % g_cocs_mono_sa_fidCsvFile points to a valid file identifier
          fprintf(g_cocs_mono_sa_fidCsvFile, '%s,%s,%s,%s%s,%s,%s\n', ...
             g_cocs_mono_sa_dacName, msgType, g_cocs_mono_sa_floatWmoStr, g_cocs_mono_sa_cycleNumStr, g_cocs_mono_sa_cycleDir, message, g_cocs_mono_sa_inputFile);
       end
    end
    S=rmfield(S,'empty');
end

%% make sure first dimension is size of field, i.e., STRING16/STRING64 for
% PARAMETER and STATION_PARAMETER in c- and b-file
% (e.g. CS 1901348: 2nd dimension)
%% core file
% dimnames must be fliplr of user manual description:
% 'char PARAMETER(N_PROF, N_CALIB, N_PARAM, STRING16);'
if ~isempty(cfilepath) % core file exists
indstr={'STRING16';'N_PARAM';'N_CALIB';'N_PROF'};
indperm=ones(ndims(C.PARAMETER.value),1)*NaN; 
try
    for i=1:length(indperm), indperm(i)=find(strcmpi(C.PARAMETER.dimname,indstr{i})); end
catch me
    if (verbose>-1)
       disp(['S-PROF_WARNING: File ' cfilestr '.nc: Could not figure out N_DIMs order of core file PARAMETER field with dimensions: ' strjoin(C.PARAMETER.dimname,', ')])
       
       % CSV output
       msgType = 'warning_s-prof';
       message = sprintf('Could not figure out N_DIMs order of core file PARAMETER field with dimensions: %s.', ...
          strjoin(C.PARAMETER.dimname,' '));
       [~, fileName, fileExt] = fileparts(cfilepath);
       g_cocs_mono_sa_inputFile  = [fileName fileExt];
       if ~isempty(g_cocs_mono_sa_fidCsvFile) && g_cocs_mono_sa_fidCsvFile>0 % g_cocs_mono_sa_fidCsvFile points to a valid file identifier
          fprintf(g_cocs_mono_sa_fidCsvFile, '%s,%s,%s,%s%s,%s,%s\n', ...
             g_cocs_mono_sa_dacName, msgType, g_cocs_mono_sa_floatWmoStr, g_cocs_mono_sa_cycleNumStr, g_cocs_mono_sa_cycleDir, message, g_cocs_mono_sa_inputFile);
       end
    end
    indperm=1:ndims(C.PARAMETER.value);
end
C.PARAMETER.value=permute(C.PARAMETER.value,indperm);
C.PARAMETER.dimname=C.PARAMETER.dimname(indperm);
C.PARAMETER.dimvalue=C.PARAMETER.dimvalue(indperm);
% 'char STATION_PARAMETERS(N_PROF, N_PARAM, STRING16);'
indstr={'STRING16';'N_PARAM';'N_PROF'};
indperm=ones(ndims(C.STATION_PARAMETERS.value),1)*NaN; 
try
    for i=1:length(indperm), indperm(i)=find(strcmpi(C.STATION_PARAMETERS.dimname,indstr{i})); end
catch me
    if (verbose>-1)
       disp(['S-PROF_WARNING: File ' cfilestr '.nc: Could not figure out N_DIMs order of core file STATION_PARAMETERS field with dimensions: ' strjoin(C.PARAMETER.dimname,', ')])
    
       % CSV output
       msgType = 'warning_s-prof';
       message = sprintf('Could not figure out N_DIMs order of core file STATION_PARAMETERS field with dimensions: %s.', ...
          strjoin(C.PARAMETER.dimname,' '));
       [~, fileName, fileExt] = fileparts(cfilepath);
       g_cocs_mono_sa_inputFile  = [fileName fileExt];
       if ~isempty(g_cocs_mono_sa_fidCsvFile) && g_cocs_mono_sa_fidCsvFile>0 % g_cocs_mono_sa_fidCsvFile points to a valid file identifier
          fprintf(g_cocs_mono_sa_fidCsvFile, '%s,%s,%s,%s%s,%s,%s\n', ...
             g_cocs_mono_sa_dacName, msgType, g_cocs_mono_sa_floatWmoStr, g_cocs_mono_sa_cycleNumStr, g_cocs_mono_sa_cycleDir, message, g_cocs_mono_sa_inputFile);
       end
    end
    indperm=1:ndims(C.STATION_PARAMETERS.value);
end
C.STATION_PARAMETERS.value=permute(C.STATION_PARAMETERS.value,indperm);
C.STATION_PARAMETERS.dimname=C.STATION_PARAMETERS.dimname(indperm);
C.STATION_PARAMETERS.dimvalue=C.STATION_PARAMETERS.dimvalue(indperm);
else % core file does not exist
    C.PARAMETER.value(:,1,1,1)='PRES'; % mimic only-PRES entry for smooth operation of code below
    C.STATION_PARAMETERS.value(:,1,1)=C.PARAMETER.value(:,:,1,:);
end % core file exists
%% b-file
% 'char PARAMETER(N_PROF, N_CALIB, N_PARAM, STRING64);'
if ~isempty(bfilepath) % bio file exists
indstr={'STRING64';'N_PARAM';'N_CALIB';'N_PROF'};
indperm=ones(ndims(S.PARAMETER.value),1)*NaN; 
try
    for i=1:length(indperm), indperm(i)=find(strcmpi(S.PARAMETER.dimname,indstr{i})); end
catch me
    if (verbose>-1)
       disp(['S-PROF_WARNING: File ' bfilestr '.nc: Could not figure out N_DIMs order of bio file PARAMETER field with dimensions: ' strjoin(S.PARAMETER.dimname,', ')])
       
       % CSV output
       msgType = 'warning_s-prof';
       message = sprintf('Could not figure out N_DIMs order of bio file PARAMETER field with dimensions: %s.', ...
          strjoin(S.PARAMETER.dimname,' '));
       [~, fileName, fileExt] = fileparts(bfilepath);
       g_cocs_mono_sa_inputFile  = [fileName fileExt];
       if ~isempty(g_cocs_mono_sa_fidCsvFile) && g_cocs_mono_sa_fidCsvFile>0 % g_cocs_mono_sa_fidCsvFile points to a valid file identifier
          fprintf(g_cocs_mono_sa_fidCsvFile, '%s,%s,%s,%s%s,%s,%s\n', ...
             g_cocs_mono_sa_dacName, msgType, g_cocs_mono_sa_floatWmoStr, g_cocs_mono_sa_cycleNumStr, g_cocs_mono_sa_cycleDir, message, g_cocs_mono_sa_inputFile);
       end
    end
    indperm=1:ndims(S.PARAMETER.value);
end
S.PARAMETER.value=permute(S.PARAMETER.value,indperm);
S.PARAMETER.dimname=S.PARAMETER.dimname(indperm);
S.PARAMETER.dimvalue=S.PARAMETER.dimvalue(indperm);
% 'char STATION_PARAMETERS(N_PROF, N_PARAM, STRING64);'
indstr={'STRING64';'N_PARAM';'N_PROF'};
indperm=ones(ndims(S.STATION_PARAMETERS.value),1)*NaN; 
try
    for i=1:length(indperm), indperm(i)=find(strcmpi(S.STATION_PARAMETERS.dimname,indstr{i})); end
catch me
    if (verbose>-1)
       disp(['S-PROF_WARNING: File ' bfilestr '.nc: Could not figure out N_DIMs order of bio file STATION_PARAMETERS field with dimensions: ' strjoin(S.PARAMETER.dimname,', ')])
       
       % CSV output
       msgType = 'warning_s-prof';
       message = sprintf('Could not figure out N_DIMs order of bio file STATION_PARAMETERS field with dimensions: %s.', strjoin(S.PARAMETER.dimname,' '));
       [~, fileName, fileExt] = fileparts(bfilepath);
       g_cocs_mono_sa_inputFile  = [fileName fileExt];
       if ~isempty(g_cocs_mono_sa_fidCsvFile) && g_cocs_mono_sa_fidCsvFile>0 % g_cocs_mono_sa_fidCsvFile points to a valid file identifier
          fprintf(g_cocs_mono_sa_fidCsvFile, '%s,%s,%s,%s%s,%s,%s\n', ...
             g_cocs_mono_sa_dacName, msgType, g_cocs_mono_sa_floatWmoStr, g_cocs_mono_sa_cycleNumStr, g_cocs_mono_sa_cycleDir, message, g_cocs_mono_sa_inputFile);
       end
    end
    indperm=1:ndims(S.STATION_PARAMETERS.value);
end
S.STATION_PARAMETERS.value=permute(S.STATION_PARAMETERS.value,indperm);
S.STATION_PARAMETERS.dimname=S.STATION_PARAMETERS.dimname(indperm);
S.STATION_PARAMETERS.dimvalue=S.STATION_PARAMETERS.dimvalue(indperm);
end % bio file exists
clear indperm indstr
%%{
%% merge PARAMETER and STATION_PARAMETERS field for each N_PROF
% (used for variable identification later on)
for i=1:size(C.PARAMETER.value,4) % cycle N_PROFs, use first N_CALIB (necessarily contains all bgc variables)
    % check PARAMETER and STATION_PARAMETERS
    inparams=union(cellstr(squeeze(S.PARAMETER.value(:,:,1,i))'),cellstr(squeeze(S.STATION_PARAMETERS.value(:,:,i))'));
    inparamsC=union(cellstr(squeeze(C.PARAMETER.value(:,:,1,i))'),cellstr(squeeze(C.STATION_PARAMETERS.value(:,:,i))'));
    if isempty(char(setdiff(inparams,{'PRES';'TEMP';'PSAL';''}))) % only PRES/TEMP/PSAL -> core N_PROF: Copy core parameters
        S.PARAMETER.value(1:size(C.PARAMETER.value(:,:,1,i),1),1:size(C.PARAMETER.value(:,:,1,i),2),1:size(C.PARAMETER.value(:,:,1,i),3),i)=C.PARAMETER.value(:,:,1,i);
        %S.PARAMETER_DATA_MODE.value(i,1:size(C.PARAMETER.value(:,:,1,i),2))=C.DATA_MODE.value(i);
    elseif isempty(char(strrep(inparamsC,'PRES',''))) % only PRES & bio -> bio N_PROF: Keep bio parameters
        % nothing to do, PRES & bio already in S.PARAMETER.value
    else % core and bio N_PROF: Join core and bio parameters
        S.PARAMETER.value(1:size(C.PARAMETER.value(:,:,1,i),1),size(S.PARAMETER.value(:,:,1,i),2)+(2:size(C.PARAMETER.value(:,:,1,i),2))-1,1:size(C.PARAMETER.value(:,:,1,i),3),i)=C.PARAMETER.value(:,2:end,1,i);
    end
end
%%}
clear fnamec fnames fnamesind

%% get bgcparams names and N_PROFs
[noNLEVELs,noNPROFs]=size(S.PRES.value);
bgcflag=false(1,noNPROFs);
bgcparams=cell(1,noNPROFs);
% check that there are params different than PRES, TEMP, PSAL in N_PROF
for i=1:noNPROFs
    inparams=union(cellstr(S.PARAMETER.value(:,:,1,i)'),cellstr(S.STATION_PARAMETERS.value(:,:,i)')); % check PARAMETER and STATION_PARAMETERS
    bgcparams{i}=setdiff(inparams,{'PRES';'TEMP';'PSAL';''});
    bgcflag(i)=~isempty(bgcparams{i});
end
% and kick out the i-parameters again / keep only the b-parameters
fnamesind=cellfun(@(x)false(size(x)),bgcparams,'uniform',0);
for k=1:length(fieldsuffixvarname)
    fnamesind=cellfun(@(x,y)y | ~cellfun(@isempty,regexp(x,['^' fieldsuffixvarname{k} '$*'])),bgcparams,fnamesind,'uniform',0); % normal variable
    fnamesind=cellfun(@(x,y)y | ~cellfun(@isempty,regexp(x,['^' fieldsuffixvarname{k} '[0-9]+$*'])),bgcparams,fnamesind,'uniform',0);  % multiple variable
    fnamesind=cellfun(@(x,y)y | ~cellfun(@isempty,regexp(x,['^' fieldsuffixvarname{k} '_[0-9]+$*'])),bgcparams,fnamesind,'uniform',0);  % multiple variable with underscore
end
bgcparams=cellfun(@(x,y)x(y),bgcparams,fnamesind,'uniform',0);
% unique BGC parameters
ubgcparams=unique(cat(1, bgcparams{:}));
% without any intermediate core ic parameter: TEMP_CNDC, MTIME, NB_sample_...,
ikeep=~ismember(ubgcparams,{'TEMP_CNDC';'MTIME'}) & cellfun(@isempty,regexpi(ubgcparams,'^NB_SAMPLE_'));
ubgcparams=ubgcparams(ikeep);
% without any statistical parameter: ..._MED, ..._STD
ikeep=cellfun(@isempty,regexpi(ubgcparams,'_MED$')) & cellfun(@isempty,regexpi(ubgcparams,'_STD$'));
ubgcparams=ubgcparams(ikeep);
clear ikeep
% --> unique BGC b parameters


%% make check: are there bgc-params in the file??
if isempty(ubgcparams) % there are no bgc-params to align
    %if verbose>-1, disp(['S-PROF_INFO: File ' bfilestr '.nc: No b-parameters found in ' bfilepath]), end
    %synthfull=[]; return
    addoffsetflag=0; % then skip vertical offset stuff for BGC sensors, only CTD (TEMP_MED/STD, PSAL_MED/STD, or MTIME)
end


%% there are b-params to align and all infos are there, do the actual work

%% use copy of pressure to work with; rounded to 1/1000 to avoid numerical ..1e-6 issues
FV=-99999;
S.PRES.value=int32(1000*S.PRES.value); % cast truly to "1/1000" integer to avoid numerical ..1e-6 issues

% check that b-PRES and c-PRES_QC sizes match
if any(size(S.PRES.value)~=size(S.PRES_QC.value))
    %{
    if verbose>-2, disp(['S-PROF_ERROR: File ' bfilestr '.nc: PRES (bio) and PRES_QC (core) dimensions don''t match. Set all PRES_QC=4 and create empty s-profile.']), end
    %synthfull=[];
    %return
    S.PRES_QC.value=ones(size(S.PRES.value))*4;
    if isfield(S,'TEMP'), S=rmfield(S,'TEMP'); end
    if isfield(S,'PSAL'), S=rmfield(S,'PSAL'); end
    %}
    if (verbose>-2)
       disp(['S-PROF_WARNING: File ' bfilestr '.nc: PRES (bio) and PRES_QC (core) dimensions don''t match. Create synthetic profile only with available core data.'])
       
       % CSV output
       msgType = 'warning_s-prof';
       message = 'PRES (bio) and PRES_QC (core) dimensions don''t match. Create synthetic profile only with available core data.';
       [~, fileName, fileExt] = fileparts(bfilepath);
       g_cocs_mono_sa_inputFile  = [fileName fileExt];
       if ~isempty(g_cocs_mono_sa_fidCsvFile) && g_cocs_mono_sa_fidCsvFile>0 % g_cocs_mono_sa_fidCsvFile points to a valid file identifier
          fprintf(g_cocs_mono_sa_fidCsvFile, '%s,%s,%s,%s%s,%s,%s\n', ...
             g_cocs_mono_sa_dacName, msgType, g_cocs_mono_sa_floatWmoStr, g_cocs_mono_sa_cycleNumStr, g_cocs_mono_sa_cycleDir, message, g_cocs_mono_sa_inputFile);
       end
    end
    S.PRES.value=int32(C.PRES.value);
    [noNLEVELs,noNPROFs]=size(S.PRES.value);
    for i=1:length(ubgcparams)
        S.(ubgcparams{i}).value=S.PRES_QC.value*NaN;
        S.([ubgcparams{i} '_QC']).value=S.PRES_QC.value*NaN;
        S.([ubgcparams{i} '_ADJUSTED']).value=S.PRES_QC.value*NaN;
        S.([ubgcparams{i} '_ADJUSTED_QC']).value=S.PRES_QC.value*NaN;
        S.([ubgcparams{i} '_ADJUSTED_ERROR']).value=S.PRES_QC.value*NaN;    
    end
    addoffsetflag=0;
end
clear C

%{
% double check pressure inversion test in profile (in a simplistic way): 
% Mustn't have repeated pressure levels with PRES_QC 0..3
% sometimes not properly flagged, e.g., D5903712_149.nc
pinversion=false(size(S.PRES.value));
ind=~isnan(S.PRES.value) & ismember(S.PRES_QC.value,[0 1 2 3]);
for i=1:size(S.PRES.value,2)
    pinversion(ind(:,i),i)=[diff(S.PRES.value(ind(:,i),i))<=0;0];
end
%pinversion=pinversion & ismember(S.PRES_QC.value,[0 1 2 3]);
if any(pinversion(:))
   if (verbose>1)
      disp(['S-PROF_INFO: File ' cfilestr '.nc: Found ' num2str(sum(pinversion(:))) ' levels with unflagged pressure inversions. Flag with PRES_QC=4.'])
      
      % CSV output
      msgType = 'info_s-prof';
      message = sprintf('Found %s levels with unflagged pressure inversions. Flag with PRES_QC=4.', ...
         num2str(sum(pinversion(:))));
      [~, fileName, fileExt] = fileparts(cfilepath);
      g_cocs_mono_sa_inputFile  = [fileName fileExt];
      if ~isempty(g_cocs_mono_sa_fidCsvFile) && g_cocs_mono_sa_fidCsvFile>0 % g_cocs_mono_sa_fidCsvFile points to a valid file identifier
         fprintf(g_cocs_mono_sa_fidCsvFile, '%s,%s,%s,%s%s,%s,%s\n', ...
            g_cocs_mono_sa_dacName, msgType, g_cocs_mono_sa_floatWmoStr, g_cocs_mono_sa_cycleNumStr, g_cocs_mono_sa_cycleDir, message, g_cocs_mono_sa_inputFile);
      end
    end
    S.PRES_QC.value(pinversion)=4;
    % check if there are more
    pnum=0;
    while any(pinversion(:))
        pinversion=false(size(S.PRES.value));
        ind=~isnan(S.PRES.value) & ismember(S.PRES_QC.value,[0 1 2 3]);
        for i=1:size(S.PRES.value,2)
            pinversion(ind(:,i),i)=[diff(S.PRES.value(ind(:,i),i))<=0;0];
        end
        if any(pinversion(:))
            %disp(['S-PROF_WARNING: File ' cfilestr '.nc: Found ' num2str(sum(pinversion(:))) ' more levels with unflagged pressure inversions. Flag with PRES_QC=4.'])
            S.PRES_QC.value(pinversion)=4;
            pnum=pnum+sum(pinversion(:));
        end
    end % while
    if (verbose>1 && pnum)
       disp(['S-PROF_INFO: File ' cfilestr '.nc: Found ' num2str(pnum) ' more levels with unflagged pressure inversions. Flag with PRES_QC=4.'])
       
       % CSV output
       msgType = 'info_s-prof';
       message = sprintf('Found %s more levels with unflagged pressure inversions. Flag with PRES_QC=4.', ...
          num2str(pnum));
       [~, fileName, fileExt] = fileparts(cfilepath);
       g_cocs_mono_sa_inputFile  = [fileName fileExt];
       if ~isempty(g_cocs_mono_sa_fidCsvFile) && g_cocs_mono_sa_fidCsvFile>0 % g_cocs_mono_sa_fidCsvFile points to a valid file identifier
          fprintf(g_cocs_mono_sa_fidCsvFile, '%s,%s,%s,%s%s,%s,%s\n', ...
             g_cocs_mono_sa_dacName, msgType, g_cocs_mono_sa_floatWmoStr, g_cocs_mono_sa_cycleNumStr, g_cocs_mono_sa_cycleDir, message, g_cocs_mono_sa_inputFile);
       end
    end
end % first iteration
clear pinversion ind pnum
%}

% sort out pressure axis and which N_PROF to use
% only use PRES_QC 0..3, ignore PRES_QC=4
inpres0=S.PRES.value; % keep a copy of pressure without vertical offset correction
inpres=S.PRES.value; % use copy of pressure to work with
pflag=ismember(S.PRES_QC.value,[0 1 2 3]); 
inpres(~pflag)=FV; 
inpres0(~pflag)=FV; 

% check where BGC samples are present (and not all NaN)
bgcpresence=false(size(S.PRES.value));
for i=1:length(ubgcparams)
    bgcpresence=bgcpresence | ~isnan(S.(ubgcparams{i}).value);
end

% ~includeTSflag: only use N_PROFs that have biogeochemical data, 
%                 ignore TEMP/PSAL-only N_PROFs for construction of synthetic axis
%if ~includeTSflag, inpres(:,~bgcflag)=NaN; end
if ~includeTSflag, inpres(:,~bgcflag)=FV; inpres(~bgcpresence)=FV; end

%% load meta file / check existence
if isempty(metafilepath)
% figure out location of the corresponding meta file
if ~isempty(bfilepath)
    [basepath,~]=fileparts(bfilepath);
else
    [basepath,~]=fileparts(cfilepath);
end
metafilepath=[basepath filesep char(cellstr(S.PLATFORM_NUMBER.value(1,:))) '_meta.nc'];
if ~(exist(metafilepath,'file'))
metafilepath=[basepath filesep '..' filesep char(cellstr(S.PLATFORM_NUMBER.value(1,:))) '_meta.nc'];
end
end
% keep meta-file names for error/warning/info reporting
[~,metafilestr]=fileparts(metafilepath);

C=[];
%infields={'LAUNCH_CONFIG_PARAMETER_NAME';'LAUNCH_CONFIG_PARAMETER_VALUE';'CONFIG_MISSION_NUMBER';'CONFIG_PARAMETER_NAME';'CONFIG_PARAMETER_VALUE'};
infields={'LAUNCH_CONFIG_PARAMETER_NAME';'LAUNCH_CONFIG_PARAMETER_VALUE';'PARAMETER';'PARAMETER_SENSOR';'FORMAT_VERSION'};
try 
    C=lov_netcdf_pickprod(metafilepath,infields);
catch me
    % failed to locate meta file
    if (verbose>-2)
       disp(['S-PROF_ERROR: Float ' strtrim(S.PLATFORM_NUMBER.value(1,:)) ': Could not find meta file ' metafilepath '. Abort..']);
       
      % CSV output
      msgType = 'error';
      message = 'File not found.';
      [~, fileName, fileExt] = fileparts(metafilepath);
      g_cocs_mono_sa_inputFile  = [fileName fileExt];
      if ~isempty(g_cocs_mono_sa_fidCsvFile) && g_cocs_mono_sa_fidCsvFile>0 % g_cocs_mono_sa_fidCsvFile points to a valid file identifier
         fprintf(g_cocs_mono_sa_fidCsvFile, '%s,%s,%s,%s%s,%s,%s\n', ...
            g_cocs_mono_sa_dacName, msgType, g_cocs_mono_sa_floatWmoStr, g_cocs_mono_sa_cycleNumStr, g_cocs_mono_sa_cycleDir, message, g_cocs_mono_sa_inputFile);
      end
    end
    synthfull=[];
    return
end
if isempty(C)
    if (verbose>-2)
       disp(['S-PROF_ERROR: Float ' strtrim(S.PLATFORM_NUMBER.value(1,:)) ': Could not find meta file ' strtrim(S.PLATFORM_NUMBER.value(1,:)) '_meta.nc in current or parent folder. Abort..']);
       
      % CSV output
      msgType = 'error';
      message = 'File not found.';
      g_cocs_mono_sa_inputFile  = [strtrim(S.PLATFORM_NUMBER.value(1,:)) '_meta.nc'];
      if ~isempty(g_cocs_mono_sa_fidCsvFile) && g_cocs_mono_sa_fidCsvFile>0 % g_cocs_mono_sa_fidCsvFile points to a valid file identifier
         fprintf(g_cocs_mono_sa_fidCsvFile, '%s,%s,%s,%s%s,%s,%s\n', ...
            g_cocs_mono_sa_dacName, msgType, g_cocs_mono_sa_floatWmoStr, g_cocs_mono_sa_cycleNumStr, g_cocs_mono_sa_cycleDir, message, g_cocs_mono_sa_inputFile);
      end
    end
    synthfull=[];
    return
end % meta file exists


%% split up pressure in each N_PROF for each parameter/sensor
% e.g. NITRATE and DOXY in same N_PROF can have different vertical offsets
if addoffsetflag
    linind=cellfun(@(x,y)repmat(x,length(y),1),num2cell(1:noNPROFs,1),bgcparams,'uniform',0); % index to N_PROF in #repetitions like bgcparams
    linbgcparams=cat(1, bgcparams{:});
    linind=cat(1, linind{:});
    inpres=inpres(:,linind); % repeat pressure for each b-parameter
end % split up N_PROFs only if vertical offsets are added per sensor

%%{
    %% check meta file for vertical pressure offsets
if addoffsetflag
if isfield(C,'LAUNCH_CONFIG_PARAMETER_NAME') % pre-v3.1 meta files might not have this field
    names=C.LAUNCH_CONFIG_PARAMETER_NAME.value;
    values=C.LAUNCH_CONFIG_PARAMETER_VALUE.value;
    %{
    % enforce all-caps writing for Ctd
    names=char(strrep(cellstr(names),'Ctd','CTD'));
    %}
    %% check each sensor short name for vertical offsets
    sensors={'CTD';'Optode';'Ocr';'Eco';'MCOMS';'FLNTU';'Crover';'Suna';'Isus'}; % sensor short name
    param_sensors={{'CTD_PRES';'CTD_TEMP';'CTD_CNDC';'CTD_PSAL'};...
        'OPTODE_DOXY';...
        {'RADIOMETER_DOWN_IRR<nnn>';'RADIOMETER_PAR'};...
        {'FLUOROMETER_CHLA';'FLUOROMETER_CDOM';'BACKSCATTERINGMETER_BBP<nnn>'};...
        {'FLUOROMETER_CHLA';'FLUOROMETER_CDOM';'BACKSCATTERINGMETER_BBP<nnn>'};...
        {'FLUOROMETER_CHLA';'BACKSCATTERINGMETER_TURBIDITY'};...
        'TRANSMISSOMETER_CP<nnn>';...
        {'SPECTROPHOTOMETER_NITRATE';'SPECTROPHOTOMETER_BISULFIDE'};...
        'SPECTROPHOTOMETER_NITRATE'};
    %params={'PSAL';'DOXY';'WELLING_';{'CHLA','BBP','CDOM'};{'CHLA','BBP'};'CP660';'NITRATE'}; % associated parameter
    % find occurences of search parameter
    cnames={'VerticalPressureOffset_dbar'};
    ind=find(~cellfun(@isempty,strfind(cellstr(lower(names)),lower(cnames{1})))); % ignore upper/lower case
    if any(ind)
        if (verbose>1)
           disp(['S-PROF_INFO: File ' metafilestr '.nc: Found ' num2str(length(ind)) ' VerticalOffsets'])
        
           % CSV output
           msgType = 'info_s-prof';
           message = sprintf('Found %s VerticalOffsets.', ...
              num2str(length(ind)));
           [~, fileName, fileExt] = fileparts(metafilestr);
           g_cocs_mono_sa_inputFile  = [fileName fileExt];
           if ~isempty(g_cocs_mono_sa_fidCsvFile) && g_cocs_mono_sa_fidCsvFile>0 % g_cocs_mono_sa_fidCsvFile points to a valid file identifier
              fprintf(g_cocs_mono_sa_fidCsvFile, '%s,%s,%s,%s%s,%s,%s\n', ...
                 g_cocs_mono_sa_dacName, msgType, g_cocs_mono_sa_floatWmoStr, g_cocs_mono_sa_cycleNumStr, g_cocs_mono_sa_cycleDir, message, g_cocs_mono_sa_inputFile);
           end
        end
        % get short sensor names and vertical offsets
        cpnamesfull=strrep(strrep(cellstr(lower(names(ind,:))),lower(cnames{1}),''),lower('CONFIG_'),'');
        % allow multiple sensors of the same parameter to occur (i.e., treat Optode2 or Optode_2 like Optode)
        cpnames=regexp(cpnamesfull,'_?\d*','split','forceCellOutput');
        cpnames=cellfun(@(x)x{1},cpnames,'uniform',0);
        cpnumbers=regexp(cpnamesfull,'_?\d*','match');
        voffset=values(ind);
        try % get corresponding full-length sensor name: index to param_sensors / sensors
            sensorind=cellfun(@(x)find(~cellfun(@isempty,strfind(lower(sensors),lower(x)))),cpnames);
        catch me
           if (verbose>0)
              disp(['S-PROF_WARNING: File ' bfilestr '.nc: Could not identify some short sensor name in meta file ' strjoin(cpnames,'; ')])
              
              % CSV output
              msgType = 'warning_s-prof';
              message = sprintf('Could not identify some short sensor name in meta file %s.', strjoin(cpnames,' '));
              [~, fileName, fileExt] = fileparts(bfilepath);
              g_cocs_mono_sa_inputFile  = [fileName fileExt];
              if ~isempty(g_cocs_mono_sa_fidCsvFile) && g_cocs_mono_sa_fidCsvFile>0 % g_cocs_mono_sa_fidCsvFile points to a valid file identifier
                 fprintf(g_cocs_mono_sa_fidCsvFile, '%s,%s,%s,%s%s,%s,%s\n', ...
                    g_cocs_mono_sa_dacName, msgType, g_cocs_mono_sa_floatWmoStr, g_cocs_mono_sa_cycleNumStr, g_cocs_mono_sa_cycleDir, message, g_cocs_mono_sa_inputFile);
              end
           end
        end
        % and assign vertical offset via full-length sensor name to
        % bgc parameters
        linvoffset=zeros(size(linbgcparams));
        C.PARAMETER.value=cellstr(C.PARAMETER.value); % make cellstr
        for i=1:length(sensorind) % cycle all vertical offsets
            %snames=param_sensors{sensorind(i)}; % associated param_sensor long names
            % allow multiple sensors of the same parameter to occur (i.e., treat Optode2 or Optode_2 like Optode)
            snames=[param_sensors{sensorind(i)} char(cpnumbers{i})]; % associated param_sensor long names, incl. numerical extension if present
            if iscell(snames) % sensor has multiple param_sensor names
                pind=false(length(C.PARAMETER.value),1);
                for k=1:length(snames) % find occurence of param_sensor name in meta file
                    %pind=pind | ~cellfun(@isempty,regexp(cellstr(C.PARAMETER_SENSOR.value),['^' strrep(snames{k},'<nnn>','[0-9][0-9][0-9]') '$*'])); % include secondary sensors..
                    pind=pind | ~cellfun(@isempty,regexp(cellstr(C.PARAMETER_SENSOR.value),['^' strrep(snames{k},'<nnn>','[0-9][0-9][0-9]') '$'])); % exclude secondary sensors
                end
            else
                %pind=~cellfun(@isempty,regexp(cellstr(C.PARAMETER_SENSOR.value),['^' strrep(snames,'<nnn>','[0-9][0-9][0-9]') '$*'])); % include secondary sensors..
                pind=~cellfun(@isempty,regexp(cellstr(C.PARAMETER_SENSOR.value),['^' strrep(snames,'<nnn>','[0-9][0-9][0-9]') '$'])); % exclude secondary sensors
            end % multiple or single param_sensor name
            if ~any(pind)
                %disp(['S-PROF_WARNING: File ' metafilestr '.nc: Could not identify parameter with sensor name(s) ' strjoin(cellstr(snames),', ')])
                %disp(['S-PROF_WARNING: File ' metafilestr '.nc: Skipping vertical offset of ' num2str(voffset(i)) ' dbar for ' strjoin(cellstr(snames),', ')])
                %keyboard
                %synthfull=[];
                %return
                if (verbose>0)
                   disp(['S-PROF_WARNING: File ' bfilestr '.nc: Could not identify parameter with sensor name(s) ' strjoin(cellstr(snames),', ') '; Skipping vertical offset of ' num2str(voffset(i)) ' dbar from LAUNCH_CONFIG'])
                
                   % CSV output
                   msgType = 'warning_s-prof';
                   message = sprintf('Could not identify parameter with sensor name(s) %s. Skipping vertical offset of %s dbar from LAUNCH_CONFIG.', ...
                      strjoin(cellstr(snames),' '), num2str(voffset(i)));
                   [~, fileName, fileExt] = fileparts(bfilepath);
                   g_cocs_mono_sa_inputFile  = [fileName fileExt];
                   if g_cocs_mono_sa_fidCsvFile>0 % g_cocs_mono_sa_fidCsvFile points to a valid file identifier
                      fprintf(g_cocs_mono_sa_fidCsvFile, '%s,%s,%s,%s%s,%s,%s\n', ...
                         g_cocs_mono_sa_dacName, msgType, g_cocs_mono_sa_floatWmoStr, g_cocs_mono_sa_cycleNumStr, g_cocs_mono_sa_cycleDir, message, g_cocs_mono_sa_inputFile);
                   end
                end
                
            else % found 
                pnames=C.PARAMETER.value(pind); % get i- and b- parameter names
                % fill in vertical offset
                linvoffset(ismember(linbgcparams,pnames))=voffset(i);
            end
            
            clear snames pind pnames 
        end % cycle all vertical offsets
            
        % and apply offset
        inpflag=inpres==FV;
        inpres=inpres+int32(1e3*ones(size(inpres,1),1)*linvoffset(:)');
        inpres(inpflag)=FV;
        
        % do some housekeeping
        voff.cpnames=cpnames;voff.voffset=voffset;
        voff.linbgcparams=reshape(linbgcparams,1,[]); voff.linvoffset=reshape(linvoffset,1,[]);
        clear inpflag cpnames sensorind voffset sensors param_sensors
    else
        if (verbose>1)
           disp(['S-PROF_INFO: File ' bfilestr '.nc: Found no verticalOffsets in meta file'])
        
           % CSV output
           msgType = 'info_s-prof';
           message = 'Found no VerticalOffsets in meta file.';
           [~, fileName, fileExt] = fileparts(bfilepath);
           g_cocs_mono_sa_inputFile  = [fileName fileExt];
           if g_cocs_mono_sa_fidCsvFile>0 % g_cocs_mono_sa_fidCsvFile points to a valid file identifier
              fprintf(g_cocs_mono_sa_fidCsvFile, '%s,%s,%s,%s%s,%s,%s\n', ...
                 g_cocs_mono_sa_dacName, msgType, g_cocs_mono_sa_floatWmoStr, g_cocs_mono_sa_cycleNumStr, g_cocs_mono_sa_cycleDir, message, g_cocs_mono_sa_inputFile);
           end
        end
        voff.linbgcparams={};voff.linvoffset=[];
    end % config name found
    clear ind cnames names values
else
   if (verbose>-1)
      disp(['S-PROF_INFO: File ' bfilestr '.nc: Could not find LAUNCH_CONFIG_PARAMETER_NAME in meta file (FORMAT_VERSION ' C.FORMAT_VERSION.value '). No vertical sensor offsets corrected.'])
      
      % CSV output
      msgType = 'info_s-prof';
      message = sprintf('Could not find LAUNCH_CONFIG_PARAMETER_NAME in meta file (FORMAT_VERSION %s). No vertical sensor offsets corrected.', ...
         C.FORMAT_VERSION.value);
      [~, fileName, fileExt] = fileparts(bfilepath);
      g_cocs_mono_sa_inputFile  = [fileName fileExt];
      if g_cocs_mono_sa_fidCsvFile>0 % g_cocs_mono_sa_fidCsvFile points to a valid file identifier
         fprintf(g_cocs_mono_sa_fidCsvFile, '%s,%s,%s,%s%s,%s,%s\n', ...
            g_cocs_mono_sa_dacName, msgType, g_cocs_mono_sa_floatWmoStr, g_cocs_mono_sa_cycleNumStr, g_cocs_mono_sa_cycleDir, message, g_cocs_mono_sa_inputFile);
      end
   end
    voff.linbgcparams={};voff.linvoffset=[];
end % LAUNCH_CONFIG_PARAMETER_NAME
end % addoffsetflag
%%}
%clear C 

%% try to construct synthetic pressure axis only for BGC floats, not if already known that it's a core-only float
if bgcfloatflag % BGC float
    
%% put extra loop around synthetic pressure axis construction - if failed, revert to core-only profile
for pconstr=1:1 % extra loop around presaxis construction
% get unique pressures (with or without TEMP/PSAL-only levels; see above)
%upres=unique(inpres(~isnan(inpres)));
upres=unique(inpres(inpres~=FV));
if isempty(upres)
    if verbose>0
        if isempty(ubgcparams)
            disp(['S-PROF_WARNING: File ' bfilestr '.nc: Found no b-parameters. Create synthetic profile only with available core data.'])
            
            % CSV output
            msgType = 'warning';
            message = 'Found no b-parameters. Create synthetic profile only with available core data.';
            [~, fileName, fileExt] = fileparts(bfilepath);
            g_cocs_mono_sa_inputFile  = [fileName fileExt];
            if g_cocs_mono_sa_fidCsvFile>0 % g_cocs_mono_sa_fidCsvFile points to a valid file identifier
               fprintf(g_cocs_mono_sa_fidCsvFile, '%s,%s,%s,%s%s,%s,%s\n', ...
                  g_cocs_mono_sa_dacName, msgType, g_cocs_mono_sa_floatWmoStr, g_cocs_mono_sa_cycleNumStr, g_cocs_mono_sa_cycleDir, message, g_cocs_mono_sa_inputFile);
            end
        else
            disp(['S-PROF_WARNING: File ' bfilestr '.nc: Found b-parameter(s) ' strjoin(ubgcparams,' ') ', but without any PRES_QC=0..3 and non-FillValue BGC data. Create synthetic profile only with available core data.'])
            
            % CSV output
            msgType = 'warning';
            message = sprintf('Found b-parameter(s) %s but without any PRES_QC=0..3 and non-FillValue BGC data. Create synthetic profile only with available core data.', ...
               strjoin(ubgcparams,' '));
            [~, fileName, fileExt] = fileparts(bfilepath);
            g_cocs_mono_sa_inputFile  = [fileName fileExt];
            if g_cocs_mono_sa_fidCsvFile>0 % g_cocs_mono_sa_fidCsvFile points to a valid file identifier
               fprintf(g_cocs_mono_sa_fidCsvFile, '%s,%s,%s,%s%s,%s,%s\n', ...
                  g_cocs_mono_sa_dacName, msgType, g_cocs_mono_sa_floatWmoStr, g_cocs_mono_sa_cycleNumStr, g_cocs_mono_sa_cycleDir, message, g_cocs_mono_sa_inputFile);
            end
        end
    end
    %synthfull=[]; return
    presaxis=[]; % default to empty presaxis
    break % extra loop around presaxis construction
end
% and check which pressure levels are present in which profile
prespresent=false(length(upres),size(inpres,2));
for i=1:size(inpres,2),prespresent(:,i)=ismember(upres,inpres(:,i));end

% verify that there are BGC observations, not just BGC N_PROFs
if ~any(prespresent(:)) % may not be needed; redundant
    if (verbose>0)
       disp(['S-PROF_WARNING: File ' bfilestr '.nc: Found b-parameter(s) ' strjoin(ubgcparams,' ') ', but without any non-FillValue data. Create synthetic profile only with available core data.'])
       
       % CSV output
       msgType = 'warning';
       message = sprintf('Found b-parameter(s) %s but without any non-FillValue data. Create synthetic profile only with available core data.', ...
          strjoin(ubgcparams,' '));
       [~, fileName, fileExt] = fileparts(bfilepath);
       g_cocs_mono_sa_inputFile  = [fileName fileExt];
       if g_cocs_mono_sa_fidCsvFile>0 % g_cocs_mono_sa_fidCsvFile points to a valid file identifier
          fprintf(g_cocs_mono_sa_fidCsvFile, '%s,%s,%s,%s%s,%s,%s\n', ...
             g_cocs_mono_sa_dacName, msgType, g_cocs_mono_sa_floatWmoStr, g_cocs_mono_sa_cycleNumStr, g_cocs_mono_sa_cycleDir, message, g_cocs_mono_sa_inputFile);
       end
    end
    %synthfull=[]; return
    presaxis=[]; % default to empty presaxis
    break % extra loop around presaxis construction
end

% get pressure differences between the levels in each N_PROF; use the
% minimum of preceeding/succeeding deltaPRES
valdp=ones(length(upres),size(inpres,2))*NaN;
for i=1:size(inpres,2)
    %%pres=inpres(~isnan(inpres(:,i)),i); 
    %pres=inpres(inpres(:,i)~=FV,i); 
    dpres=diff(upres(prespresent(:,i))); % use monotonic series of levels
    if ~isempty(dpres)
        valdp(prespresent(:,i),i)=min(abs([dpres(1);dpres]),abs([dpres;dpres(end)]));
	else
        %valdp(prespresent(:,i),i)=0;
        valdp(prespresent(:,i),i)=NaN;
    end
    clear pres dpres
end

% cycle through record from bottom
useind=false(size(upres));
i=length(upres); % start at bottom
niter=0;nitermax=length(upres)+1;
if all(isnan(valdp(:))) % each BGC obs has only one level - no way to jump/construct synthetic pressure axis
%presaxis=median(upres); % take median pressure
presaxis=upres(end); % take deepest pressure and align rest to this level
else % cycle pressure record
while ~isempty(i)
    niter=niter+1;
    useind(i)=1; % add current level to synthetic axis
    ind=find(upres>upres(i)-min(valdp(i,:)) & upres<=upres(i)); % get pressures that are within current level (included) and probably next level-min(dPRES) (excluded)
    % check if any of the intermittent levels has such a small dPRES, that
    % there will be a second observation within the current level-min(dPRES) "jump"
    obspresence=~isnan(valdp(ind,:)); % make presence of non-FillValue a logical array
    if ~isempty(ind) && any(sum(obspresence,1)>1) % there are other levels in between and they have more than one observation, i.e., a denser sampling interval
        % go to deepest upres that features a second observation in the
        % same N_PROF: sum #obs from bottom in each N_PROF, get max in each
        % line (upres), and jump to (deepest) line that has >1        
        i=ind(find(max(flipud(cumsum(flipud(obspresence),1)),[],2)>1,1,'last'));
        if isempty(i)
            %keyboard % should not happen?? Check code..
            if (verbose>-3)
               disp(['S-PROF_WARNING: File ' bfilestr '.nc: Trouble during creation of synthetic pressure axis. Create synthetic profile only with available core data.'])
               
               % CSV output
               msgType = 'warning';
               message = 'Trouble during creation of synthetic pressure axis. Create synthetic profile only with available core data.';
               [~, fileName, fileExt] = fileparts(bfilepath);
               g_cocs_mono_sa_inputFile  = [fileName fileExt];
               if g_cocs_mono_sa_fidCsvFile>0 % g_cocs_mono_sa_fidCsvFile points to a valid file identifier
                  fprintf(g_cocs_mono_sa_fidCsvFile, '%s,%s,%s,%s%s,%s,%s\n', ...
                     g_cocs_mono_sa_dacName, msgType, g_cocs_mono_sa_floatWmoStr, g_cocs_mono_sa_cycleNumStr, g_cocs_mono_sa_cycleDir, message, g_cocs_mono_sa_inputFile);
               end
            end
            %synthfull=[]; return
            useind=[]; % default to empty presaxis if failed
            break % loop of pressure levels from bottom
        end
    else % jump by at least current level+min(dPRES)
        if all(isnan(valdp(i,:))) % no min(dPRES) available for current level: 
            % jump to next level that has a non-NaN valdp
            i=find(upres<upres(i) & any(~isnan(valdp),2),1,'last');
        else % jump by at least current level+min(dPRES)
            i=find(upres<=upres(i)-min(valdp(i,:)),1,'last');
        end
    end
    clear obspresence
    if niter>nitermax
       if (verbose>-3)
          disp(['S-PROF_WARNING: File ' bfilestr '.nc: Exceeded maximum number of iterations in selection of synthetic pressure levels. Should not happen... Create synthetic profile only with available core data.'])
          
          % CSV output
          msgType = 'warning';
          message = 'Exceeded maximum number of iterations in selection of synthetic pressure levels. Should not happen... Create synthetic profile only with available core data.';
          [~, fileName, fileExt] = fileparts(bfilepath);
          g_cocs_mono_sa_inputFile  = [fileName fileExt];
          if g_cocs_mono_sa_fidCsvFile>0 % g_cocs_mono_sa_fidCsvFile points to a valid file identifier
             fprintf(g_cocs_mono_sa_fidCsvFile, '%s,%s,%s,%s%s,%s,%s\n', ...
                g_cocs_mono_sa_dacName, msgType, g_cocs_mono_sa_floatWmoStr, g_cocs_mono_sa_cycleNumStr, g_cocs_mono_sa_cycleDir, message, g_cocs_mono_sa_inputFile);
          end
       end
        %synthfull=[]; return
        useind=[]; % default to empty presaxis if failed
        break % loop of pressure levels from bottom
    end
end
clear niter nitermax
presaxis=upres(useind);
end % pressure axis cycle from bottom possible?

end % extra loop around presaxis construction, default to empty presaxis if failed
%% done with synthetic pressure axis construction, now prepare to fill/align BGC data

else % no BGC float, core only; no additional messages for failed synthetic axis construction
    presaxis=[]; % default to empty presaxis
end % extra check for BGC float via function input parameter 'bgcFloatFlag'


%% get N_PROF priority from meta file (alphabetical by sensor name)
nprofstr=cell(1,noNPROFs);
params=cellstr(C.PARAMETER.value);
if isfield(C,'PARAMETER_SENSOR') % not a very old meta file
    paramsensors=cellstr(C.PARAMETER_SENSOR.value);
    for i=1:noNPROFs
        dummy=union(cellstr(S.PARAMETER.value(:,:,1,i)'),cellstr(S.STATION_PARAMETERS.value(:,:,i)'));
        nprofstr{i}=strjoin(sort(paramsensors(ismember(params,setdiff(dummy,'')))),'_');
    end
    % and bring into order but keeping nprof 1 at first position
    [~,asort]=sort(nprofstr(2:end));asort=[1 asort+1];
else % pre-v3.1 meta file
    if (verbose>0)
       disp(['S-PROF_WARNING: File ' bfilestr '.nc: Could not find PARAMETER_SENSOR in meta file (FORMAT_VERSION ' C.FORMAT_VERSION.value '). Kept N_PROF order as in profile file.'])
    
       % CSV output
       msgType = 'warning';
       message = sprintf('Could not find PARAMETER_SENSOR in meta file (FORMAT_VERSION %s). Kept N_PROF order as in profile file.', ...
          C.FORMAT_VERSION.value);
       [~, fileName, fileExt] = fileparts(bfilepath);
       g_cocs_mono_sa_inputFile  = [fileName fileExt];
       if g_cocs_mono_sa_fidCsvFile>0 % g_cocs_mono_sa_fidCsvFile points to a valid file identifier
          fprintf(g_cocs_mono_sa_fidCsvFile, '%s,%s,%s,%s%s,%s,%s\n', ...
             g_cocs_mono_sa_dacName, msgType, g_cocs_mono_sa_floatWmoStr, g_cocs_mono_sa_cycleNumStr, g_cocs_mono_sa_cycleDir, message, g_cocs_mono_sa_inputFile);
       end
    end
    asort=1:noNPROFs;
end % define N_PROF priority

%% define core parameters
%coreparams={'PRES';'TEMP';'PSAL'};
coreparams=intersect(fieldnames(S),{'PRES';'TEMP';'PSAL'});

% get non-overlapping pressure axis for core parameters
xpres=inpres0(:,asort); % keep original pressure
xpresqc=pflag(:,asort); % and flag to pressure that are not QC=4
for i=1:length(coreparams)
    
    %% extract data
    y=S.(coreparams{i}).value(:,asort);
    yqc=S.([coreparams{i} '_QC']).value(:,asort);
    %% check for overlapping portion of N_PROFs
    if ismember(coreparams{i},{'PRES'})
        overlap=true(size(y)); % pressures of different N_PROFs (almost) necessarily overlap
    else % not PRES
        % get max and min ranges per nprof
        xrange=ones(2,1+noNPROFs)*NaN;
        overlap=false(size(y)); % and flag portions that don't overlap
        for k=1:noNPROFs 
            ind=~isnan(y(:,k)) & xpresqc(:,k);
            if any(ind) % data in current nprof and with proper pres
                xrange(:,1+k)=[min(xpres(ind,k)); max(xpres(ind,k))]; 
                % check if it should be added or not
                if isnan(xrange(1,1)) % first nprof with data
                    xrange(:,1)=xrange(:,1+k);
                    overlap(:,k)=ind;
                else % more than one nprof with data: keep only data outside existing range
                    overlap(:,k)=ind & (xpres(:,k)>xrange(2,1) | xpres(:,k)<xrange(1,1));
                    xrange(1,1)=min([xrange(1,1) xrange(1,1+k)]);
                    xrange(2,1)=max([xrange(2,1) xrange(2,1+k)]);
                end
            end
        end % cycle all nprofs
        clear ind xrange
    end % overlapping portion
    %% do not use <PARAM>_QC of 8 or FillValue
    yflagqc=ismember(yqc,[0 1 2 3 4 5]);
    if ismember(coreparams{i},{'PRES'}), yflagnoFV=y~=FV; % double check PRES FV
    else, yflagnoFV=~isnan(y); end % and other FV (e.g., BR5900952_157, DOXY all NaN but QC=0)
    
    %% clean up: only data of current parameter without QC 8, only pflag
    x=xpres(xpresqc & yflagqc & yflagnoFV);
    %xqc=xpresqc(xpresqc & yflagqc);
    y=y(xpresqc & yflagqc & yflagnoFV);
    overlap=overlap(xpresqc & yflagqc & yflagnoFV);
    %yadjerrpresence=~all(isnan(yadjerr)); % error not mandatory for adjusted fields..
    clear yflagqc yflagnoFV yqc
    
    if ~isempty(y) % not only NaN/FV data
        % use only non-overlapping portion 
        x=x(overlap);
        clear overlap
        % make monotonic for interpolation (looses nprof priority!)
        [~,ind]=sort(x); % monotonic sorting
        x=x(ind);
        full.(coreparams{i}).x=x;
    else % empty pressure axis
        full.(coreparams{i}).x=int32([]);
    end % not only NaN/FV data
    clear x y 
end
clear xpres xpresqc
if ~isfield(full,'TEMP'), full.TEMP.x=[]; end % no core TEMP data (e.g. because of missing core file: kordi\2900608\profiles\BR2900608_077.nc
if ~isfield(full,'PSAL'), full.PSAL.x=[]; end % no core PSAL data (e.g. because of missing core file: kordi\2900608\profiles\BR2900608_077.nc

%% get all non-overlapping (HR-)TEMP/PSAL levels and synthetic pressure axis levels
presmerge=union(union(full.TEMP.x,full.PSAL.x),presaxis); % 'HR' T/S pressure axis and presaxis
% get indices for synthetic pressure axis
nosf=length(presmerge);
[~,synthind]=intersect(presmerge,presaxis);
%clear full

%% start to fill in data
ubgcparams=cat(1, {'PRES';'TEMP';'PSAL'},ubgcparams(:));

isynth=(1:length(presaxis))'; % index 1..length synthetic pressure axis
nos=length(isynth);
% DOXY/<PARAM> can sit in more than one N_PROF, so need to be a bit more
% clunky than just simply interpolating a single N_PROF which contains
% <PARAM>
%xpres=S.PRES.value(:,asort); % rearrange pressure obeying nprof priority
xpresqc=pflag(:,asort); % and flag to pressure that are not QC=4
synth.PRES.value=presaxis;

if isempty(presmerge) % core and presaxis empty
    for i=1:length(ubgcparams) % tap all with FillValue (avoid N_LEVEL dimension of 0)
        if ismember(ubgcparams{i},{'PRES'})
            synth.(ubgcparams{i}).value=int32(FV);
        else
            synth.(ubgcparams{i}).value=NaN;
        end
        synth.([ubgcparams{i} '_QC']).value=NaN;
        synth.([ubgcparams{i} '_ADJUSTED']).value=NaN;
        synth.([ubgcparams{i} '_ADJUSTED_QC']).value=NaN;
        synth.([ubgcparams{i} '_ADJUSTED_ERROR']).value=NaN;
        synth.([ubgcparams{i} '_dPRES']).value=NaN;
    end
    nosf=1;synthind=1; % avoid N_LEVEL dimension of 0 for BGC parameters
else
% fill in data in synthetic profile
for i=1:length(ubgcparams)
    
    if ismember(ubgcparams{i},{'PRES';'TEMP';'PSAL'}) % check which pressure axis to use
        sind=1:length(presmerge); % synthetic levels and full-HR PTS data for core
    else % BGC
        sind=synthind; % synthetic levels only
    end
    spresaxis=presmerge(sind); % pressure axis for current parameter
    spresaxis=spresaxis(:); % make sure it's a column vector
    
    if addoffsetflag
        %% re-apply vertical offset from scratch for particular parameter
        % e.g., N_PROF with SUNA & CTD has large offset for NITRATE, but none
        % for TEMP & PSAL, and only one S.PRES.value / inpres for both
        if ismember(ubgcparams{i},voff.linbgcparams)
            % check to which N_PROF the current parameter  fits
            ind=cellfun(@(x)ismember(ubgcparams{i},x),bgcparams);
            xpres=inpres0;
            xpres(:,ind)=xpres(:,ind)+int32(ones(noNLEVELs,1)*1e3*voff.linvoffset(ismember(voff.linbgcparams,ubgcparams{i})));
            xpres(inpres0==FV)=FV; % keep FV
            xpres=xpres(:,asort);
            clear ind
        else % no match found
            xpres=inpres0(:,asort); % keep original pressure
        end % found vertical offsets in config 
        if strcmp(ubgcparams{i},'PRES')
            xpres=inpres0(:,asort); % forget everything above, use all unadjusted pressures
            %xpres=S.PRES.value(:,asort); % forget everything above, use all unadjusted pressures
        end
    else % no addoffsetflag
        xpres=inpres0(:,asort); % keep original pressure
    end % addoffsetflag
    
    %% extract data
    y=S.(ubgcparams{i}).value(:,asort);
    yqc=S.([ubgcparams{i} '_QC']).value(:,asort);
    yadj=S.([ubgcparams{i} '_ADJUSTED']).value(:,asort);
    yadjqc=S.([ubgcparams{i} '_ADJUSTED_QC']).value(:,asort);
    yadjerr=S.([ubgcparams{i} '_ADJUSTED_ERROR']).value(:,asort);
    %% check for overlapping portion of N_PROFs
    if ismember(ubgcparams{i},{'PRES'})
        overlap=true(size(y)); % pressures of different N_PROFs (almost) necessarily overlap
        % get max and min ranges per nprof for adjusted anyway
        xrangeadj=ones(2,1+noNPROFs)*NaN;
        overlapadj=false(size(yadj)); % and flag portions that don't overlap for adjusted data
        for k=1:noNPROFs 
            % and adjusted
            %indadj=~isnan(yadj(:,k)) & xpresqc(:,k); % use only levels without FillValue and with useful PRES_QC
            indadj=(~isnan(yadj(:,k)) | ismember(yadjqc(:,k),4)) & xpresqc(:,k); % consider that adjusted_QC 4 may have FillValue adjusted data
            if any(indadj) % data in current nprof and with proper pres
                xrangeadj(:,1+k)=[min(xpres(indadj,k)); max(xpres(indadj,k))]; 
                % check if it should be added or not
                if isnan(xrangeadj(1,1)) % first nprof with data
                    xrangeadj(:,1)=xrangeadj(:,1+k);
                    overlapadj(:,k)=indadj;
                else % more than one nprof with data: keep only data outside existing range
                    overlapadj(:,k)=indadj & (xpres(:,k)>xrangeadj(2,1) | xpres(:,k)<xrangeadj(1,1));
                    xrangeadj(1,1)=min([xrangeadj(1,1) xrangeadj(1,1+k)]);
                    xrangeadj(2,1)=max([xrangeadj(2,1) xrangeadj(2,1+k)]);
                end
            end
        end % cycle all nprofs
        clear indadj xrangeadj
        
    else % not PRES
        % get max and min ranges per nprof
        xrange=ones(2,1+noNPROFs)*NaN;
        xrangeadj=ones(2,1+noNPROFs)*NaN;
        overlap=false(size(y)); % and flag portions that don't overlap
        overlapadj=false(size(yadj)); % and flag portions that don't overlap for adjusted data
        for k=1:noNPROFs 
            ind=~isnan(y(:,k)) & xpresqc(:,k);
            if any(ind) % data in current nprof and with proper pres
                xrange(:,1+k)=[min(xpres(ind,k)); max(xpres(ind,k))]; 
                % check if it should be added or not
                if isnan(xrange(1,1)) % first nprof with data
                    xrange(:,1)=xrange(:,1+k);
                    overlap(:,k)=ind;
                else % more than one nprof with data: keep only data outside existing range
                    overlap(:,k)=ind & (xpres(:,k)>xrange(2,1) | xpres(:,k)<xrange(1,1));
                    xrange(1,1)=min([xrange(1,1) xrange(1,1+k)]);
                    xrange(2,1)=max([xrange(2,1) xrange(2,1+k)]);
                end
            end
            % and adjusted
            %indadj=~isnan(yadj(:,k)) & xpresqc(:,k); % use only levels without FillValue and with useful PRES_QC
            indadj=(~isnan(yadj(:,k)) | ismember(yadjqc(:,k),4)) & xpresqc(:,k); % consider that adjusted_QC 4 may have FillValue adjusted data
            if any(indadj) % data in current nprof and with proper pres
                xrangeadj(:,1+k)=[min(xpres(indadj,k)); max(xpres(indadj,k))]; 
                % check if it should be added or not
                if isnan(xrangeadj(1,1)) % first nprof with data
                    xrangeadj(:,1)=xrangeadj(:,1+k);
                    overlapadj(:,k)=indadj;
                else % more than one nprof with data: keep only data outside existing range
                    overlapadj(:,k)=indadj & (xpres(:,k)>xrangeadj(2,1) | xpres(:,k)<xrangeadj(1,1));
                    xrangeadj(1,1)=min([xrangeadj(1,1) xrangeadj(1,1+k)]);
                    xrangeadj(2,1)=max([xrangeadj(2,1) xrangeadj(2,1+k)]);
                end
            end
        end % cycle all nprofs
        clear ind xrange indadj xrangeadj
    end % check for overlapping portion of N_PROFs PRES (int32/FV) or other style (double/NaN)
    %% do not use <PARAM>_QC of 8 or FillValue
    yflagqc=ismember(yqc,[0 1 2 3 4 5]);
    if ismember(ubgcparams{i},{'PRES'}), yflagnoFV=y~=FV; % double check PRES FV
    else, yflagnoFV=~isnan(y); end % and other FV (e.g., BR5900952_157, DOXY all NaN but QC=0)
    yflagadjqc=ismember(yadjqc,[0 1 2 3 4 5]);
    %yflagadjnoFV=~isnan(yadj); % double check FV, use only levels without FillValue
    yflagadjnoFV=~isnan(yadj) | ismember(yadjqc,4);  % double check FV, consider adjusted QC 4 as exception to FillValue
    
    %% clean up: only data of current parameter without QC 8, only pflag
    x=xpres(xpresqc & yflagqc & yflagnoFV);
    xadj=xpres(xpresqc & yflagadjqc & yflagadjnoFV);
    %xqc=xpresqc(xpresqc & yflagqc);
    y=y(xpresqc & yflagqc & yflagnoFV);
    yqc=yqc(xpresqc & yflagqc & yflagnoFV);
    yadj=yadj(xpresqc & yflagadjqc & yflagadjnoFV);
    yadjqc=yadjqc(xpresqc & yflagadjqc & yflagadjnoFV);
    yadjerr=yadjerr(xpresqc & yflagadjqc & yflagadjnoFV);
    overlapadj=overlapadj(xpresqc & yflagadjqc & yflagadjnoFV);
    overlap=overlap(xpresqc & yflagqc & yflagnoFV);
    yadjerrpresence=~all(isnan(yadjerr)); % error not mandatory for adjusted fields..
    clear yflagqc yflagnoFV yflagadjqc yflagadjnoFV
    
    %% preallocate
    if ismember(ubgcparams{i},{'PRES'})
        synth.(ubgcparams{i}).value=int32(ones(size(spresaxis))*FV);
    else
        synth.(ubgcparams{i}).value=double(spresaxis)*NaN;
    end
    synth.([ubgcparams{i} '_QC']).value=double(spresaxis)*NaN;
    synth.([ubgcparams{i} '_ADJUSTED']).value=double(spresaxis)*NaN;
    synth.([ubgcparams{i} '_ADJUSTED_QC']).value=double(spresaxis)*NaN;
    synth.([ubgcparams{i} '_ADJUSTED_ERROR']).value=double(spresaxis)*NaN;
    synth.([ubgcparams{i} '_dPRES']).value=int32(ones(size(spresaxis))*FV);
    
    if ismember(ubgcparams{i},{'PRES'}) % add synthetic levels (incl. vertical offsets of BGC sensors)
        synth.PRES.value(synthind)=presaxis;
    end
        
    if ~isempty(y) % not only NaN/FV data
        % use only non-overlapping portion 
        x=x(overlap);y=y(overlap);yqc=yqc(overlap);
        clear overlap
        % make monotonic for interpolation (looses nprof priority! But non-overlapping anyway)
        [~,ind]=sort(x); % monotonic sorting
        x=x(ind);y=y(ind);yqc=yqc(ind);
        % and make sure that they are column vectors
        x=x(:);y=y(:);yqc=yqc(:);
        % make monotonic and consolidate to unique values for interpolation (looses nprof priority! But non-overlapping anyway)
        [xunique,y]=consolidator(x,y,'nanmean'); % monotonic sorting and unique, nanmean data value
        yqc(yqc==5)=2.5; % replace QC 5 with 2.5: 
        [xunique,yqc]=consolidator(x,yqc,'max'); % monotonic sorting and unique, 'max' QC value
        yqc(yqc==2.5)=5; % replace QC 2.5 with 5 again: 
        x=int32(xunique); % ensure PRES is in int32 type
                
        %% copy data for levels that are part of the synthetic pressure axis:
        % get indices to which data to copy
        % take only 'first' occurence (in nprof-priority sorted record!) and
        % toss away repeated occurences (e.g., MD5904767_004.nc PSAL @ 46.0 dbar) 
        [~,fillind,cpind]=intersect(spresaxis,x);
        synth.(ubgcparams{i}).value(fillind)=y(cpind);
        synth.([ubgcparams{i} '_QC']).value(fillind)=yqc(cpind);
        synth.([ubgcparams{i} '_dPRES']).value(fillind)=0;
        %if ismember(ubgcparams{i},{'PRES';'TEMP';'PSAL'}) % keep which BGC PTS were truly measured for later
        %    full.(ubgcparams{i}).fillind=fillind;
        %end
        clear fillind cpind
        
        %% rest of data:
        % interpolate data for other levels of the synthetic pressure axis:
        % toss away repeated occurence of pressures: e.g., MD5904767_004.nc PSAL @ 46.0 dbar
        if ismember(ubgcparams{i},{'PRES'})
            [~,uind]=unique(x);
        else
            uind=1:length(x); % should have been dealt with by overlapping portions already
        end
        if length(x(uind))>1 
            % data interpolation: linear, no extrapolation
            synth.(ubgcparams{i}).value(isnan(synth.(ubgcparams{i}).value))=interp1(double(x(uind)),double(y(uind)),double(spresaxis(isnan(synth.(ubgcparams{i}).value))),'linear',NaN);
            % data extrapolation: nearest-neighbour, no limit on extrapolation
            if ~ismember(ubgcparams{i},{'PRES'}) % PRES extrapolation as nearest-neighbour does not work..
                synth.(ubgcparams{i}).value(isnan(synth.(ubgcparams{i}).value))=interp1(double(x(uind)),double(y(uind)),double(spresaxis(isnan(synth.(ubgcparams{i}).value))),'nearest','extrap');
            end % should not occur for PRES field, either..
            % deal with qc
            % qc interpolation: next and previous, no extrapolation
            qcnext=interp1(double(x(uind)),yqc(uind),double(spresaxis),'next',NaN);
            qcprevious=interp1(double(x(uind)),yqc(uind),double(spresaxis),'previous',NaN);
            % take maximum of QC; order 1 < 2 < 5 < 3 < 4
            qcnext(qcnext==5)=2.5; qcprevious(qcprevious==5)=2.5; % replace QC 5 with 2.5: 
            qcfill=max(qcnext,qcprevious); % max for interpolated QC
            synth.([ubgcparams{i} '_QC']).value(isnan(synth.([ubgcparams{i} '_QC']).value))=qcfill(isnan(synth.([ubgcparams{i} '_QC']).value));
            synth.([ubgcparams{i} '_QC']).value(synth.([ubgcparams{i} '_QC']).value==2.5)=5; % and reverse QC 5
            % qc extrapolation: nearest-neighbour, no limit on extrapolation
            synth.([ubgcparams{i} '_QC']).value(isnan(synth.([ubgcparams{i} '_QC']).value))=interp1(double(x(uind)),yqc(uind),double(spresaxis(isnan(synth.([ubgcparams{i} '_QC']).value))),'nearest','extrap');
            clear qcnext qcprevious qcfill
        else % only one value, keep this value as well as its QC, and place it closest to the original pressure
            [~,ifill]=min(abs(spresaxis-x(uind)));
            if ~ismember(ubgcparams{i},{'PRES'}) % PRES already dealt with (incl. vertical offsets), which shouldn't be overwritten
                synth.(ubgcparams{i}).value(ifill)=y(uind);
            end
            synth.([ubgcparams{i} '_QC']).value(ifill)=yqc(uind);
            if addTSeverywhere && ismember(ubgcparams{i},{'TEMP';'PSAL'})
                % extrapolate T and S context by replication, no limit on extrapolation
                synth.(ubgcparams{i}).value(:)=y(uind);
                synth.([ubgcparams{i} '_QC']).value(:)=yqc(uind);
            end
        end
        %% and kick out unmatched data
        %inomatch=false(nos,1); inomatch(setdiff(isynth,dsearchn(synth.PRES.value,x)))=1;
        % keep nearest data (can be two points) and remove all other that
        % are further away
        inomatch=true(length(spresaxis),1);
        if length(spresaxis)==1 % just one value on synthetic pressure axis
            %neardp=abs(synth.PRES.value-x(uind)); % on original sampling axis
            neardp=abs(spresaxis-x(uind)); % on original sampling axis
        else % more than one value on synthetic pressure axis
            %neardp=abs(synth.PRES.value(dsearchn(synth.PRES.value/1e3,x(uind)/1e3))-x(uind)); % on original sampling axis
            neardp=abs(spresaxis(dsearchn(double(spresaxis)/1e3,double(x(uind))/1e3))-x(uind)); % on original sampling axis
        end
        for k=1:length(uind)
            %inomatch(abs(synth.PRES.value-x(uind(k)))==neardp(k))=0; 
            inomatch(abs(spresaxis-x(uind(k)))==neardp(k))=0; 
        end
        %% decide which data to really remove
        iremove=inomatch;
        % keep all interpolated core-data within [max(pres)-2 dbar float length; min(pres)+1 dbar antenna length]
        if addTSeverywhere && ismember(ubgcparams{i},{'PRES';'TEMP';'PSAL'})
            if ismember(ubgcparams{i},{'PRES'})
                iremove(:)=0; % don't remove any interpolated/extrapolated PRES
            else % TEMP, PSAL
                % if there are valid data before or after, keep those in between, too
                %iremove(cumsum(~iremove,'forward')>0 & cumsum(~iremove,'reverse')>0)=0;
                % keep all within pressure range: extrapolate deepest data
                % point up to 1 float length (2 dbar) deeper and shallowest
                % data point up to 1 antenna length (1 dbar) shallower
                iremove(spresaxis<=max(x)+2*1000 & spresaxis>=min(x)-1*1000)=0;
            end
        end
        
        % keep an isolated hole between data
        % standard case: 1 isolated hole between two data before and after
        if nos>=5
            iremove(find(inomatch(3:nos-2) & ~inomatch(1:nos-4) & ~inomatch(2:nos-3) & ~inomatch(4:nos-1) & ~inomatch(5:nos))+2)=0;
        end
        if nos>=4
            % special case: 'data point # 2' and 'data point # end-1'
            iremove(find(inomatch(2) & ~inomatch(1) & ~inomatch(3) & ~inomatch(4))+1)=0;
            iremove(find(inomatch(nos-1) & ~inomatch(nos-3) & ~inomatch(nos-2) & ~inomatch(nos))+nos-2)=0;
        end
        if nos>2
            % special case: shallowest data point: up to 1 float length (2
            % dbar) and deepest data point: up to 1 antenna length (1 dbar)
            %iremove(find(inomatch(1) & ~inomatch(2) & ~inomatch(3) & diff(synth.PRES.value([1 2]))<=2*1000))=0;
            %iremove(find(inomatch(nos) & ~inomatch(nos-2) & ~inomatch(nos-1) & diff(synth.PRES.value([nos-1 nos]))<=1*1000)+nos-1)=0;
            iremove(find(inomatch(1) & ~inomatch(2) & ~inomatch(3) & diff(spresaxis([1 2]))<=2*1000))=0;
            iremove(find(inomatch(nos) & ~inomatch(nos-2) & ~inomatch(nos-1) & diff(spresaxis([nos-1 nos]))<=1*1000)+nos-1)=0;
        end
        
        if ismember(ubgcparams{i},{'PRES'})
            %synth.(ubgcparams{i}).value(iremove)=FV;
        else
            synth.(ubgcparams{i}).value(iremove)=NaN;
            synth.([ubgcparams{i} '_QC']).value(iremove)=NaN;
            %synth.([ubgcparams{i} '_dPRES']).value(iremove)=FV;
            % assign QC flag to gap in a series points
            %synth.([ubgcparams{i} '_QC']).value(inomatch & ~iremove)=8;
            %fillind=inomatch & ~iremove & ~ismember(synth.([ubgcparams{i} '_QC']).value,[3 4]);
            %fillind=inomatch & ~iremove & ~(ismember(synth.([ubgcparams{i} '_QC']).value,[3 4]) | isnan(synth.(ubgcparams{i} ).value));
            fillind=inomatch & ~iremove & ~(ismember(synth.([ubgcparams{i} '_QC']).value,[0 3 4]) | isnan(synth.(ubgcparams{i} ).value));
            synth.([ubgcparams{i} '_QC']).value(fillind)=8;
        end % PRES (int32) or not (double)
        clear y yqc uind inomatch iremove fillind
        
        %% check dPRES assignment
        % and add pressure difference where it is missing (and there are data)
        fillind=find(~isnan(synth.([ubgcparams{i} '_QC']).value) & synth.([ubgcparams{i} '_dPRES']).value==FV);
        % if there are two nearest samples, take the deeper one..
        for k=1:length(fillind)
            dp=x-spresaxis(fillind(k)); % deeper sample of minimum pressure difference
            synth.([ubgcparams{i} '_dPRES']).value(fillind(k))=dp(find(abs(dp)==min(abs(dp)),1,'last'));
            %%synth.([ubgcparams{i} '_dPRES']).value(synth.([ubgcparams{i} '_dPRES']).value==FV)=x(uind(nearind(synth.([ubgcparams{i} '_dPRES']).value==FV)))-spresaxis(synth.([ubgcparams{i} '_dPRES']).value==FV);
            %dpind=abs(x-spresaxis(k))==abs(x(uind(nearind(k)))-spresaxis(k)); % points with same distance and to be used (not in low priority nprofs)
            %synth.([ubgcparams{i} '_dPRES']).value(k)=max(x(dpind))-spresaxis(k); % take deeper value if there are any two samples at +/- the same distance
            %clear dpind
        end
        clear x xqc fillind dp
    
    if ~isempty(yadj) % not only NaN/FV adjusted data
        % use only non-overlapping portion 
        xadj=xadj(overlapadj);yadj=yadj(overlapadj);yadjqc=yadjqc(overlapadj);yadjerr=yadjerr(overlapadj);
        clear overlapadj
        % make monotonic for interpolation (looses nprof priority!)
        [~,ind]=sort(xadj); % monotonic sorting
        xadj=xadj(ind);yadj=yadj(ind);yadjqc=yadjqc(ind);yadjerr=yadjerr(ind);
        % and make sure that they are column vectors
        xadj=xadj(:);yadj=yadj(:);yadjqc=yadjqc(:);yadjerr=yadjerr(:);
        % make monotonic and consolidate to unique values for interpolation (looses nprof priority! But non-overlapping anyway)
        [xunique,yadj]=consolidator(xadj,yadj,'nanmean'); % monotonic sorting and unique, nanmean data value
        yadjqc(yadjqc==5)=2.5; % replace QC 5 with 2.5: 
        [~,yadjqc]=consolidator(xadj,yadjqc,'max'); % monotonic sorting and unique, 'max' QC value
        yadjqc(yadjqc==2.5)=5; % replace QC 2.5 with 5 again: 
        [~,yadjerr]=consolidator(xadj,yadjerr,'nanmean'); % monotonic sorting and unique, nanmean error value
        xadj=int32(xunique); % ensure PRES is in int32 type
        
        %% do the same with adjusted fields
        %% copy data for levels that are part of the synthetic pressure axis:
        [~,fillindadj,cpindadj]=intersect(spresaxis,xadj);
        synth.([ubgcparams{i} '_ADJUSTED']).value(fillindadj)=yadj(cpindadj);
        synth.([ubgcparams{i} '_ADJUSTED_QC']).value(fillindadj)=yadjqc(cpindadj);
        synth.([ubgcparams{i} '_ADJUSTED_ERROR']).value(fillindadj)=yadjerr(cpindadj);
        %if ismember(ubgcparams{i},{'PRES';'TEMP';'PSAL'}) % keep which BGC PTS were truly measured for later
        %    full.(ubgcparams{i}).fillindadj=fillindadj;
        %end
        clear fillindadj cpindadj
        
        %% rest of data:
        % interpolate data for other levels of the synthetic pressure axis:
        % toss away repeated occurence of pressures: e.g., MD5904767_004.nc PSAL @ 46.0 dbar
        if ismember(ubgcparams{i},{'PRES'})
            [~,uindadj]=unique(xadj);
        else
            uindadj=1:length(xadj); % should have been dealt with by overlapping portions already
        end
        if length(xadj(uindadj))>1
            % data interpolation: linear, no extrapolation
            synth.([ubgcparams{i} '_ADJUSTED']).value(isnan(synth.([ubgcparams{i} '_ADJUSTED']).value))=interp1(double(xadj(uindadj)),double(yadj(uindadj)),double(spresaxis(isnan(synth.([ubgcparams{i} '_ADJUSTED']).value))),'linear',NaN);
            % data extrapolation: nearest-neighbour, no limit on extrapolation
            if ismember(ubgcparams{i},{'PRES'}) % PRES_ADJUSTED extrapolation as nearest-neighbour does not work.. use linear extrapolation
                synth.([ubgcparams{i} '_ADJUSTED']).value(isnan(synth.([ubgcparams{i} '_ADJUSTED']).value))=interp1(double(xadj(uindadj)),double(yadj(uindadj)),double(spresaxis(isnan(synth.([ubgcparams{i} '_ADJUSTED']).value))),'linear','extrap');
            else % nearest-neighbour
                synth.([ubgcparams{i} '_ADJUSTED']).value(isnan(synth.([ubgcparams{i} '_ADJUSTED']).value))=interp1(double(xadj(uindadj)),double(yadj(uindadj)),double(spresaxis(isnan(synth.([ubgcparams{i} '_ADJUSTED']).value))),'nearest','extrap');
            end
            if yadjerrpresence % same with errors if any
                synth.([ubgcparams{i} '_ADJUSTED_ERROR']).value(isnan(synth.([ubgcparams{i} '_ADJUSTED_ERROR']).value))=interp1(double(xadj(uindadj)),double(yadjerr(uindadj)),double(spresaxis(isnan(synth.([ubgcparams{i} '_ADJUSTED_ERROR']).value))),'linear',NaN);
                synth.([ubgcparams{i} '_ADJUSTED_ERROR']).value(isnan(synth.([ubgcparams{i} '_ADJUSTED_ERROR']).value))=interp1(double(xadj(uindadj)),double(yadjerr(uindadj)),double(spresaxis(isnan(synth.([ubgcparams{i} '_ADJUSTED_ERROR']).value))),'nearest','extrap');
            end
            % deal with qc
            % qc interpolation: next and previous, no extrapolation
            qcnextadj=interp1(double(xadj(uindadj)),yadjqc(uindadj),double(spresaxis),'next',NaN);
            qcpreviousadj=interp1(double(xadj(uindadj)),yadjqc(uindadj),double(spresaxis),'previous',NaN);
            % take maximum of QC; order 1 < 2 < 5 < 3 < 4
            qcnextadj(qcnextadj==5)=2.5; qcpreviousadj(qcpreviousadj==5)=2.5; % replace QC 5 with 2.5: 
            qcfilladj=max(qcnextadj,qcpreviousadj); % max for interpolated QC
            synth.([ubgcparams{i} '_ADJUSTED_QC']).value(isnan(synth.([ubgcparams{i} '_ADJUSTED_QC']).value))=qcfilladj(isnan(synth.([ubgcparams{i} '_ADJUSTED_QC']).value));
            synth.([ubgcparams{i} '_ADJUSTED_QC']).value(synth.([ubgcparams{i} '_ADJUSTED_QC']).value==2.5)=5; % and reverse QC 5
            % qc extrapolation: nearest-neighbour, no limit on extrapolation
            synth.([ubgcparams{i} '_ADJUSTED_QC']).value(isnan(synth.([ubgcparams{i} '_ADJUSTED_QC']).value))=interp1(double(xadj(uindadj)),yadjqc(uindadj),double(spresaxis(isnan(synth.([ubgcparams{i} '_ADJUSTED_QC']).value))),'nearest','extrap');
            clear qcnextadj qcpreviousadj qcfilladj
        elseif ~isempty(xadj) % only one value, keep this value, its error, and its QC, and place it closest to the original pressure
            [~,ifill]=min(abs(spresaxis-xadj));
            synth.([ubgcparams{i} '_ADJUSTED']).value(ifill)=yadj(uindadj);
            if yadjerrpresence % same with errors if any
                synth.([ubgcparams{i} '_ADJUSTED_ERROR']).value(ifill)=yadjerr(uindadj);
            end
            synth.([ubgcparams{i} '_ADJUSTED_QC']).value(ifill)=yadjqc(uindadj);
        else % no adjusted value left from overlapping portions
            % do nothing
        end    
        %% and kick out unmatched data
        inomatch=true(length(spresaxis),1);
        %neardp=abs(synth.PRES.value(dsearchn(synth.PRES.value/1e3,xadj(uindadj)/1e3))-xadj(uindadj)); % on original sampling axis
        neardp=abs(spresaxis(dsearchn(double(spresaxis)/1e3,double(xadj(uindadj))/1e3))-xadj(uindadj)); % on original sampling axis
        for k=1:length(uindadj)
            %inomatch(abs(synth.PRES.value-xadj(uindadj(k)))==neardp(k))=0; 
            inomatch(abs(spresaxis-xadj(uindadj(k)))==neardp(k))=0; 
        end
        %% decide which data to really remove
        iremove=inomatch;
        % keep all interpolated core-data within [max(pres)-2 dbar float length; min(pres)+1 dbar antenna length]
        if addTSeverywhere && ismember(ubgcparams{i},{'PRES';'TEMP';'PSAL'})
            if ismember(ubgcparams{i},{'PRES'})
                iremove(:)=0; % don't remove any interpolated/extrapolated PRES_ADJUSTED
            else % TEMP, PSAL
                % if there are valid data before or after, keep those in between, too
                %iremove(cumsum(~iremove,'forward')>0 & cumsum(~iremove,'reverse')>0)=0;
                % keep all within pressure range: extrapolate deepest data
                % point up to 1 float length (2 dbar) deeper and shallowest
                % data point up to 1 antenna length (1 dbar) shallower
                iremove(spresaxis<=max(xadj)+2*1000 & spresaxis>=min(xadj)-1*1000)=0;
            end
        end
        
        % but only if it's not an isolated hole between data
        % standard case: 1 isolated hole between two data before and after
        if nos>=5
            iremove(find(inomatch(3:nos-2) & ~inomatch(1:nos-4) & ~inomatch(2:nos-3) & ~inomatch(4:nos-1) & ~inomatch(5:nos))+2)=0;
        end
        if nos>=4
            % special case: 'data point # 2' and 'data point # end-1'
            iremove(find(inomatch(2) & ~inomatch(1) & ~inomatch(3) & ~inomatch(4))+1)=0;
            iremove(find(inomatch(nos-1) & ~inomatch(nos-3) & ~inomatch(nos-2) & ~inomatch(nos))+nos-2)=0;
        end
        if nos>2
            % special case: shallowest data point: up to 1 float length (2
            % dbar) and deepest data point: up to 1 antenna length (1 dbar)
            %iremove(find(inomatch(1) & ~inomatch(2) & ~inomatch(3) & diff(synth.PRES.value([1 2]))<=2*1000))=0;
            %iremove(find(inomatch(nos) & ~inomatch(nos-2) & ~inomatch(nos-1) & diff(synth.PRES.value([nos-1 nos]))<=1*1000)+nos-1)=0;
            iremove(find(inomatch(1) & ~inomatch(2) & ~inomatch(3) & diff(spresaxis([1 2]))<=2*1000))=0;
            iremove(find(inomatch(nos) & ~inomatch(nos-2) & ~inomatch(nos-1) & diff(spresaxis([nos-1 nos]))<=1*1000)+nos-1)=0;
        end
        %if ismember(ubgcparams{i},{'PRES'})
        %    synth.(ubgcparams{i}).value(iremove)=FV;
        %else
        synth.([ubgcparams{i} '_ADJUSTED']).value(iremove)=NaN;
        %end % PRES (int32) or not (double)
        synth.([ubgcparams{i} '_ADJUSTED_QC']).value(iremove)=NaN;
        % assign QC flag to gap in a series points
        %synth.([ubgcparams{i} '_ADJUSTED_QC']).value(inomatch & ~iremove)=8;
        %fillind=inomatch & ~iremove & ~ismember(synth.([ubgcparams{i} '_ADJUSTED_QC']).value,[3 4]);
        %fillind=inomatch & ~iremove & ~(ismember(synth.([ubgcparams{i} '_ADJUSTED_QC']).value,[3 4]) | isnan(synth.([ubgcparams{i} '_ADJUSTED']).value));
        fillind=inomatch & ~iremove & ~(ismember(synth.([ubgcparams{i} '_ADJUSTED_QC']).value,[0 3 4]) | isnan(synth.([ubgcparams{i} '_ADJUSTED']).value));
        if ~ismember(ubgcparams{i},{'PRES'}) % don't tap with '8' for PRES_ADJUSTED: location, not really data
        synth.([ubgcparams{i} '_ADJUSTED_QC']).value(fillind)=8;
        end
        synth.([ubgcparams{i} '_ADJUSTED_ERROR']).value(iremove)=NaN;
        clear xadj xadjqc yadj yadjqc yadjerr yadjerrpresence uindadj inomatch fillind
    end % ~isempty(yadj) : some adjusted data available
    end % ~isempty(y) : some data available
    %% and convert parameter dPRES back to proper 1/1000 double
    fillind=synth.([ubgcparams{i} '_dPRES']).value==FV;
	synth.([ubgcparams{i} '_dPRES']).value=double(synth.([ubgcparams{i} '_dPRES']).value)./1000;
    synth.([ubgcparams{i} '_dPRES']).value(fillind)=NaN;
    clear fillind
end % fill in data in synthetic profile

end % core and presaxis empty


%% add synthetic profile to merged data with full dimension, BGC levels interleaved
fnames=fieldnames(synth); % use non-interleaved profile as template; fill gaps with NaN
%for i=2:length(fnames) % start at index 2: first one is PRES=presaxis -> already present
for i=1:length(fnames) % start at index 1: first one is PRES=presmerge -> copy all to be sure
    synthfull.(fnames{i}).value=ones(nosf,1)*NaN;
    if ismember(fnames{i},{'PRES';'TEMP';'PSAL';'PRES_QC';'TEMP_QC';'PSAL_QC';'PRES_ADJUSTED';'TEMP_ADJUSTED';'PSAL_ADJUSTED';'PRES_ADJUSTED_QC';'TEMP_ADJUSTED_QC';'PSAL_ADJUSTED_QC';'PRES_ADJUSTED_ERROR';'TEMP_ADJUSTED_ERROR';'PSAL_ADJUSTED_ERROR';'PRES_dPRES';'TEMP_dPRES';'PSAL_dPRES'}) % core already on full axis
        synthfull.(fnames{i}).value=synth.(fnames{i}).value;
    else % BGC on synthetic pressure axis
        synthfull.(fnames{i}).value(synthind)=synth.(fnames{i}).value;
    end % already on full axis (core)?
end % cycle fields

%% and convert PRES back to proper 1/1000 double
fillind=synthfull.PRES.value==FV;
synthfull.PRES.value=double(synthfull.PRES.value)./1000;
synthfull.PRES.value(fillind)=NaN;

%% sanity-check ADJUSTED_QC in case of ADJUSTED=FV
for i=1:length(ubgcparams)
    if ~all(isnan(synthfull.([ubgcparams{i} '_ADJUSTED']).value)) && ~all(isnan(synthfull.([ubgcparams{i} '_ADJUSTED_QC']).value))
        fillind=~isnan(synthfull.(ubgcparams{i}).value) & isnan(synthfull.([ubgcparams{i} '_ADJUSTED']).value) & isnan(synthfull.([ubgcparams{i} '_ADJUSTED_QC']).value);
        synthfull.([ubgcparams{i} '_ADJUSTED_QC']).value(fillind)=4;
    end % adjusted data or adjusted_QC are present?
end

return

%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%

function S=lov_netcdf_pickprod(filename,varargin)
%
%
% loads oao lovbio profile netcdf files
%
% inspired by SDS_pickprod from Heidi Dierssen, UConn
% adapted for netcdf files
% Henry Bittig, GEOMAR
% 10.10.2013
% 31.10.2016, LOV, more specific adaptations to Argo netcdf files (QC field
%             data type and option to load only specific fields)
% 10.01.2019, IOW, modified to include dimension information
%
% input:
% filename - (path &) filename of netcdf file
% loadflag - 0 or 1 to indicate to actually load the data or not (optional)
%            (relevant for large files' attribute exploration without data
%            usage)
% fnames   - cellstr of field names that are to be loaded into S; all other
%            variables are ignored (optional)
%
% usage:
% S=lov_netcdf_pickprod('test.nc');
% S=lov_netcdf_pickprod('test.nc',0);
% S=lov_netcdf_pickprod('test.nc',{'VAR1';'VAR2'});
% S=lov_netcdf_pickprod('test.nc',{'VAR1';'VAR2'},0);


%
% Script for reading in SDS hdf datafile
%  And finding the number datasets and names of datasets within
%    the file.
%INPUT:  filename = '   '
%
%OUTPUT: 2 structural arrays
% SDS_info = global attributes
% SDS_prod = dataset names numbered

clear SDS_prod SDS_info



tmp=cellfun(@isnumeric,varargin);
if any(tmp) 
   loadflag = varargin{tmp};
   varargin = varargin(~tmp); 
else
    loadflag=1;
end

if ~isempty(varargin)
    fnames=varargin{1};
    % and add '^' to mark that regexp needs to start from start of varname
    % and add '$' to mark its end
    fnames=cellfun(@(x)['^' x '$'],fnames,'uniform',0);
else
    fnames=[];
end

%% start access to the file
ncid=netcdf.open(filename,'NC_NOWRITE');
if ncid == -1;
   error('ERROR: bad ncid');
end

%% file info
[ndims,nvariables,nglobal_attr,unlimdim_id] = netcdf.inq(ncid);

Info = ''; %Descrip of all the file attributes

% get global attributes if present
[f1,f2]=fileparts(filename);
SDS_info.GLOBAL.path=f1;
SDS_info.GLOBAL.filename=f2;
if nglobal_attr>0
    i=netcdf.getConstant('NC_GLOBAL')+1; % VarID global = -1; 
    for j=1:nglobal_attr
        nameatt=netcdf.inqAttName(ncid,i-1,j-1);
        [xtype_att,attlen] = netcdf.inqAtt(ncid,i-1,nameatt);
        valueatt=netcdf.getAtt(ncid,i-1,nameatt);
        %% convert to double precision
        if xtype_att>4
            valueatt = double(valueatt);
        end
        %% convert spaces, hyphens, slashes to underscores
        %nameatt=strrep(nameatt,'_FillValue','FillValue');
        if strncmp(nameatt,'_',1), nameatt=nameatt(2:end); end
        nameatt = strrep(nameatt,' ','_');
        nameatt=strrep(nameatt,'-','_');
        nameatt=strrep(nameatt,'/','_');
        nameatt=strrep(nameatt,'.','_');
        % 
        SDS_info.GLOBAL.(nameatt)=valueatt;
    end
end

% get dimensions
if ndims>0
    for j=1:ndims
        [nameatt,attlen] = netcdf.inqDim(ncid,j-1);
        %valueatt=netcdf.getAtt(ncid,i-1,nameatt);
        %% convert spaces, hyphens, slashes to underscores
        %nameatt=strrep(nameatt,'_FillValue','FillValue');
        if strncmp(nameatt,'_',1), nameatt=nameatt(2:end); end
        nameatt = strrep(nameatt,' ','_');
        nameatt=strrep(nameatt,'-','_');
        nameatt=strrep(nameatt,'/','_');
        nameatt=strrep(nameatt,'.','_');
        % 
        SDS_info.GLOBAL.dims.(nameatt)=attlen;        
    end
end

%% get all data sets
for i = 1:nvariables;
    [name,data_type,dimids,natts]=netcdf.inqVar(ncid,i-1);
    %% convert spaces, hyphens, slashes to underscores
       name = strrep(name,' ','_');
       name=strrep(name,'-','_');
       name=strrep(name,'/','_');
       name=strrep(name,'.','_');
    %% check if data set names are limited and if so, whether current one is to load
    %if isempty(fnames) || any(strcmp(fnames,name))
    if isempty(fnames) || any(~cellfun(@isempty,regexp(name,fnames,'match')));
    %% get variable attributes value
    for j=1:natts
        nameatt=netcdf.inqAttName(ncid,i-1,j-1);
        [xtype_att,attlen] = netcdf.inqAtt(ncid,i-1,nameatt);
        valueatt=netcdf.getAtt(ncid,i-1,nameatt);
        %% convert to double precision
        if xtype_att>4
            valueatt = double(valueatt);
        end
        %% convert spaces, hyphens, slashes to underscores
        nameatt=strrep(nameatt,'_FillValue','FillValue');
        nameatt = strrep(nameatt,' ','_');
        nameatt=strrep(nameatt,'-','_');
        nameatt=strrep(nameatt,'/','_');
        nameatt=strrep(nameatt,'.','_');
        if nameatt(1)=='_', nameatt=nameatt(2:end); end
        % 
        SDS_info.(name).(nameatt)=valueatt;
    end
    %% get variable dimension names and values
    [a,b]=arrayfun(@(x)netcdf.inqDim(ncid,x),dimids,'uniform',0);
    SDS_info.(name).dimname=a;
    SDS_info.(name).dimvalue=cell2mat(b);
    if loadflag % actually load the data
    % get variable value
    SDS_info.(name).value=netcdf.getVar(ncid,i-1);
    % and replace FillValue with NaN
    if data_type>2
        try
            SDS_info.(name).value(SDS_info.(name).FillValue==SDS_info.(name).value)=NaN;
        catch me
            warning off
            SDS_info.(name).value(99999==SDS_info.(name).value)=NaN;
            SDS_info.(name).value(9.969209968386869e+36==SDS_info.(name).value)=NaN;
            %warning on
            %disp(['no FillValue available for ' name ])
        end
        try
            SDS_info.(name).value(SDS_info.(name).missing_value==SDS_info.(name).value)=NaN;
        catch me
            
        end
    end
    % and tidy up result 
    if data_type==2 & (isempty(strfind(name,'QC')) | ~isempty(strfind(name,'QCTEST'))) % flip character arrays if not QC field
        try
            SDS_info.(name).value=SDS_info.(name).value';
            SDS_info.(name).dimname=SDS_info.(name).dimname([2 1]);
            SDS_info.(name).dimvalue=SDS_info.(name).dimvalue([2 1]);
        catch me
        end

    elseif data_type<3 & isempty(strfind(name,'PROFILE')) % make double for data QC "string" fields
        SDS_info.(name).value=double(SDS_info.(name).value)-double('0');
        SDS_info.(name).value(SDS_info.(name).value==-16)=NaN; % double(' ')-double('0')=-16;
    elseif data_type>4 % make double for float, double, 
        SDS_info.(name).value=double(SDS_info.(name).value);
%{
    elseif data_type<3 % make double and sparse for QC "string" fields
        SDS_info.(name).value=sparse(double(SDS_info.(name).value));
	elseif data_type>4 % make double and sparse for float and double fields
        SDS_info.(name).value=glsparse(double(SDS_info.(name).value));
%}
    end % tidy up
    end % loadflag
    end % check field names
%{       
  %% convert to double precision
  if strcmp(class(value),'single') == 1
      value = double(value);
  end
  
  if strcmp(class(value),'struct') == 1
   %% put number place holder
     SDS_info.(name) =  i;
  else
      SDS_info.(name) =  value;
  end
    %}
end
netcdf.close(ncid);

%{
%---pick dataset
for jj=0:(ndatasets-1);
sds_index=jj;
sds_id=hdfsd('select',ncid,sds_index);
[name,rank,dimsizes,data_type,nattrs,status]=hdfsd('getinfo',sds_id);
   %% convert spaces, hyphens, slashes to underscores
      name = strrep(name,' ','_');
      name=strrep(name,'-','_');
      name=strrep(name,'/','_');
      name=strrep(name,'.','_');
SDS_prod.(name) =  jj;
end

%% end access to dataset
status = hdfsd('endaccess',sds_id);
if status == -1;
   error('ERROR: bad end access to dataset');
end

%% end access to the file
status = hdfsd('end',ncid);
if status == -1;
   error('ERROR: bad end access to file');
end
%}

S=SDS_info;

clear cb cm ax pc ratio x y plot ti top base slope intercept name value j
clear li ans i sds_id sds_index status rank nattrs ndatasets 
clear dimsizes edge nglobal_attr data_type count name bottom top
clear lat_step lon_step vrbl dellat

return

%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%

function [xcon,ycon,ind] = consolidator(x,y,aggregation_mode,tol)
% consolidator: consolidate "replicates" in x, also aggregate corresponding y
% usage: [xcon,ycon,ind] = consolidator(x,y,aggregation_mode,tol)
%
% arguments: (input)
%  x - rectangular array of data to be consolidated. If multiple (p)
%      columns, then each row of x is interpreted as a single point in a
%      p-dimensional space. (x may be character, in which case xcon will
%      be returned as a character array.)
%
%      x CANNOT be complex. If you do have complex data, split it into
%      real and imaginary components as columns of an array.
%
%      If x and y are both ROW vctors, they will be transposed and
%      treated as single columns.
%
%  y - outputs to be aggregated. If y is not supplied (is left empty)
%      then consolidator is similar to unique(x,'rows'), but with a
%      tolerance on which points are distinct. (y may be complex.)
%
%      y MUST have the same number of rows as x unless y is empty.
%
%  aggregation_mode - (OPTIONAL) - an aggregation function, either
%      in the form of a function name, such as 'mean' or 'sum', or as
%      a function handle, i.e., @mean or @std. An inline function would
%      also work, for those users of older matlab releases.
%
%      DEFAULT: 'mean'
%
%      Aggregation_mode may also be the string 'count', in which case
%      a count is made of the replicates found. Ycon will only have
%      one column in this case.
%      
%      The function supplied MUST have the property that it operates
%      on the the first dimension of its input by default.
%
%      Common functions one might use here are:
%      'mean', 'sum', 'median', 'min', 'max', 'std', 'var', 'prod'
%      'geomean', 'harmmean'.
%
%      These last two examples would utilize the statistics toolbox,
%      however, these means can be generated using a function
%      handle easily enough if that toolbox is not available:
%
%      fun = @(x) 1./mean(1./x)        % harmonic mean
%      fun = @(x) exp(mean(log(x)))    % geometric mean
%
%  tol - (OPTIONAL) tolerance to identify replicate elements of x. If
%      x has multiple columns, then the same (absolute) tolerance is
%      applied to all columns of x.
%
%      DEFAULT: 0
%
% arguments: (output)
%  xcon - consolidated x. Replicates wthin the tolerance are removed.
%      if no y was specified, then consolidation is still done on x.
%
%  ycon - aggregated value as specified by the aggregation_mode.
%
%  ind  - vector - denotes the elements of the original array which
%      were consolidated into each element of the result.
%
%
% Example 1:
%
% Group means: (using a function handle for the aggregation)
%  x = round(rand(1000,1)*5);
%  y = x+randn(size(x));
%  [xg,yg] = consolidator(x,y,@mean);
%  [xg,yg]
%  ans =
%         0    0.1668
%    1.0000    0.9678
%    2.0000    2.0829
%    3.0000    2.9688
%    4.0000    4.0491
%    5.0000    4.8852
%
% Example 2:
%
% Group counts on x
%  x = round(randn(100000,1));
%  [xg,c] = consolidator(x,[],'count');
%  [xg,c]
%  ans =
%         -4          26
%         -3         633
%         -2        5926
%         -1       24391
%          0       38306
%          1       24156
%          2        5982
%          3         559
%          4          21
%
% Example 3:
%
% Unique(x,'rows'), but with a tolerance
%  x = rand(100,2);
%  xc = consolidator(x,[],[],.05);
%  size(xc)
%  ans =
%      62     2
%
% See also: unique
%
% Author: John D'Errico
% e-mail address: woodchips@rochester.rr.com
% Release: 3
% Release date: 5/2/06

% is it a character array?
if ischar(x)
  charflag = 1;
  x=double(x);
else
  charflag = 0;
end

% check for/supply defaults
if (nargin<4) || isempty(tol)
  tol = 0;
end
if (tol<0)
  error 'Tolerance must be non-negative.'
end
tol = tol*(1+10*eps);

% -------------------------------------------------------
% DETERMINE AGGREGATION MODE AND CREATE A FUNCTION HANDLE
% -------------------------------------------------------
if (nargin < 3) || isempty(aggregation_mode)
 	% use default function
  fun=@mean;
  aggregation_mode='mean';
  
elseif ischar(aggregation_mode)
	aggregation_mode=lower(aggregation_mode);

  k=strmatch(aggregation_mode,'count');
  if ~isempty(k)
    fun=@(x) x;
	else
		fun=str2func(aggregation_mode);
  end
  
elseif isa(aggregation_mode,'inline')
  fun=aggregation_mode;
  am = struct(fun);
  aggregation_mode=am.expr;
  
else
  fun=aggregation_mode;
  aggregation_mode=func2str(fun);
  
end
% -------------------------------------------------------

% was y supplied, or empty?
[n,p] = size(x);
if (nargin<2) || isempty(y)
  y = zeros(n,0);
  fun = @(x) x;
  aggregation_mode = 'count';
end
% check for mismatch between x and y
[junk,q] = size(y);
if n~=junk
  error 'y must have the same number of rows as x.'
end

% are both x and y row vectors?
if (n == 1)
  x=x';
  n = length(x);
  p = 1;
  
  if ~isempty(y)
    y=y';
  else
    y=zeros(n,0);
  end
  
  q = size(y,2);
end

if isempty(y)
  aggregation_mode = 'count';
end

% consolidate elements of x.
% first shift, scale, and then ceil. 
if tol>0
  xhat = x - repmat(min(x,[],1),n,1)+tol*eps;
  xhat = ceil(xhat/tol);
else
  xhat = x;
end
[xhat,tags] = sortrows(xhat);
x=x(tags,:);
y=y(tags,:);

% count the replicates
iu = [true;any(diff(xhat),2)];
eb = cumsum(iu);

% which original elements went where?
if nargout>2
  ind = eb;
  ind(tags) = ind;
end

% count is the vector of counts for the consolidated
% x values
if issparse(eb)
  eb = full(eb);
end
count=accumarray(eb,1).';
% ec is the expanded counts, i.e., counts for the
% unconsolidated x
ec = count(eb);

% special case for aggregation_mode of 'count',
% but we still need to aggregate (using the mean) on x
if strcmp(aggregation_mode,'count')
  ycon = count.';
  q = 0;   % turn off aggregation on y
else
  ycon = zeros(length(count),q);
end

% loop over the different replicate counts, aggregate x and y
ucount = unique(count);
xcon = repmat(NaN,[length(count),p]);
fullx = ~issparse(x);
fully = ~issparse(y);
for k=ucount
  if k==1
    xcon(count==1,:) = x(ec==1,:);
  else
    if fullx
      v=permute(x(ec==k,:),[3 2 1]);
    else
      v=permute(full(x(ec==k,:)),[3 2 1]);
    end
    v=reshape(v,p,k,[]);
    v=permute(v,[2 1 3]);
    xcon(count==k,:)=reshape(nanmean(v),p,[]).';
  end
  
  if q>0
    % aggregate y as specified
    if k==1
      switch aggregation_mode
        case {'std' 'var'}
          ycon(count==1,:) = 0;
        otherwise
          ycon(count==1,:) = y(ec==1,:);
      end
    else
      if fully
        v=permute(y(ec==k,:),[3 2 1]);
      else
        v=permute(full(y(ec==k,:)),[3 2 1]);
      end
      v=reshape(v,q,k,[]);
      v=permute(v,[2 1 3]);
      
      % aggregate using the appropriate function
      ycon(count==k,:)=reshape(fun(v),q,[]).';
      
    end
  end
end

% was it originally a character array?
if charflag
  xcon=char(xcon);
end

return

